
/* =====================================================================
   ORG.JS — organisation, identity, site scoping and the ANTS adapter
   ---------------------------------------------------------------------
   Loaded BEFORE every other DRS module.

   1. ANTS ADAPTER (window.ANTS)
      DRS never keeps its own animals, sites or staff. It asks ANTS.
      In the demo, window.ANTS is a built-in SAMPLE (clusters V1–V5, sites S1…).
      In the real build the ANTS team defines window.ANTS before this file
      (or the connector does), implementing the same functions:
        ANTS.clusters()            -> [{code,name,sites:[{code,name,cluster,zones:[{code,enclosures:[code]}]}]}]
        ANTS.staff()               -> [{uid,name,ep,antsRole,role,cluster,site,zone,agency?}]
        ANTS.animals(site)         -> [{id,name,species,site,zone,enclosure,sex,dob}]
        ANTS.history(animalId)     -> {weights:[{date,kg}],bcs:[{date,score}],vacc:[{date,type,by}],events:[{date,text}]}
        ANTS.schedules(site)       -> [{id,animalId,animal,species,enclosure,type,due}]   (vaccination / deworming)
        ANTS.record(kind,payload)  -> {ok,ref}   kind: "birth" | "death" | "vaccination-done"
        ANTS.login(user,pass)      -> {uid,token}   (real build only)

   2. IDENTITY — who is signed in (uid), their DRS role, cluster, site, zone.
   3. SITE SCOPING — every DRS key is stored per site ("@V1S2/kc-issues"),
      per user ("@u:EP1001/kc-read") or globally. This keeps each site's
      lists small (5,000+ users / 50 sites) and keeps sites' data apart.
   4. CLOCK — NOW() with a demo-only fast-forward for showing reminders,
      escalations and missed time targets.
   ===================================================================== */
(function () {
  "use strict";
  /* ---------- deterministic random (same demo data on every phone) ---------- */
  function rng(seed) { let h = 1779033703 ^ seed.length; for (let i = 0; i < seed.length; i++) { h = Math.imul(h ^ seed.charCodeAt(i), 3432918353); h = h << 13 | h >>> 19; }
    return function () { h = Math.imul(h ^ h >>> 16, 2246822507); h = Math.imul(h ^ h >>> 13, 3266489909); h ^= h >>> 16; return (h >>> 0) / 4294967296; }; }
  const pick = (r, a) => a[Math.floor(r() * a.length)];
  const pad = (n, w) => String(n).padStart(w, "0");
  const today = (() => { const d = new Date(); return d.getFullYear() + "-" + pad(d.getMonth() + 1, 2) + "-" + pad(d.getDate(), 2); })();
  const addD = (k, n) => { const d = new Date(k + "T12:00:00"); d.setDate(d.getDate() + n); return d.toISOString().slice(0, 10); };

  /* ---------- ANTS job titles -> DRS roles (edit to match ANTS exactly) ---------- */
  const ANTS_ROLE_MAP = {
    "Chief Executive Officer": "exec", "Chief Operating Officer": "exec", "Cluster Head": "ch",
    "Site Manager": "mgr", "Curator": "cur", "Assistant Curator": "acur", "Biologist": "bio",
    "Veterinarian": "vet", "Paravet": "pvet", "Assistant Facility Manager": "afm",
    "Head Animal Keeper": "sup", "Site Supervisor": "sup", "Animal Keeper": "keeper", "Night Keeper": "keeper",
    "DRS Super Admin": "sadmin", "DRS Site Admin": "siteadmin", "Maintenance Agency": "agency"
  };

  /* ---------- SAMPLE ANTS (demo only) ---------- */
  const CLUSTER_SIZES = [10, 9, 10, 8, 3];          /* sites per cluster: 2–10, not fixed */
  const FIRST = ["Ravi", "Amit", "Sunita", "Pooja", "Kiran", "Meena", "Rahul", "Neha", "Vikram", "Asha", "Suresh", "Kavita", "Manoj", "Divya", "Arjun", "Lata", "Imran", "Farah", "Joseph", "Anita", "Deepak", "Rekha", "Sanjay", "Priya", "Harish", "Geeta", "Naveen", "Sapna", "Rakesh", "Uma"];
  const SPECIES = [["Bengal tiger", 1, 3], ["Asian elephant", 1, 4], ["Indian leopard", 1, 2], ["Asiatic lion", 2, 4], ["Blackbuck", 6, 14], ["Spotted deer", 8, 20], ["Nilgai", 3, 8], ["Sloth bear", 1, 3], ["Gharial", 3, 8], ["Mugger crocodile", 2, 6], ["Indian rhinoceros", 1, 2], ["Sarus crane", 2, 4], ["Indian star tortoise", 6, 20], ["Hoolock gibbon", 2, 4], ["Lion-tailed macaque", 4, 9], ["Red panda", 1, 3], ["Indian rock python", 1, 3], ["Striped hyena", 2, 4], ["Indian peafowl", 4, 10], ["Himalayan black bear", 1, 2]];
  const NAMES = ["Raja", "Rani", "Moti", "Shera", "Gauri", "Bholu", "Chinu", "Mira", "Tara", "Kali", "Sultan", "Leela", "Bijli", "Sheru", "Champa", "Badal", "Heera", "Juhi", "Kesar", "Laddu", "Munna", "Noor", "Pari", "Rocky", "Sona", "Toofan", "Veer", "Zara"];
  const BIG = ["Bengal tiger", "Asian elephant", "Indian leopard", "Asiatic lion", "Sloth bear", "Indian rhinoceros", "Red panda", "Himalayan black bear", "Hoolock gibbon", "Striped hyena"];
  const KG = { "Bengal tiger": 190, "Asian elephant": 3200, "Indian leopard": 55, "Asiatic lion": 160, "Blackbuck": 35, "Spotted deer": 70, "Nilgai": 220, "Sloth bear": 110, "Gharial": 140, "Mugger crocodile": 200, "Indian rhinoceros": 2100, "Sarus crane": 7, "Indian star tortoise": 1.5, "Hoolock gibbon": 7, "Lion-tailed macaque": 8, "Red panda": 5, "Indian rock python": 45, "Striped hyena": 35, "Indian peafowl": 4, "Himalayan black bear": 120 };

  let _clusters = null, _staff = null; const _animals = {};
  function clusters() {
    if (_clusters) return _clusters;
    _clusters = CLUSTER_SIZES.map((n, ci) => {
      const cc = "V" + (ci + 1);
      return { code: cc, name: "Cluster " + cc, sites: Array.from({ length: n }, (_, si) => {
        const sc = cc + "S" + (si + 1), r = rng(sc), nz = 2 + Math.floor(r() * 3);
        return { code: sc, name: "Site S" + (si + 1), cluster: cc, zones: Array.from({ length: nz }, (_, zi) => ({ code: "Z" + (zi + 1), enclosures: Array.from({ length: 3 + Math.floor(r() * 4) }, (_, ei) => "Z" + (zi + 1) + "-E" + pad(ei + 1, 2)) })) };
      }) };
    });
    return _clusters;
  }
  const allSites = () => clusters().flatMap(c => c.sites);
  function staff() {
    if (_staff) return _staff;
    const out = []; let ep = 1000;
    const person = (seed, antsRole, extra) => { const r = rng(seed); ep++; const p = { uid: "EP" + ep, ep: "EP" + ep, name: pick(r, FIRST), antsRole, role: ANTS_ROLE_MAP[antsRole], cluster: "", site: "", zone: "", ...extra }; out.push(p); return p; };
    person("ceo", "Chief Executive Officer", { title: "CEO" });
    person("coo", "Chief Operating Officer", { title: "COO" });
    person("sa1", "DRS Super Admin"); person("sa2", "DRS Super Admin");
    clusters().forEach(c => {
      person("ch" + c.code, "Cluster Head", { cluster: c.code });
      person("sad" + c.code, "DRS Site Admin", { cluster: c.code });
      c.sites.forEach(s => {
        const b = { cluster: c.code, site: s.code };
        ["Site Manager", "Curator", "Assistant Curator", "Biologist", "Veterinarian", "Paravet", "Assistant Facility Manager"].forEach(t => person(s.code + t, t, b));
        s.zones.forEach((z, zi) => {
          if (zi < 2) person(s.code + z.code + "hak", zi === 0 ? "Head Animal Keeper" : "Site Supervisor", { ...b, zone: z.code });
          person(s.code + z.code + "k1", "Animal Keeper", { ...b, zone: z.code });
          person(s.code + z.code + "k2", zi === 0 ? "Night Keeper" : "Animal Keeper", { ...b, zone: z.code });
        });
      });
    });
    AGENCIES0.forEach(a => out.push({ uid: a.login, ep: a.login, name: a.name, antsRole: "Maintenance Agency", role: "agency", cluster: a.clusters[0], site: "", zone: "", agency: a.id }));
    _staff = out; return out;
  }
  const AGENCIES0 = [
    { id: "AG1", login: "AG-1021", name: "Shree Fabricators", trades: ["Fabrication", "Civil", "Mesh"], person: "Mahesh", phone: "", clusters: ["V1", "V2"] },
    { id: "AG2", login: "AG-1034", name: "Aqua Plumbing Services", trades: ["Plumbing", "Electrical"], person: "Irfan", phone: "", clusters: ["V1", "V3", "V4"] },
    { id: "AG3", login: "AG-1047", name: "GreenBuild Civil Works", trades: ["Civil", "Painting", "Carpentry"], person: "Raghav", phone: "", clusters: ["V2", "V4", "V5"] },
    { id: "AG4", login: "AG-1052", name: "CoolAir Technicians", trades: ["AC", "Electrical", "Equipment"], person: "Salim", phone: "", clusters: ["V1", "V2", "V3", "V4", "V5"] }
  ];
  function animals(site) {
    if (_animals[site]) return _animals[site];
    const s = allSites().find(x => x.code === site); if (!s) return [];
    const r = rng("animals" + site), out = []; let n = 0;
    s.zones.forEach(z => z.enclosures.forEach(enc => {
      const [sp, lo, hi] = pick(r, SPECIES), cnt = lo + Math.floor(r() * (hi - lo + 1));
      for (let i = 0; i < cnt; i++) {
        n++; const big = BIG.includes(sp);
        out.push({ id: site + "-A" + pad(n, 4), name: big ? pick(r, NAMES) : sp + " #" + (i + 1), species: sp, site, zone: z.code, enclosure: enc, sex: pick(r, ["Male", "Female", "Female", "Unknown"]), dob: addD(today, -Math.floor(365 * (1 + r() * 14))) });
      }
    }));
    _animals[site] = out; return out;
  }
  function history(id) {
    const site = id.split("-A")[0], a = animals(site).find(x => x.id === id); if (!a) return { weights: [], bcs: [], vacc: [], events: [] };
    const r = rng("hist" + id), base = KG[a.species] || 20, w = [], b = [], v = [], ev = [];
    let kg = base * (0.85 + r() * 0.3), sc = 3;
    for (let m = 11; m >= 0; m--) { kg = kg * (0.97 + r() * 0.06); w.push({ date: addD(today, -m * 30 - Math.floor(r() * 5)), kg: Math.round(kg * 10) / 10 }); if (m % 3 === 0) { sc = Math.max(2, Math.min(4, sc + (r() < 0.25 ? -0.5 : r() < 0.5 ? 0.5 : 0))); b.push({ date: addD(today, -m * 30), score: sc }); } }
    v.push({ date: addD(today, -150 - Math.floor(r() * 60)), type: "Vaccination", by: "Vet" }, { date: addD(today, -80 - Math.floor(r() * 30)), type: "Deworming", by: "Paravet" });
    ev.push({ date: a.dob, text: "Born / acquired" }, { date: addD(today, -200 - Math.floor(r() * 100)), text: "Moved to enclosure " + a.enclosure });
    return { weights: w, bcs: b, vacc: v, events: ev };
  }
  function schedules(site) {
    const r = rng("sched" + site), out = [];
    animals(site).filter((a, i) => i % 3 === 0).forEach((a, i) => {
      const d = Math.floor(r() * 40) - 8; /* some overdue, some due soon */
      out.push({ id: "SCH-" + a.id + "-" + i, animalId: a.id, animal: a.name, species: a.species, enclosure: a.enclosure, type: r() < 0.5 ? "Vaccination" : "Deworming", due: addD(today, d) });
    });
    return out;
  }
  let _ref = 0;
  function record(kind, payload) {
    /* demo: keep a local log of what DRS sent to ANTS (real build: POST to ANTS) */
    const log = JSON.parse(localStorage.getItem("ants-demo-records") || "[]");
    const ref = "ANTS-" + { birth: "B", death: "D", "vaccination-done": "V" }[kind] + "-" + new Date().getFullYear().toString().slice(2) + pad(log.length + 1 + (_ref++), 5);
    log.unshift({ ref, kind, payload, at: Date.now() }); localStorage.setItem("ants-demo-records", JSON.stringify(log.slice(0, 500)));
    return { ok: true, ref };
  }
  const SAMPLE = { demo: true, clusters, staff, animals, history, schedules, record, agencies: () => AGENCIES0, roleMap: ANTS_ROLE_MAP };
  window.ANTS = window.ANTS || SAMPLE;                 /* the real ANTS replaces this */

  /* ---------- organisation helpers used by DRS ---------- */
  const ORG = window.ORG = {
    clusters: () => window.ANTS.clusters(),
    sites: () => window.ANTS.clusters().flatMap(c => c.sites),
    site: code => ORG.sites().find(s => s.code === code),
    staff: () => window.ANTS.staff(),
    user: uid => ORG.staff().find(p => p.uid === uid),
    people: (f) => ORG.staff().filter(p => Object.entries(f).every(([k, v]) => Array.isArray(v) ? v.includes(p[k]) : p[k] === v)),
    roleMap: () => (window.ANTS.roleMap || ANTS_ROLE_MAP),
    MULTI: ["exec", "ch", "sadmin", "siteadmin", "agency"],   /* roles that work across several sites */
    scopeSites(u) { u = u || ORG.me(); if (!u) return []; const all = ORG.sites();
      const own = window.ANTS.scopeSites && window.ANTS.scopeSites(u); if (own) return own;
      if (["exec", "sadmin"].includes(u.role)) return all.map(s => s.code);
      if (["ch", "siteadmin"].includes(u.role)) return all.filter(s => s.cluster === u.cluster).map(s => s.code);
      if (u.role === "agency") { const a = (window.ANTS.agencies ? window.ANTS.agencies() : []).find(x => x.id === u.agency); return all.filter(s => !a || a.clusters.includes(s.cluster)).map(s => s.code); }
      return [u.site]; },
    me: () => { const uid = raw.get("drs-user"); return uid ? ORG.user(JSON.parse(uid)) : null; },
    activeSite() { const u = ORG.me(); if (!u) return "_"; const sc = ORG.scopeSites(u); let s = raw.get("drs-site"); s = s ? JSON.parse(s) : null; return sc.includes(s) ? s : (u.site || sc[0] || "_"); },
    clusterOf: site => { const s = ORG.site(site); return s ? s.cluster : ""; },
    tkCode: site => site   /* ticket prefix, e.g. V1S2 */
  };

  /* ---------- CLOCK ---------- */
  window.NOW = () => Date.now() + (+(localStorage.getItem("drs-now-offset") || 0));

  /* ---------- STORAGE SCOPING ---------- */
  const base = window.DRS_STORAGE || { get: k => localStorage.getItem(k), set: (k, v) => localStorage.setItem(k, v) };
  const raw = { get: k => base.get(k), set: (k, v) => base.set(k, v) };
  const GLOBAL = /^(kc-role|kc-lang|kc-replang|drs-user|drs-site|kc-agencies|kc-notices|kc-useradm|kc-settings|kc-tr-|kc-export|drs-ants-|drsdemo-|kc-sessions|kc-pmjobs-all)/;
  const USER = /^(kc-lastto-|kc-read$|kc-alpop-|kc-evpop-|kc-agpop-|kc-afm-popped|kc-afmdone-pop|kc-vetmfpop|kc-pvpop|kc-notes$|kc-done|kc-logs|kc-train|kc-quiz|kc-mem-|kc-sup-name|kc-bio-name|kc-pin|kc-quiet|kc-ntpop|kc-duty|kc-ntseen|kc-sos-)/;
  function scoped(k, site) {
    if (GLOBAL.test(k)) return k;
    const u = raw.get("drs-user"); const uid = u ? JSON.parse(u) : "_";
    if (USER.test(k)) return "@u:" + uid + "/" + k;
    return "@" + (site || ORG.activeSite()) + "/" + k;
  }
  window.DRS_STORAGE = { get: k => base.get(scoped(k)), set: (k, v) => base.set(scoped(k), v) };
  /* read/write another site's data (dashboards, cross-site notices) */
  window.storeAt = {
    get(site, k, d) { try { const v = base.get(scoped(k, site)); return v ? JSON.parse(v) : d; } catch (e) { return d; } },
    set(site, k, v) { try { base.set(scoped(k, site), JSON.stringify(v)); } catch (e) {} }
  };
  window.DRS_RAW = raw; window.DRS_SCOPED = scoped;

  /* ---------- sign-in from ANTS (real build): ?uid=EP1001&token=… ---------- */
  try { const q = new URLSearchParams(location.search); const uid = q.get("uid");
    if (uid && !window.ANTS.connected && ORG.user(uid)) { raw.set("drs-user", JSON.stringify(uid)); raw.set("kc-role", JSON.stringify(ORG.user(uid).role)); if (q.get("site")) raw.set("drs-site", JSON.stringify(q.get("site"))); } } catch (e) {}
  /* who owns new records (incidents, alerts): the signed-in person */
  try { const me = ORG.me(); if (me && !window.DRS_ANTS_USER) window.DRS_ANTS_USER = { uid: me.uid, role: me.role, name: me.name, site: ORG.activeSite(), zone: me.zone || "" }; } catch (e) {}
  /* keep ROLE consistent with the signed-in person */
  try { const me = ORG.me(); if (me) raw.set("kc-role", JSON.stringify(me.role)); else if (raw.get("kc-role")) raw.set("kc-role", "null"); } catch (e) {}
})();

