const ul=a=>"<ul>"+a.map(x=>`<li>${L2(x)}</li>`).join("")+"</ul>";
function renderSpecies(){const g=GROUPS[current];
 $("species").innerHTML=`<h2>${L2(g.k)}</h2><p class="eg">${L2(g.eg)}</p><span class="danger d-${g.d}">${L2(g.dl)}</span>
 <div class="sec"><h3>${t("fFeeding")}</h3>${ul(g.food)}</div><div class="sec"><h3>${t("fHome")}</h3>${ul(g.home)}</div>
 <div class="sec"><h3>${t("fHealth")}</h3>${ul(g.health)}</div><div class="sec"><h3>${t("fEnrich")}</h3>${ul(g.enrich)}</div><div class="sec"><h3>${t("fSafe")}</h3>${ul(g.safe)}</div>`}
document.querySelector(".seg2").onclick=e=>{const m=e.target.dataset.am;if(!m)return;document.querySelectorAll(".seg2 button").forEach(b=>b.setAttribute("aria-pressed",b.dataset.am===m));$("am-ex").hidden=m!=="ex";$("am-care").hidden=m!=="care"};

/* ================= SPECIES EXPLORER ================= */
let ex={cls:"b",region:null,country:null,q:""};
const tagList=s=>s.split(" ").map(x=>L2(TAGS[x])).join(", ");
function spCard(s){
 const [c,cl,name,hn,sci,food,hab,st,ss,note]=s;const C=COUNTRIES[c];
 const subs=ss?ss.split(";").map(x=>`<em>${esc(x)}</em>`).join("<br>"):t("noSub");
 return `<div class="sp"><div class="top"><h3>${esc(name)}${hn?`<span class="hi">${esc(hn)}</span>`:""}</h3><span class="iucn s-${st}" title="${L2(IUCN[st])}">${st}<small>${L2(IUCN[st])}</small></span></div>
 <i>${esc(sci)}</i><dl><dt>${t("food")}</dt><dd>${tagList(food)}</dd><dt>${t("where")}</dt><dd>${C[3]} ${hi()?C[2]:C[1]}: ${tagList(hab)}</dd><dt>${t("subsp")}</dt><dd>${subs}</dd></dl>
 ${note?`<p class="note">${esc(L2(note))}</p>`:""}</div>`;
}
function renderEx(){
 $("exCls").innerHTML=[["b","birds"],["m","mammals"]].map(([k,l])=>`<button class="chip" aria-pressed="${ex.cls===k}" data-cl="${k}">${t(l)}</button>`).join("");
 const pool=SP.filter(s=>s[1]===ex.cls);let h="";
 const q=ex.q.trim().toLowerCase();
 if(q){
  const r=SP.filter(s=>(s[2]+" "+s[3]+" "+s[4]).toLowerCase().includes(q));
  h=`<p class="counter">${t("results",{n:r.length})}</p>`+(r.length?r.map(spCard).join(""):`<p class="empty">${t("noResults")}</p>`);
 }else if(ex.country){
  const C=COUNTRIES[ex.country],list=pool.filter(s=>s[0]===ex.country);
  h=`<button class="crumb" data-back="region">${REGIONS.find(r=>r[0]===C[0])[hi()?2:1]}</button><h2 class="xh">${C[3]} ${hi()?C[2]:C[1]}</h2>`+list.map(spCard).join("");
 }else if(ex.region){
  const R=REGIONS.find(r=>r[0]===ex.region);
  h=`<button class="crumb" data-back="all">${t("allRegions")}</button><h2 class="xh">${hi()?R[2]:R[1]}</h2>`+Object.entries(COUNTRIES).filter(([k,v])=>v[0]===ex.region).map(([k,v])=>
   `<button class="ccard" data-c="${k}"><span><b>${v[3]} ${hi()?v[2]:v[1]}</b><br><small>${t("nSpecies",{n:pool.filter(s=>s[0]===k).length})}</small></span><span class="go">›</span></button>`).join("");
 }else{
  h=`<div class="rgrid">`+REGIONS.map(r=>{const n=pool.filter(s=>COUNTRIES[s[0]][0]===r[0]).length;return `<button class="rcard ${r[3]}" data-r="${r[0]}"><b>${hi()?r[2]:r[1]}</b><small>${t("nSpecies",{n})}</small></button>`}).join("")+`</div>`;
 }
 $("exBody").innerHTML=h;
 $("legend").innerHTML=Object.keys(IUCN).map(k=>`<span class="s-${k}">${k} = ${L2(IUCN[k])}</span>`).join("");
}
$("exCls").onclick=e=>{if(e.target.dataset.cl){ex.cls=e.target.dataset.cl;renderEx()}};
$("exSearch").addEventListener("input",e=>{ex.q=e.target.value;renderEx()});
$("exBody").onclick=e=>{const b=e.target.closest("button");if(!b)return;
 if(b.dataset.r){ex.region=b.dataset.r;ex.country=null}
 else if(b.dataset.c){ex.country=b.dataset.c}
 else if(b.dataset.back==="region"){ex.country=null}
 else if(b.dataset.back==="all"){ex.region=null;ex.country=null}
 renderEx();window.scrollTo({top:0})};

