Object.assign(V,{Active:"जारी",Completed:"पूरा"});

const RECK=(fk,d)=>`drs-${fk}-${d}`;
function getRec(fk,d=TODAY){let r=store.get(RECK(fk,d),null);if(!r){r={};const F=FORMS[fk];F.sections.forEach(s=>s.fields.forEach(f=>{if(f.mem)r[f.k]=store.get(`kc-mem-${fk}-${f.k}`,"");if(f.now&&f.t==="time")r[f.k]=nowHM();if(f.t==="group")r[f.k]=[];if(f.t==="multi")r[f.k]=[]}))}return r}
function putRec(fk,r,d=TODAY){store.set(RECK(fk,d),r);const k=`drs-idx-${fk}`;let ix=store.get(k,[]);if(!ix.includes(d)){ix.unshift(d);ix.sort().reverse();store.set(k,ix)}}
const isFilled=(f,v)=>f.t==="check"?!!v:f.t==="group"?(v||[]).length>=(f.min||1):f.t==="multi"?(v||[]).length>0:!!(v!==undefined&&v!==null&&String(v).trim()!=="");
const flat=(F)=>F.sections.flatMap(s=>s.fields);
function sectionState(s,r){const req=s.fields.filter(f=>f.req||f.min);if(!req.length)return null;return req.every(f=>isFilled(f,r[f.k]))}
/* field HTML; ctx = data attributes string identifying record */
function fHTML(fk,f,v,path,ctx){
 const id=`f_${fk}_${path.replace(/\W/g,"_")}`,lab=f.l?L2(f.l):"",a=`data-fk="${fk}" data-p="${path}" data-t="${f.t}" ${ctx}`;
 if(f.t==="group"){const arr=v||[];return `<div class="grp">${lab?`<span class="lbl">${lab}</span>`:""}${arr.map((it,i)=>`<div class="box"><h3>${esc(L2(f.item))} ${i+1}<button class="x" data-gdel="${path}" data-i="${i}" ${a}>${t("remove")}</button></h3>${f.fields.map(sf=>fHTML(fk,sf,it[sf.k],`${path}.${i}.${sf.k}`,ctx)).join("")}</div>`).join("")}<button class="add" data-gadd="${path}" ${a}>${esc(L2(f.add))}</button></div>`}
 if(f.t==="seg")return `<div class="field"><span class="lbl">${lab}</span><div class="seg">${f.o.map(o=>`<label><input type="radio" name="${id}" value="${esc(o)}" ${v===o?"checked":""} ${(f.bad||[]).includes(o)?'class="bad"':""} ${a}><span>${esc(tv(o))}</span></label>`).join("")}</div></div>`;
 if(f.t==="multi")return `<div class="field"><span class="lbl">${lab}</span><div class="seg">${f.o.map(o=>`<label><input type="checkbox" value="${esc(o)}" ${(v||[]).includes(o)?"checked":""} ${(f.bad||[]).includes(o)?'class="bad"':""} ${a}><span>${esc(tv(o))}</span></label>`).join("")}</div></div>`;
 if(f.t==="check")return `<label class="chk"><input type="checkbox" ${v?"checked":""} ${a}><span>${lab}</span></label>`;
 if(f.t==="area")return `<div class="field"><span><label for="${id}">${lab}</label></span><textarea id="${id}" ${a}>${esc(v)}</textarea></div>`;
 const typ={time:"time",date:"date",num:"number"}[f.t]||"text";
 return `<div class="field"><span><label for="${id}">${lab}</label></span><input id="${id}" type="${typ}" value="${esc(v)}" ${typ==="number"?'inputmode="decimal"':""} ${a}></div>`;
}
function formCards(fk,r,ctx,openSet){const F=FORMS[fk];return F.sections.map((s,i)=>{const st=sectionState(s,r);
 const cnt=s.fields.filter(f=>f.t==="group").map(f=>(r[f.k]||[]).length).reduce((a,b)=>a+b,0);
 return `<details class="card ${st?"ok":""}" data-fsec="${fk}:${s.k}" ${(openSet?openSet.has(fk+":"+s.k):i===0)?"open":""}><summary><span class="num">${i+1}</span><h2><span>${esc(L2(s.l))}</span>${s.sub?`<span class="sub">${esc(L2(s.sub))}</span>`:""}</h2><span class="pill" ${st===null&&!cnt?'style="display:none"':""}>${st?t("done"):(cnt?cnt:t("pending"))}</span></summary><div class="cbody">${s.fields.map(f=>fHTML(fk,f,r[f.k],f.k,ctx)).join("")}</div></details>`}).join("")}
function meter(fk,r){const F=FORMS[fk];const st=F.sections.map(s=>sectionState(s,r)).filter(x=>x!==null);const n=st.filter(Boolean).length;return [n,st.length]}
function brandHTML(fk,r,id){const F=FORMS[fk];const [n,tt]=meter(fk,r);return `<div class="brand"><small>${esc(L2(F.small))}</small><h1>${esc(L2(F.title))}</h1><div class="meter"><div class="bar"><i id="${id}Bar" style="width:${tt?n/tt*100:0}%"></i></div><b id="${id}Pct">${t("ofDone",{n,t:tt})}</b></div><p class="counter" style="color:var(--gold-soft);margin:6px 0 0">${fmtDate(TODAY)}</p></div>`}
/* generic text */
function fmtVal(f,v){if(f.t==="check")return v?t("yes"):"";if(f.t==="multi")return (v||[]).map(tv).join(", ");if(f.t==="seg")return v?tv(v):"";return v?String(v):""}
function formText(fk,r,d){const F=FORMS[fk];const L=[`*DRS · ${L2(F.title).toUpperCase()}*`,`${t("rDate")}: ${fmtDate(d)}`];let n=0;
 F.sections.forEach(s=>{const lines=[];s.fields.forEach(f=>{const v=r[f.k];
  if(f.t==="group"){(v||[]).forEach((it,i)=>{const parts=f.fields.map(sf=>{const x=fmtVal(sf,it[sf.k]);return x?`${L2(sf.l)}: ${x}`:""}).filter(Boolean);if(parts.length)lines.push(`${i+1}) ${parts.join(" | ")}`)})}
  else{const x=fmtVal(f,v);if(x)lines.push(`${L2(f.l)}: ${x}`)}});
  n++;L.push("",`*${n}. ${L2(s.l)}*`);L.push(lines.length?lines.join("\n"):"-")});
 return L.join("\n")}
/* ---------- input handling for engine forms ---------- */
const CTX={};/* fk -> {get:()=>rec, save:(rec)=>void, rerender:()=>void, meterId} */
function ctxOf(el){const fk=el.dataset.fk,rid=el.dataset.rid;return rid?CTX[fk+":"+rid]:CTX[fk]}
document.addEventListener("input",e=>{const el=e.target;if(!el.dataset||!el.dataset.fk||el.dataset.gadd||el.dataset.gdel)return;const C=ctxOf(el);if(!C)return;const r=C.get();const p=el.dataset.p,ty=el.dataset.t;
 let v;if(ty==="multi"){v=[...el.closest(".seg").querySelectorAll("input:checked")].map(x=>x.value)}else if(ty==="check")v=el.checked;else if(el.type==="radio"){if(!el.checked)return;v=el.value}else v=el.value;
 setP(r,p,v);const f=flat(FORMS[el.dataset.fk]).find(x=>x.k===p);if(f&&f.mem)store.set(`kc-mem-${el.dataset.fk}-${p}`,v);C.save(r);C.status&&C.status();});
document.addEventListener("click",e=>{const b=e.target.closest("[data-gadd],[data-gdel]");if(!b||!b.dataset.fk)return;const C=ctxOf(b);if(!C)return;const r=C.get();
 if(b.dataset.gadd){const path=b.dataset.gadd;const arr=getP(r,path)||[];const f=findField(FORMS[b.dataset.fk],path);const it={};(f.fields||[]).forEach(sf=>{if(sf.now)it[sf.k]=nowHM();if(sf.t==="multi")it[sf.k]=[]});arr.push(it);setP(r,path,arr);C.save(r);C.rerender();
  const boxes=document.querySelectorAll(`[data-gdel="${path}"]`);const last=boxes[boxes.length-1];if(last){const box=last.closest(".box");box&&box.scrollIntoView({block:"center"})}}
 else{const arr=getP(r,b.dataset.gdel);arr.splice(+b.dataset.i,1);C.save(r);C.rerender()}});
function findField(F,path){const parts=path.split(".").filter(x=>!/^\d+$/.test(x));let fs=flat(F),f=null;parts.forEach(k=>{f=fs.find(x=>x.k===k);fs=f&&f.fields||[]});return f}
function updStatus(fk,r,root,meterId){const F=FORMS[fk];F.sections.forEach(s=>{const c=root.querySelector(`[data-fsec="${fk}:${s.k}"]`);if(!c)return;const st=sectionState(s,r);const cnt=s.fields.filter(f=>f.t==="group").map(f=>(r[f.k]||[]).length).reduce((a,b)=>a+b,0);c.classList.toggle("ok",!!st);const p=c.querySelector(".pill");p.textContent=st?t("done"):(cnt?cnt:t("pending"));p.style.display=(st===null&&!cnt)?"none":""});
 const [n,tt]=meter(fk,r);const b=$(meterId+"Bar"),pc=$(meterId+"Pct");if(b)b.style.width=(tt?n/tt*100:0)+"%";if(pc)pc.textContent=t("ofDone",{n,t:tt})}
/* daily form mounted into an element */
function mountDaily(fk,el){const mid="m_"+fk;const C=CTX[fk]={get:()=>C.r,save:r=>{C.r=r;putRec(fk,r)},rerender:()=>render(),status:()=>updStatus(fk,C.r,el,mid)};C.r=getRec(fk);
 function render(){const os=el.querySelector("[data-fsec]")?new Set([...el.querySelectorAll("details[data-fsec][open]")].map(d=>d.dataset.fsec)):null;const y=window.scrollY;el.innerHTML=brandHTML(fk,C.r,mid)+formCards(fk,C.r,"",os)+sendHTML(`${fk}:${TODAY}`);window.scrollTo(0,y)}
 SENDERS[`${fk}:${TODAY}`]=()=>({title:L2(FORMS[fk].title),role:FORMS[fk].role,text:formText(fk,C.r,TODAY),onSend:()=>afmFromForm(fk,C.r)});render()}
function afmFromForm(fk,r){flat(FORMS[fk]).filter(f=>f.t==="group").forEach(g=>{if(!g.fields.some(x=>x.afm))return;(r[g.k]||[]).forEach(it=>{if(it.afm&&!it.afmSent){newIssue({cat:"Other",prob:it.notes||it.cage||"Site work",loc:it.cage||"",pri:"Normal",from:ROLE});it.afmSent=true}})});putRec(fk,r)}

/* ---------- SEND ---------- */
const SENDERS={};let SENT=store.get("kc-sent",{});
function sendHTML(key){const s=SENT[key];const last=store.get("kc-lastto-"+(ROLE||"x"),[]);const sel=s?s.to:last;
 const chip=o=>`<label><input type="checkbox" value="${esc(o)}" ${sel.includes(o)?"checked":""} data-sendto="${key}"><span>${esc(tv(o))}</span></label>`;
 return `<div class="sendbox" data-sk="${key}"><h2>${t("sendH")}</h2><p class="counter" style="margin:2px 0 10px">${t("sendP")}</p>
 <span class="lbl">${t("people")}</span><div class="seg">${(ROLE==="dop"?["Curator","Manager"]:ROLE==="pvet"?["Vet","Manager"]:RECIP_PEOPLE).map(chip).join("")}</div>
 <span class="lbl" style="margin-top:10px">${t("groups")}</span><div class="seg">${(ROLE==="dop"?["Curator office"]:ROLE==="pvet"?["Vet team"]:RECIP_GROUPS).map(chip).join("")}</div>
 ${s?`<p class="okmsg" style="margin-top:12px">✓ ${t("sentTo",{w:s.to.map(tv).join(", "),t:hm(s.at)})}</p>`:""}
 <button class="btn gold" style="margin-top:12px" data-dosend="${key}">${s?t("resend"):t("sendBtn")}</button>
 <button class="x" style="margin-top:10px" data-prev="${key}">${t("preview")}</button><pre class="report" hidden data-prevbox="${key}"></pre>
 <details class="shareout"><summary>${t("shareOut")}</summary><a class="btn sg" href="https://signal.group/#CjQKIHaDRV-lYt2GfE4fDLXkotsmB6Nf7jA79dItiF-e5wx2EhC0tgvfWcNnTFliMHLCbH7g" target="_blank" rel="noopener" data-shout="${key}">${t("sendSignal")}</a><a class="btn wa" href="https://chat.whatsapp.com/DFVSMR1xboz41wkvxlAh40" target="_blank" rel="noopener" data-shout="${key}">${t("sendWA")}</a><p class="waTo">${t("pasteHelp")}</p></details></div>`}
document.addEventListener("click",e=>{const b=e.target.closest("[data-dosend],[data-prev],[data-shout]");if(!b)return;const key=b.dataset.dosend||b.dataset.prev||b.dataset.shout;const S0=SENDERS[key];if(!S0)return;const x=S0();
 if(b.dataset.prev){const pb=document.querySelector(`[data-prevbox="${key}"]`);pb.hidden=!pb.hidden;pb.textContent=x.text;b.textContent=pb.hidden?t("preview"):t("hidePrev");return}
 if(b.dataset.shout){copyText(x.text);toast(t("copied"));return}
 const to=[...document.querySelectorAll(`[data-sendto="${key}"]:checked`)].map(i=>i.value);if(!to.length){toast(t("pickOne"));return}
 finishSend(key,to,b);});
