/* ---------- ISSUES helper ---------- */
function newIssue({cat,prob,loc,pri,from}){const n=store.get("kc-issue-n",0)+1;store.set("kc-issue-n",n);issues=store.get("kc-issues",[]);issues.unshift({id:"M-"+String(n).padStart(3,"0"),cat,prob,loc,pri,step:0,times:[Date.now()],date:TODAY,from:from||ROLE||"sup",notes:[],st:"new",hist:[{st:"new",at:Date.now(),by:from||ROLE||"sup"}]});store.set("kc-issues",issues);try{renderIssues();status()}catch(e){}}

/* ---------- PINS ---------- */
let PINS=store.get("kc-pins",[]);const canPin=()=>["cur","acur","mgr"].includes(ROLE);
function rPins(){const el=$("pinBox");if(!el)return;if(!PINS.length&&!canPin()){el.innerHTML="";return}
 el.innerHTML=`<div class="pinbox"><h2>📌 ${t("pinsH")} <span class="pill">${PINS.length}</span></h2>${PINS.map((p,i)=>`<div class="act"><span>${esc(p.text)}<br><small style="color:var(--muted)">${esc(L2(ROLE_LABEL[p.by]||["",""]))} · ${hm(p.at)}</small></span>${canPin()?`<button class="x" data-unpin="${i}">${t("unpin")}</button>`:""}</div>`).join("")}
 ${canPin()?`<div class="inl" style="margin:10px 0 0"><input type="text" id="pinIn" placeholder="${t("pinAdd")}" aria-label="${t("pinAdd")}"><button class="btn" id="pinGo">+</button></div>`:""}</div>`}
document.addEventListener("click",e=>{if(e.target.id==="pinGo"){const v=$("pinIn").value.trim();if(!v)return;PINS.unshift({text:v,by:ROLE,at:Date.now()});store.set("kc-pins",PINS);rPins()}
 const u=e.target.dataset&&e.target.dataset.unpin;if(u!=null){PINS.splice(+u,1);store.set("kc-pins",PINS);rPins()}});

/* ---------- KEEPER DUTY ---------- */
let DUTY=store.get("kc-duty","day");
function rDuty(){document.querySelectorAll("#dutySeg button").forEach(b=>b.setAttribute("aria-pressed",b.dataset.duty===DUTY));["day","night","special"].forEach(x=>$("duty-"+x).hidden=x!==DUTY);
 if(DUTY==="night")mountDaily("night",$("duty-night"));if(DUTY==="special")mountDaily("special",$("duty-special"));
 if(DUTY==="day")mountSend("sendDay",`kday:${TODAY}`,()=>({title:t("kDay"),role:"keeper",text:kdayText()}))}
$("dutySeg").onclick=e=>{const d=e.target.dataset.duty;if(!d)return;DUTY=d;store.set("kc-duty",d);rDuty()};
function kdayText(){const all=DAY.flatMap(s=>s.tasks);const dn=all.filter(x=>done.ids.includes(x.id)),miss=all.filter(x=>!done.ids.includes(x.id));
 const lg=logs.filter(l=>new Date(l.at).toDateString()===new Date().toDateString());
 return [`*${t("kdTitle")}*`,`${t("rDate")}: ${fmtDate(TODAY)}`,"",`*${t("kdTasks")}: ${dn.length}/${all.length}*`,miss.length?`${t("kdMissed")}:\n- `+miss.map(x=>L2(x.t)+(x.s?" ⚠":"")).join("\n- "):t("allChecks"),"",`*${t("kdLogs")} (${lg.length})*`,
  lg.length?lg.map(l=>`- ${l.animal}: ${t("appetite")} ${tv(l.app)}, ${t("behaviour")} ${tv(l.beh)}, ${t("droppings")} ${tv(l.dro)}${l.notes?" – "+l.notes:""}`).join("\n"):t("noneR")].join("\n")}

/* ---------- REPORTS INBOX ---------- */
let READ=store.get("kc-read",{}),inbF={k:"all",r:"7"};
const KINDS=[["kday","kDay","keeper"],["night","kNight","keeper"],["special","kSpecial","keeper"],["sup","kSup","sup"],["bio","kBio","bio"],["etho","kEtho","bio"],["shift","kShift","bio"],["acur","kAcur","acur"],["cur","kCur","cur"],["vet","kVet","vet"],["afm","kAfm","afm"],["mgr","kMgr","mgr"]];
function allReports(){const out=[];const add=(kind,key,date,title,author,getText)=>{const s=SENT[key];out.push({kind,key,date,title,author,sent:s,getText:()=>s?s.text:getText()})};
 store.get("kc-sup-index",[]).forEach(d=>{const R=d===TODAY?S:store.get("kc-sup-"+d,null);if(R)add("sup","sup:"+d,d,t("kSup"),R.name,()=>buildReport(R,d))});
 store.get("kc-bio-index",[]).forEach(d=>{const R=dayRec(d);add("bio","bio:"+d,d,t("kBio"),R.name,()=>buildBio(R,d))});
 ["night","special","acur","cur","vet","mgr"].forEach(fk=>store.get(`drs-idx-${fk}`,[]).forEach(d=>{const R=getRec(fk,d);add(fk,`${fk}:${d}`,d,L2(FORMS[fk].title),R.name,()=>formText(fk,R,d))}));
 ETHS.forEach(s=>add("etho","etho:"+s.id,s.start,`${t("kEtho")}: ${s.animal}`,s.observer,()=>ethoText(s)));
 SHIFTS.forEach(s=>add("shift","shift:"+s.id,s.date||TODAY,`${t("kShift")}: ${s.animal||"?"}`,"",()=>formText("shift",s,s.date||TODAY)));
 Object.entries(SENT).forEach(([k,s])=>{if(/^(kday|afm):/.test(k)){const [kind,d]=k.split(":");out.push({kind,key:k,date:d,title:s.title,author:"",sent:s,getText:()=>s.text})}});
 return out.sort((a,b)=>(b.sent?b.sent.at:0)-(a.sent?a.sent.at:0)||b.date.localeCompare(a.date))}
function rInbox(){const from=inbF.r==="1"?TODAY:inbF.r==="7"?addDays(TODAY,-6):"0000";
 const list=allReports().filter(x=>x.date>=from&&(inbF.k==="all"||x.kind===inbF.k));
 const kinds=[["all","fAll"],...KINDS.map(k=>[k[0],k[1]])];
 $("inboxBody").innerHTML=`<div class="chips" style="margin:0 -18px 8px;padding:0 18px 6px">${kinds.map(([k,l])=>`<button class="chip" aria-pressed="${inbF.k===k}" data-ik="${k}">${t(l)}</button>`).join("")}</div>
 <div class="tabs2" style="margin-top:0">${[["1","fToday"],["7","f7"],["all","fEver"]].map(([k,l])=>`<button aria-pressed="${inbF.r===k}" data-ir="${k}">${t(l)}</button>`).join("")}</div>`+
 (list.length?list.map(x=>`<button class="res inb" data-open="${x.key}"><span class="top"><b>${esc(x.title)}</b>${READ[x.key]?"":`<span class="tag">${t("unread")}</span>`}</span><small>${fmtDate(x.date)}${x.author?" · "+esc(x.author):""} · ${x.sent?`<span class="pass">${t("sent")}</span> → ${esc(x.sent.to.map(tv).join(", "))}`:t("draft")}</small></button>`).join(""):`<p class="empty">${t("noReports")}</p>`)}
$("inboxBody").addEventListener("click",e=>{const b=e.target.closest("button");if(!b)return;if(b.dataset.ik){inbF.k=b.dataset.ik;rInbox()}if(b.dataset.ir){inbF.r=b.dataset.ir;rInbox()}if(b.dataset.open)openReport(b.dataset.open)});
function openReport(key){const x=allReports().find(r=>r.key===key);if(!x)return;READ[key]=1;store.set("kc-read",READ);const canFlag=["cur","acur","mgr","bio","sup"].includes(ROLE);
 $("repSheet").innerHTML=`<div class="sheet big"><div class="top"><h2>${esc(x.title)}</h2><button class="x" id="rsClose">${t("close")}</button></div><p class="counter">${fmtDate(x.date)}${x.sent?" · "+t("sentTo",{w:x.sent.to.map(tv).join(", "),t:hm(x.sent.at)}):" · "+t("draft")}</p><pre class="report">${esc(x.getText())}</pre>
 ${canFlag?`<details class="shareout"><summary>${t("flagAfm")}</summary><div class="field"><span>${t("flagWhat")}</span><input type="text" id="flWhat"></div><div class="row"><div class="field"><span>${t("loc")}</span><input type="text" id="flLoc"></div><div class="field"><span>${t("probType")}</span><select class="full" id="flCat">${Object.keys(MCATS).map(c=>`<option value="${c}">${tv(c)}</option>`).join("")}</select></div></div><button class="btn" id="flGo">${t("flagSend")}</button></details>`:""}
 ${canPin()?`<button class="btn ghost" id="pinRep" style="margin-top:10px">📌 ${t("pinIt")}</button>`:""}</div>`;$("repSheet").hidden=false;$("repSheet").dataset.key=key;$("rsClose").focus()}
$("repSheet").addEventListener("click",e=>{const id=e.target.id;const key=$("repSheet").dataset.key;
 if(id==="rsClose"||e.target===$("repSheet")){$("repSheet").hidden=true;if(VIEW==="inbox")rInbox();if(VIEW==="dash")rDash()}
 if(id==="flGo"){const w=$("flWhat").value.trim();if(!w){$("flWhat").focus();return}newIssue({cat:$("flCat").value,prob:w,loc:$("flLoc").value.trim(),pri:"Normal",from:ROLE});toast(t("flagged"));$("flWhat").value=""}
 if(id==="pinRep"){const x=allReports().find(r=>r.key===key);PINS.unshift({text:x.title+" ("+fmtDate(x.date)+")",by:ROLE,at:Date.now()});store.set("kc-pins",PINS);rPins();toast(t("pinned"))}});
$("repSheet").addEventListener("keydown",e=>{if(e.key==="Escape")$("repSheet").hidden=true});

/* ---------- AFM ---------- */
let afmF="0";const ASTEP=["aNew","aSeen","aWork","aFixed"];
function rAfm(){issues=store.get("kc-issues",[]);const list=issues.filter(x=>afmF==="all"||String(x.step)===afmF);
 $("afmBody").innerHTML=`<div class="tabs2" style="margin-top:0">${["0","1","2","3","all"].map(k=>`<button aria-pressed="${afmF===k}" data-af="${k}">${k==="all"?t("fAll"):t(ASTEP[+k])} (${k==="all"?issues.length:issues.filter(x=>String(x.step)===k).length})</button>`).join("")}</div>`+
 (list.length?list.map(x=>{const old=x.step<3&&(Date.now()-x.times[0])>2*864e5;return `<div class="issue ${x.pri==="Urgent"?"urgent":""} ${x.step===3?"fixed":""}"><div class="top"><strong>${esc(x.prob)}</strong><small>${x.id}</small></div>
  <small>${tv(x.cat)}${x.loc?", "+esc(x.loc):""} · ${t("from")}: ${esc(L2(ROLE_LABEL[x.from]||ROLE_LABEL.sup))}</small>${x.pri==="Urgent"?`<span class="tag">${tv("Urgent")}</span>`:""}${old?`<span class="tag age">${t("openFor",{d:ago(x.times[0])})}</span>`:""}
  <div class="steps" aria-hidden="true">${[0,1,2,3].map(i=>`<span class="${i<=x.step?"on":""}"></span>`).join("")}</div><div class="st"><b>${stLabel(x)}</b>, ${hm(x.times[x.step])}</div>
  ${(x.notes||[]).map(n=>`<div class="logi"><small>${hm(n.at)}</small>${esc(n.t)}</div>`).join("")}
  ${x.step<3?`<div class="acts"><button class="btn" data-anext="${x.id}">${t(["markSeen","startWork","markFixed"][x.step])}</button></div>`:""}
  <div class="inl" style="margin:8px 0 0"><input type="text" data-anote="${x.id}" placeholder="${t("addNote")}" aria-label="${t("addNote")}"><button class="btn" data-anadd="${x.id}">+</button></div></div>`}).join(""):`<p class="empty">${t("noOpen")}</p>`);
 mountSend("sendAfm",`afm:${TODAY}`,()=>({title:t("afmSum"),role:"afm",text:afmText()}))}
$("afmBody").addEventListener("click",e=>{const b=e.target.closest("button");if(!b)return;const d=b.dataset;
 if(d.af){afmF=d.af;rAfm();return}const x=issues.find(i=>i.id===(d.anext||d.anadd));if(!x)return;
 if(d.anext){x.step++;x.times[x.step]=Date.now();toast(stLabel(x))}
 if(d.anadd){const inp=document.querySelector(`[data-anote="${x.id}"]`);if(!inp.value.trim())return;x.notes=x.notes||[];x.notes.push({t:inp.value.trim(),at:Date.now()})}
 store.set("kc-issues",issues);rAfm()});
function afmText(){const td=x=>x&&new Date(x).toDateString()===new Date().toDateString();const fx=issues.filter(x=>x.step===3&&td(x.times[3])),st=issues.filter(x=>x.step===2&&td(x.times[2])),op=issues.filter(x=>x.step<3);
 const ln=x=>`- ${x.id} [${tv(x.cat)}] ${x.prob}${x.loc?" @ "+x.loc:""}${(x.notes||[]).length?" – "+x.notes[x.notes.length-1].t:""}`;
 return [`*${t("afmTitle")}*`,`${t("rDate")}: ${fmtDate(TODAY)}`,"",`*${t("fixedToday")} (${fx.length})*`,...(fx.length?fx.map(ln):["-"]),"",`*${t("startedToday")} (${st.length})*`,...(st.length?st.map(ln):["-"]),"",`*${t("pendingN")} (${op.length})*`,...(op.length?op.map(x=>ln(x)+` (${stLabel(x)}, ${ago(x.times[0])})`):["-"])].join("\n")}

/* ---------- MANAGER DASHBOARD ---------- */
function rDash(){issues=store.get("kc-issues",[]);$("dashDate").textContent=fmtDate(TODAY);const R=allReports().filter(x=>x.date===TODAY);
 const st=k=>SENT[`${k}:${TODAY}`]?"sent":R.some(x=>x.kind===k)?"draft":"none";
 const night=getRec("night"),vet=getRec("vet");
 const births2=(S.events||[]).filter(e=>e.type==="Birth").reduce((a,e)=>a+(+e.count||1),0)+(night.finds||[]).filter(f=>f.type==="Birth").length+(vet.births||[]).length;
 const deaths=(S.events||[]).filter(e=>e.type==="Mortality").reduce((a,e)=>a+(+e.count||1),0)+(night.finds||[]).filter(f=>f.type==="Mortality").length+(vet.morts||[]).length;
 const flags=actions(B,TODAY).length+(night.finds||[]).filter(f=>f.emer==="Yes").length;
 const open=issues.filter(x=>x.step<3),urg=open.filter(x=>x.pri==="Urgent").length;
 const cards=[["kDay","kday"],["kNight","night"],["kSpecial","special"],["kSup","sup"],["kBio","bio"],["kAcur","acur"],["kCur","cur"],["kVet","vet"],["kAfm","afm"]];
 $("dashBody").innerHTML=`<div class="wgrid">${[["births",births2],["deaths",deaths],["redFlags",flags],["openIssues",open.length],["studies",ETHS.filter(s=>s.status!=="Completed").length],["shiftsN",SHIFTS.filter(s=>["Planned","Approved","In progress"].includes(s.status)).length]].map(([k,v])=>`<div class="wst ${(k==="deaths"||k==="redFlags")&&v?"hot":""}"><b>${v}</b><span>${t(k)}</span></div>`).join("")}</div>
 ${urg?`<div class="warn">${t("urgentN",{n:urg})} · ${t("openIssues")}</div>`:""}
 <h2 class="xh" style="font-size:1.2rem;margin:16px 0 8px">${t("repToday")}</h2><div class="rgrid2">${cards.map(([l,k])=>{const s=st(k);return `<div class="rst ${s}"><b>${t(l)}</b><span>${s==="sent"?"✓ "+t("sent"):s==="draft"?t("draft"):t("notStarted")}</span></div>`}).join("")}</div>
 <h2 class="xh" style="font-size:1.2rem;margin:18px 0 8px">${t("latest")}</h2>${allReports().slice(0,8).map(x=>`<button class="res inb" data-open="${x.key}"><span class="top"><b>${esc(x.title)}</b>${READ[x.key]?"":`<span class="tag">${t("unread")}</span>`}</span><small>${fmtDate(x.date)} · ${x.sent?t("sent"):t("draft")}</small></button>`).join("")||`<p class="empty">${t("noReports")}</p>`}`;
 mountDaily("mgr",$("mgrForm"))}
$("dashBody").addEventListener("click",e=>{const b=e.target.closest("[data-open]");if(b)openReport(b.dataset.open)});

