function rShifts(){const el=$("shiftList");const os=new Set([...el.querySelectorAll("details[data-fsec][open]")].map(d=>d.dataset.fsec));const y=window.scrollY;el.innerHTML=SHIFTS.length?SHIFTS.map(s=>{const k="shift:"+s.id;CTX["shift:"+s.id]={get:()=>s,save:()=>{store.set("kc-shifts",SHIFTS)},rerender:()=>{shOpen=s.id;rShifts()},status:()=>{const i=document.querySelector(`[data-rid="${s.id}"]`);const d=i&&i.closest("details.plan");if(d){d.querySelector("h3").textContent=s.animal||"—";d.querySelector(".ptype").textContent=tv(s.kind||"");d.querySelector(".meta").innerHTML=`<span>${esc(s.from||"?")} → ${esc(s.to||"?")}</span>${s.date?`<span>${shortD(s.date)}</span>`:""}<span>${esc(tv(s.status||"Planned"))}</span>`}}};
  SENDERS[k]=()=>({title:`${t("kShift")}: ${s.animal||"?"}`,role:"bio",text:formText("shift",s,s.date||TODAY)});
  return `<details class="plan" ${shOpen===s.id?"open":""}><summary><span class="ptype">${esc(tv(s.kind||""))}</span><h3>${esc(s.animal||"—")}</h3><div class="meta"><span>${esc(s.from||"?")} → ${esc(s.to||"?")}</span>${s.date?`<span>${shortD(s.date)}</span>`:""}<span>${esc(tv(s.status||"Planned"))}</span></div></summary><div class="pbody">${formCards("shift",s,`data-rid="${s.id}"`,os.size?os:null)}${sendHTML(k)}<button class="x" data-shdel="${s.id}">${t("delShift")}</button></div></details>`}).join(""):`<p class="empty">${t("noShifts")}</p>`;window.scrollTo(0,y)}
$("newShiftBtn").onclick=()=>{const s={id:"S"+Date.now(),status:"Planned",date:TODAY,chk:[],settle:[]};SHIFTS.unshift(s);store.set("kc-shifts",SHIFTS);shOpen=s.id;rShifts()};
