const LIBS={zip:"https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js",xlsx:"https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js",h2c:"https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js",pdf:"https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js"};
const _libP={};function lib(k){return _libP[k]||(_libP[k]=new Promise((res,rej)=>{const s=document.createElement("script");s.src=LIBS[k];s.onload=res;s.onerror=()=>{delete _libP[k];rej(new Error("net"))};document.head.appendChild(s)}))}
let DL=null;(async()=>{try{if(window.claude&&claude.use)DL=await claude.use("downloads")}catch(e){DL=null}})();
async function saveFile(name,data){if(DL){try{await DL.save({filename:name,data});toast(t("exSaved"));return}catch(e){if(e&&e.code==="declined")return;if(e&&!["unavailable","not_granted","capability_disabled","capability_removed"].includes(e.code)){toast(t("exFail"));return}}}
 const blob=data instanceof Blob?data:new Blob([data]);const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},2000);toast(t("exSaved"))}
const xe=s=>String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
async function makeDocx(text){await lib("zip");const z=new JSZip();
 const paras=text.split("\n").map(line=>{const h=/^\*(.+)\*$/.test(line.trim());const tx=h?line.trim().slice(1,-1):line;const big=/^\*VANTARA|DRS ·/.test(line.trim())&&h;
  return `<w:p>${h?`<w:pPr><w:spacing w:before="${big?0:200}" w:after="80"/></w:pPr>`:""}<w:r><w:rPr><w:rFonts w:ascii="Calibri" w:hAnsi="Calibri" w:cs="Nirmala UI"/>${h?"<w:b/><w:bCs/>":""}<w:sz w:val="${big?32:h?26:22}"/><w:szCs w:val="${big?32:h?26:22}"/>${h?'<w:color w:val="123F31"/>':""}</w:rPr><w:t xml:space="preserve">${xe(tx)}</w:t></w:r></w:p>`}).join("");
 z.file("[Content_Types].xml",`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>`);
 z.file("_rels/.rels",`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>`);
 z.file("word/document.xml",`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>${paras}<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1134" w:right="1134" w:bottom="1134" w:left="1134" w:header="708" w:footer="708" w:gutter="0"/></w:sectPr></w:body></w:document>`);
 return await z.generateAsync({type:"blob"})}
async function makeXlsx(){await lib("xlsx");const wb=XLSX.utils.book_new();Object.entries(exSheets()).forEach(([n,rows])=>{const ws=XLSX.utils.aoa_to_sheet(rows);ws["!cols"]=rows[0].map((h,i)=>({wch:i===rows[0].length-1&&n==="Reports"?80:Math.min(40,Math.max(10,...rows.map(r=>String(r[i]==null?"":r[i]).length).slice(0,50)))}));XLSX.utils.book_append_sheet(wb,ws,n)});
 const out=XLSX.write(wb,{bookType:"xlsx",type:"array"});return new Blob([out])}
async function makePdf(text){await lib("h2c");await lib("pdf");const box=document.createElement("div");box.className="pdfsheet";
 box.innerHTML=text.split("\n").map(l=>{const h=/^\*(.+)\*$/.test(l.trim());return h?`<h3>${esc(l.trim().slice(1,-1))}</h3>`:l.trim()?`<p>${esc(l)}</p>`:`<p>&nbsp;</p>`}).join("");document.body.appendChild(box);
 try{const cv=await html2canvas(box,{scale:2,backgroundColor:"#ffffff"});const {jsPDF}=window.jspdf;const pdf=new jsPDF({unit:"pt",format:"a4"});const pw=pdf.internal.pageSize.getWidth(),ph=pdf.internal.pageSize.getHeight(),m=28;
  const iw=pw-2*m,scale=iw/cv.width,pageH=Math.floor((ph-2*m)/scale);let y=0,first=true;
  while(y<cv.height){const h=Math.min(pageH,cv.height-y);const c2=document.createElement("canvas");c2.width=cv.width;c2.height=h;c2.getContext("2d").drawImage(cv,0,y,cv.width,h,0,0,cv.width,h);if(!first)pdf.addPage();pdf.addImage(c2.toDataURL("image/jpeg",0.92),"JPEG",m,m,iw,h*scale);first=false;y+=h}
  return pdf.output("blob")}finally{box.remove()}}
