  const sp=store.get(RECK("special",TODAY),{});const bad=["Aggression","Restless / distressed","Not eating","Heavy breathing","Bleeding / wound"];const spc=(sp.obs||[]).filter(o=>(o.tags||[]).some(x=>bad.includes(x))).map(o=>({txt:`${sp.animal||"?"} ${o.time||""}: ${(o.tags||[]).filter(x=>bad.includes(x)).map(tv).join(", ")}${o.note?" – "+o.note:""}`,who:t("tellVet")}));
  const tx=[...(vprev.treat||[]),...(vrec.treat||[])].filter(x=>x.next);
