/* ---------- ticket status model ---------- */
const STS=["new","seen","assigned","accepted","parts","done","closed"];const ST2STEP={new:0,seen:1,assigned:2,accepted:2,parts:2,done:2,closed:3};
const stOf=x=>x.st||(["new","seen","accepted","closed"][x.step]||"new");
function stLabel(x){return t("s_"+stOf(x))}
const agById=id=>AGENCIES.find(a=>a.id===id);
const agName=x=>x.agency==="inhouse"?tv("In-house"):(agById(x.agency)||{}).name||"";
function setSt(x,st,note,extra){const prev=x.step;x.st=st;x.step=ST2STEP[st];x.times=x.times||[];if(x.step!==prev||!x.times[x.step])x.times[x.step]=Date.now();x.hist=x.hist||[];x.hist.push({st,at:Date.now(),by:ROLE,note:note||"",agency:x.agency||""});if(note){x.notes=x.notes||[];x.notes.push({t:note,at:Date.now(),by:ROLE})}Object.assign(x,extra||{})}
const tOf=(x,st)=>{const h=(x.hist||[]).filter(e=>e.st===st);return h.length?h[h.length-1].at:null};
const tFirst=(x,st)=>{const h=(x.hist||[]).find(e=>e.st===st);return h?h.at:null};
function dur(ms){if(ms==null||ms<0)return "-";const m=Math.round(ms/60000);if(m<60)return m+" min";const h=Math.floor(m/60),mm=m%60;if(h<24)return `${h} h${mm?" "+mm+" min":""}`;const d=Math.floor(h/24),hh=h%24;return `${d} d${hh?" "+hh+" h":""}`}
function times(x){const c=x.times&&x.times[0],acc=tFirst(x,"accepted"),dn=tOf(x,"done"),cl=x.st==="closed"?tOf(x,"closed"):null;return {created:c,assigned:tFirst(x,"assigned"),accepted:acc,done:dn,closed:cl,resp:acc&&c?acc-c:null,work:dn&&acc?dn-acc:null,total:cl&&c?cl-c:null}}
const saveIss=()=>{store.set("kc-issues",issues);_lastNew=newIss().map(x=>x.id).join();try{_lastTk=JSON.stringify(issues.map(x=>[x.id,(x.hist||[]).length]))}catch(e){}};
