async function translator(){if(window.DRS_TRANSLATE)return {strings:window.DRS_TRANSLATE};try{const s=window.claude&&claude.use?await claude.use("sample"):null;if(!s)return null;
 return {strings:async(arr,lang)=>{const L=LANGS.find(l=>l[0]===lang);const prompt=`Translate the user-interface strings below for a zoo and animal rescue centre staff app ("DRS – Daily Report System") from English into ${L[2]}${L[3]?" ("+L[3]+" script)":""}.
Rules: use simple everyday words a zoo keeper understands; keep placeholders such as {n} {t} {d} {w} {s} {p} {a} {r} {b} {c} {h} {l} exactly as they are; keep abbreviations unchanged (DRS, AFM, CSSD, ID, EP, pH, UVB, IUCN, CITES, BCS, SOP, VIP, AC, PDF, P, A, L, SL, WO, H, HD, LT, OD); keep emoji and punctuation; keep animal and species names in English if unsure.
Reply with ONLY a JSON object whose keys are the exact English strings and whose values are the translations.
Strings:
${JSON.stringify(arr)}`;
  return await s.json(prompt,{modelTier:"quick"})},text:async(txt,lang)=>{const L=LANGS.find(l=>l[0]===lang);const {text}=await s(`Translate this zoo staff report into ${L[2]}. Keep the exact layout, line breaks, numbering, asterisks (*) and symbols. Keep names of people, animals, species, cage numbers, IDs, times and numbers unchanged. Translate everything written in any other language. Reply with only the translated report.\n\n${txt}`,{modelTier:"quick"});return text}}}catch(e){return null}}
async function translateUI(code,force){const key="kc-tr-"+code;let tr=force?{}:store.get(key,{});const all=uiStrings();const todo=all.filter(s=>!tr[s]);window.TRX=tr;if(!todo.length)return true;
 const T=await translator();if(!T){toast(t("trFail"));return false}
 const L=LANGS.find(l=>l[0]===code);TRJOB={code,done:all.length-todo.length,total:all.length,stop:false};rTrBar();
 const chunks=[];for(let i=0;i<todo.length;i+=90)chunks.push(todo.slice(i,i+90));
 let fails=0;const run=async()=>{while(chunks.length&&!TRJOB.stop){const c=chunks.shift();try{const res=await T.strings(c,code);if(res&&typeof res==="object")c.forEach(s=>{const v=res[s];if(typeof v==="string"&&v.trim()){const ph=(s.match(/\{\w\}/g)||[]);if(ph.every(p=>v.includes(p)))tr[s]=v}});store.set(key,tr);if(LANG===code){window.TRX=tr;applyLang()}}catch(e){fails++;if(e&&["not_granted","unavailable","capability_disabled"].includes(e.code)){TRJOB.stop=true;toast(t("trFail"))}}TRJOB.done+=c.length;rTrBar()}};
 await Promise.all([run(),run()]);const ok=!TRJOB.stop||Object.keys(tr).length>all.length*0.5;TRJOB=null;rTrBar();if(ok&&LANG===code)toast(t("trDone",{l:L[1]}));return ok}
function rTrBar(){let el=$("trBar");if(!el){el=document.createElement("div");el.id="trBar";document.querySelector("main").prepend(el)}
 if(!TRJOB){el.innerHTML="";return}const L=LANGS.find(l=>l[0]===TRJOB.code);const p=Math.round(TRJOB.done/TRJOB.total*100);
 el.innerHTML=`<div class="trbar"><span>🌐 ${t("trBusy",{l:L[1],p})}</span><span class="bar"><i style="width:${p}%"></i></span><button class="x" id="trStop">${t("trStop")}</button></div>`}
async function setLang(code){LANG=code;store.set("kc-lang",code);window.TRX=code!=="en"&&code!=="hi"?store.get("kc-tr-"+code,{}):{};langFont(code);applyLang();$("repSheet").hidden=true;if(code!=="en"&&code!=="hi"){const ok=await translateUI(code);if(!ok&&!Object.keys(window.TRX).length){LANG="en";store.set("kc-lang","en");window.TRX={};applyLang()}}}
function openLang(){$("repSheet").innerHTML=`<div class="sheet big"><div class="top"><h2>🌐 ${t("langH")}</h2><button class="x" id="rsClose">${t("close")}</button></div><p class="counter">${t("langP")}</p>
 <div class="langgrid">${LANGS.map(([c,n,en,sc])=>{const have=c==="en"||c==="hi"||Object.keys(store.get("kc-tr-"+c,{})).length>200;return `<button class="langopt" aria-pressed="${LANG===c}" data-lang="${c}" lang="${c}"><b>${n}</b><small>${en} · ${c==="en"||c==="hi"?t("builtIn"):have?"✓ "+t("ready"):t("aiTr")}</small></button>`}).join("")}</div>
 ${!["en","hi"].includes(LANG)?`<button class="x" data-retr="${LANG}" style="margin-top:8px">${t("retrans")}</button>`:""}
 <h3 class="subh" style="margin-top:16px">${t("repLangH")}</h3><p class="counter" style="margin-top:0">${t("repLangP")}</p><div class="seg">${[["en","English"],["hi","हिंदी"]].map(([c,n])=>`<label><input type="radio" name="rlg" value="${c}" ${REPLANG===c?"checked":""} data-rlang="1"><span>${n}</span></label>`).join("")}</div></div>`;$("repSheet").hidden=false;
 document.querySelectorAll(".langgrid .langopt").forEach(b=>{const f=FONT_OF[(LANGS.find(l=>l[0]===b.dataset.lang)||[])[3]];if(f)langFont&&(()=>{if(!document.querySelector(`link[data-f="${f}"]`)){const ln=document.createElement("link");ln.rel="stylesheet";ln.dataset.f=f;ln.href=`https://fonts.googleapis.com/css2?family=${encodeURIComponent(f)}:wght@400;700&display=swap`;document.head.appendChild(ln)}b.style.fontFamily=`"${f}",sans-serif`})()})}
