/* ================= MAIN-APP HOOKS =================
   Optional functions the main app can define on window before or after DRS loads:
   DRS_SEND(payload)    -> deliver a sent report into the main app chat. payload = {key, to:[...], title, role, text, original, language, at}
   DRS_NOTIFY(event)    -> push notification. event = {type, title, body, toRoles:[...], ref}
                           types: "afm_ticket", "ticket_update", "animal_alert", "event_approved", "cover_request", "cover_approved"
   DRS_TRANSLATE(strings, lang) -> Promise<{english: translated}> for screen text (e.g. Bhashini / Google / Azure)
   DRS_TRANSLATE_TEXT(text, lang) -> Promise<string> for translating a typed report into English/Hindi
   DRS_STORAGE {get,set} -> replaces localStorage (see logic.js)
   The main app opens DRS with ?role=&name=&zone=&agency=&lock=1 or posts {type:"drs-user", role, name, zone, agency, lock}. */
const notify=(ev)=>{try{window.DRS_NOTIFY&&window.DRS_NOTIFY(ev)}catch(e){}};
const _commitSend0=commitSend;commitSend=function(key,to,x,text,orig,btn){_commitSend0(key,to,x,text,orig,btn);try{window.DRS_SEND&&window.DRS_SEND({key,to,title:x.title,role:x.role,text,original:orig||null,language:REPLANG,at:Date.now()})}catch(e){}};
