const _addIssueBtn=$("addIssue").onclick;$("addIssue").onclick=()=>{const t0=Date.now();_addIssueBtn();setTimeout(()=>{const x=store.get("kc-issues",[])[0];if(x&&x.times&&x.times[0]>=t0-50)notify({type:"afm_ticket",title:"New AFM complaint "+x.id,body:x.prob+(x.loc?" @ "+x.loc:""),toRoles:["afm","mgr"],ref:x.id})},0)};
const _setSt0=setSt;setSt=function(x,st,note,extra){_setSt0(x,st,note,extra);notify({type:"ticket_update",title:`${x.id}: ${I["s_"+st][0]}`,body:x.prob+(note?" – "+note:""),toRoles:st==="assigned"?["agency"]:st==="done"?["afm"]:["afm","mgr",x.from],ref:x.id})};
const _syncAlerts0=syncAlerts;syncAlerts=function(){const before=new Set(Object.keys(store.get("kc-alerts",{})));_syncAlerts0();const now=store.get("kc-alerts",{});Object.values(now).filter(a=>!before.has(a.id)).forEach(a=>notify({type:"animal_alert",title:`${a.type}${a.animal?": "+a.animal:""}`,body:[a.cage,a.details].filter(Boolean).join(" – "),toRoles:AL_TO,ref:a.id}))};
