let rxForm=null,rxSite="",doseOpen=null,rxEditId=null;
const rxSites=()=>[...new Set(RX.map(r=>r.site).filter(Boolean))];
function rxFormHTML(){const r=rxForm;return `<div class="form" style="margin-top:12px">
 <div class="row"><div class="field"><span>${t("rxAnimal")}</span><input type="text" data-rx="animal" value="${esc(r.animal)}" list="animalList"></div><div class="field"><span>${t("rxId")}</span><input type="text" data-rx="aid" value="${esc(r.aid)}"></div></div>
 <div class="row"><div class="field"><span>${t("rxSite")}</span><input type="text" data-rx="site" value="${esc(r.site)}"></div><div class="field"><span>${t("rxCage")}</span><input type="text" data-rx="cage" value="${esc(r.cage)}"></div></div>
 <div class="field"><span>${t("rxDx")}</span><input type="text" data-rx="dx" value="${esc(r.dx)}"></div>
 <div class="row"><div class="field"><span>${t("rxMed")}</span><input type="text" data-rx="med" value="${esc(r.med)}"></div><div class="field"><span>${t("rxDose")}</span><input type="text" data-rx="dose" value="${esc(r.dose)}"></div></div>
 <div class="field"><span class="lbl">${t("rxRoute")}</span><div class="seg">${ROUTES.map(o=>`<label><input type="radio" name="rxr" value="${o}" data-rx="route" ${r.route===o?"checked":""}><span>${tv(o)}</span></label>`).join("")}</div></div>
 <div class="field"><span>${t("rxTimes")}</span><input type="text" data-rx="times" value="${esc(r.times)}"></div>
 <div class="row"><div class="field"><span>${t("rxStart")}</span><input type="date" data-rx="start" value="${r.start}"></div><div class="field"><span>${t("rxDays")}</span><input type="number" min="1" data-rx="days" value="${r.days}"></div></div>
 <div class="field"><span>${t("rxInstr")}</span><textarea data-rx="instr">${esc(r.instr)}</textarea></div><div class="field"><span>${t("rxFollow")}</span><input type="date" data-rx="follow" value="${r.follow||""}"></div>
 ${rxEditId?`<div class="field"><span>${t("changeWhy")}</span><input type="text" data-rx="why" value=""></div>`:""}
 <div class="btns"><button class="btn" id="rxSaveBtn">${t("rxSave")}</button><button class="btn ghost" id="rxCancel">${t("cancel")}</button></div></div>`}
function last7(r){const ds=[...Array(7)].map((_,i)=>addDays(TODAY,i-6)).filter(d=>rxDays(r).includes(d));const tm=rxTimes(r);
 return `<div class="rxgrid" style="grid-template-columns:auto repeat(${tm.length},1fr)"><span></span>${tm.map(x=>`<b>${x}</b>`).join("")}${ds.map(d=>`<span>${shortD(d)}</span>${tm.map(x=>{const rec=(r.doses||{})[d+"|"+x];const over=!rec&&(d<TODAY||(d===TODAY&&x<nowHM()));return `<i class="${rec?DCLS[rec.st]:over?"bad":""}" title="${rec?tv(rec.note||""):""}">${rec?({given:"✓",partial:"½",refused:"R",missed:"✗"}[rec.st]):over?"!":"·"}</i>`}).join("")}`).join("")}</div>`}
function rxCard(r,mode){const sl=slotsOn(r,TODAY);const dn=rxDays(r).indexOf(TODAY)+1;const v=(r.verify||{})[TODAY];
 const instr=`<div class="rxcol"><span class="lbl">${t("vetInstr")}</span><p><b>${esc(r.med)}</b> · ${esc(r.dose)} · ${esc(tv(r.route||""))}</p><p>${rxTimes(r).join(", ")} · ${t("dayN",{n:dn>0?dn:"-",t:r.days})}</p>${r.instr?`<p>${esc(r.instr)}</p>`:""}${r.follow?`<p>${t("rxFollow")}: ${shortD(r.follow)}</p>`:""}</div>`;
 const slots=sl.length?sl.map(s=>`<button class="slot ${s.rec?DCLS[s.rec.st]:s.state==="over"?"bad":""}" data-slot="${r.id}|${s.k}" ${mode!=="pvet"?"disabled":""}><b>${s.tm}</b><span>${s.rec?t(DST[s.rec.st]):s.state==="over"?t("overdue"):t("due")}</span></button>`).join(""):`<p class="counter">-</p>`;
 const rec=`<div class="rxcol"><span class="lbl">${t("pvRecord")} · ${t("tToday")}</span><div class="slots">${slots}</div>${sl.filter(s=>s.rec&&s.rec.note).map(s=>`<p class="counter" style="margin:4px 0 0">${s.tm}: ${esc(s.rec.note)}</p>`).join("")}</div>`;
 let panel="";if(mode==="pvet"&&doseOpen&&doseOpen.startsWith(r.id+"|")){panel=`<div class="form" style="margin-top:8px"><div class="seg">${Object.keys(DST).map(k=>`<label><input type="radio" name="dst" value="${k}" ${k==="given"?"checked":""}><span>${t(DST[k])}</span></label>`).join("")}</div><div class="field" style="margin-top:8px"><span>${t("doseNote")}</span><textarea id="doseNote"></textarea></div><button class="btn" data-dosesave="${esc(doseOpen)}">${t("saveDose")}</button></div>`}
 return `<div class="issue rx ${r.status!=="active"?"fixed":""} ${r.pending?"pendrx":""}"><div class="top"><strong>${esc(r.animal)}${r.aid?` <small>${esc(r.aid)}</small>`:""}</strong><small>${esc(r.site||"")}${r.cage?" · "+esc(r.cage):""}</small></div><small>${esc(r.dx||"")} · ${t(r.status)}</small>
 ${r.pending?`<p class="warn" style="margin:6px 0">${t("needVetOk")}${mode==="vet"?` <button class="btn" data-rxok="${r.id}" style="width:auto;margin-left:6px;padding:6px 10px">${t("confirmRx")}</button>`:""}</p>`:""}
 <div class="rxside">${instr}${rec}</div>${panel}
 ${mode!=="pvet"?`<span class="lbl" style="margin-top:8px">${t("last7")}</span>${last7(r)}
  ${v?`<p class="${v.ok?"okmsg":"warn"}" style="margin:8px 0">${t("verifiedOn",{d:shortD(TODAY),r:v.ok?t("followedOk"):t("followedNo")+(v.note?": "+esc(v.note):"")})}</p>`:""}
  ${r.status==="active"&&mode==="vet"?`<div class="acts" style="margin-top:8px"><button class="btn" data-rxv="${r.id}" data-ok="1">${t("followedOk")}</button><button class="btn ghost" data-rxv="${r.id}" data-ok="0">${t("followedNo")}</button></div>
  <div class="acts" style="margin-top:6px"><button class="x" data-rxedit="${r.id}">${t("changeRx")}</button><button class="x" data-rxfu="${r.id}">${t("addFollow")}</button><button class="x" data-rxend="${r.id}" data-v="completed">${t("markDoneRx")}</button><button class="x" data-rxend="${r.id}" data-v="stopped">${t("stopRx")}</button></div>`:""}`:""}
 ${(r.hist||[]).length?`<details class="hist"><summary>${t("history")} (${r.hist.length})</summary>${r.hist.map(h=>`<div class="logi"><small>${hm(h.at)} · ${esc(L2(ROLE_LABEL[h.by]||["",""]))}</small>${esc(h.text)}</div>`).join("")}</details>`:""}</div>`}
function rRx(){const el=$("rxBody");if(!el)return;reload9();const mode=ROLE==="vet"?"vet":ROLE==="pvet"?"pvet":"view";const sites=rxSites();
 const list=RX.filter(r=>(!rxSite||r.site===rxSite)).sort((a,b)=>({active:0,completed:1,stopped:2}[a.status]-{active:0,completed:1,stopped:2}[b.status])||(a.site||"").localeCompare(b.site||""));
 el.innerHTML=`<p class="intro" style="margin-top:0">${t("rxP")}</p>${mode==="view"?`<button class="crumb" data-backdash="1">${t("tDash")}</button>`:`<button class="btn" id="rxNew">${mode==="vet"?t("newRx"):t("newRxPv")}</button>`}<div id="rxFormBox">${rxForm?rxFormHTML():""}</div>
 <div class="chips" style="margin:12px -18px 10px;padding:0 18px 6px"><button class="chip" aria-pressed="${!rxSite}" data-rxs="">${t("allSites")}</button>${sites.map(s=>`<button class="chip" aria-pressed="${rxSite===s}" data-rxs="${esc(s)}">${esc(s)}</button>`).join("")}</div>
 ${list.length?list.map(r=>rxCard(r,mode)).join(""):`<p class="empty">${t("nothing")}</p>`}`}
document.addEventListener("input",e=>{const k=e.target.dataset&&e.target.dataset.rx;if(k&&rxForm){if(e.target.type==="radio"&&!e.target.checked)return;rxForm[k]=e.target.value}});
document.addEventListener("click",e=>{const id=e.target.id,b=e.target.closest("[data-slot],[data-dosesave],[data-rxs],[data-rxv],[data-rxedit],[data-rxfu],[data-rxend],[data-rxok]"),d=b?b.dataset:{};
 if(id==="rxNew"){rxEditId=null;rxForm={animal:"",aid:"",site:store.get("kc-mem-pv-site",""),cage:"",dx:"",med:"",dose:"",route:"Oral",times:"08:00, 20:00",start:TODAY,days:5,instr:"",follow:""};rRx();return}
 if(id==="rxCancel"){rxForm=null;rxEditId=null;rRx();return}
 if(id==="rxSaveBtn"){const r=rxForm;if(!r.animal.trim()||!r.med.trim()){toast(t("needName"));return}store.set("kc-mem-pv-site",r.site);
  if(rxEditId){const o=RX.find(x=>x.id===rxEditId);const ch=["med","dose","route","times","days","instr","follow"].filter(k=>String(o[k]||"")!==String(r[k]||"")).map(k=>`${t({med:"rxMed",dose:"rxDose",route:"rxRoute",times:"rxTimes",days:"rxDays",instr:"rxInstr",follow:"rxFollow"}[k])}: ${o[k]||"-"} → ${r[k]||"-"}`);
   Object.assign(o,{...r,why:undefined});o.hist=o.hist||[];o.hist.push({at:Date.now(),by:ROLE,text:(ch.join("; ")||t("changeRx"))+(r.why?` (${r.why})`:"")});o.changedAt=Date.now()}
  else RX.unshift({...r,id:"RX"+Date.now(),status:"active",pending:ROLE!=="vet",by:ROLE,doses:{},verify:{},hist:[{at:Date.now(),by:ROLE,text:`${r.med} ${r.dose} ${tv(r.route)} · ${r.times} · ${r.days} d`}]});
  rxSave();rxForm=null;rxEditId=null;rRx();return}
 if(!b)return;const r=RX.find(x=>x.id===(d.rxv||d.rxedit||d.rxfu||d.rxend||d.rxok||(d.slot||d.dosesave||"").split("|")[0]));
 if(d.rxs!==undefined){rxSite=d.rxs;rRx();return}
 if(d.slot&&ROLE==="pvet"){doseOpen=doseOpen===d.slot?null:d.slot;rRx();return}
 if(d.dosesave&&r){const [,dd,tm]=d.dosesave.split("|");const st=(document.querySelector("input[name=dst]:checked")||{}).value||"given";r.doses=r.doses||{};r.doses[dd+"|"+tm]={st,at:Date.now(),by:ROLE,note:$("doseNote").value.trim()};r.hist=r.hist||[];r.hist.push({at:Date.now(),by:ROLE,text:`${shortD(dd)} ${tm}: ${I[DST[st]][0]}${$("doseNote").value.trim()?" – "+$("doseNote").value.trim():""}`});rxSave();doseOpen=null;rRx();if(st!=="given")notify({type:"dose_missed",title:`${r.animal}: ${I[DST[st]][0]}`,body:`${r.med} ${tm}`,toRoles:["vet"]});return}
 if(d.rxv&&r){let note="";if(d.ok==="0"){note=prompt(t("whyNot"),"");if(note===null)return}r.verify=r.verify||{};r.verify[TODAY]={ok:d.ok==="1",note,at:Date.now()};r.hist.push({at:Date.now(),by:"vet",text:(d.ok==="1"?I.followedOk[0]:I.followedNo[0])+(note?": "+note:"")});rxSave();rRx();return}
 if(d.rxedit&&r){rxEditId=r.id;rxForm={...r};rRx();$("rxFormBox").scrollIntoView({behavior:"smooth"});return}
 if(d.rxfu&&r){const v=prompt(t("rxFollow")+" (YYYY-MM-DD)",r.follow||addDays(TODAY,3));if(!v)return;r.follow=v;r.hist.push({at:Date.now(),by:"vet",text:`${I.rxFollow[0]}: ${v}`});r.changedAt=Date.now();rxSave();rRx();return}
 if(d.rxend&&r){r.status=d.v;r.hist.push({at:Date.now(),by:"vet",text:I[d.v][0]});r.changedAt=Date.now();rxSave();rRx();return}
 if(d.rxok&&r){r.pending=false;r.hist.push({at:Date.now(),by:"vet",text:I.confirmRx[0]});r.changedAt=Date.now();rxSave();rRx()}});
