/* ---------- ticket numbers: <site>-<yy>-<work letter>-<0001>, restarting each year per site ----------
   Work letters: P Plumbing · F Fabrication (metal, mesh, welding) · C Carpentry & painting (wood work)
   E Electrical · M Masonry / civil · A AC & cooling · H Housekeeping / cleaning · Q Equipment · O Other
   One running number per site per year, so the number alone is unique; the letter shows the work type. */
const WORK_CODE={Plumbing:"P",Fabrication:"F",Mesh:"F",Carpentry:"C",Painting:"C",Electrical:"E",Civil:"M",AC:"A",Cleaning:"H",Equipment:"Q",Other:"O"};
const WORK_NAME={P:["Plumbing","प्लंबिंग"],F:["Fabrication / metal","फैब्रिकेशन / धातु"],C:["Carpentry & painting","बढ़ईगिरी और पेंटिंग"],E:["Electrical","बिजली"],M:["Masonry / civil","चिनाई / सिविल"],A:["AC & cooling","AC और कूलिंग"],H:["Housekeeping","सफ़ाई"],Q:["Equipment","उपकरण"],O:["Other","अन्य"]};
function workCode(cat){if(WORK_CODE[cat])return WORK_CODE[cat];const c=String(cat||"").toLowerCase();
 if(/drain|water|pipe|tap|pool|leak|plumb|sewer|tank/.test(c))return "P";if(/weld|metal|mesh|gate|grill|lock|iron|steel|fabric/.test(c))return "F";
 if(/wood|carpent|paint|door frame|platform|nest|furniture/.test(c))return "C";if(/electric|light|power|wire|generator|bulb|switch/.test(c))return "E";
 if(/wall|floor|roof|civil|plaster|brick|moat|concrete|mason/.test(c))return "M";if(/\bac\b|cool|fan|chiller|hvac/.test(c))return "A";if(/clean|waste|garbage|sweep/.test(c))return "H";if(/machine|equip|vehicle|tool|pump/.test(c))return "Q";return "O"}
const YY=String(new Date().getFullYear()).slice(2);
function nextTicketId(cat){const L=workCode(cat);if(window.DRS_NEXT_TICKET)return window.DRS_NEXT_TICKET(SITE,YY,L); /* server can allocate numbers */
 const k="kc-tkn-"+YY;const n=store.get(k,0)+1;store.set(k,n);return `${ORG.tkCode(SITE)}-${YY}-${L}-${String(n).padStart(4,"0")}`}
function stampNewest(t0){const is=store.get("kc-issues",[]);const x=is[0];if(!x||!x.times||x.times[0]<t0-50||x._num)return null;
 x.id=nextTicketId(x.cat);x.wc=workCode(x.cat);x._num=1;x.site=SITE;x.byUid=ME?ME.uid:"";x.byName=ME?ME.name:"";store.set("kc-issues",is);issues=is;return x}
const _newIssue11=newIssue;newIssue=function(o){const t0=Date.now();_newIssue11(o);const x=stampNewest(t0);try{renderIssues()}catch(e){}return x};
const _addIssue11=$("addIssue").onclick;$("addIssue").onclick=()=>{const t0=Date.now();_addIssue11();stampNewest(t0);try{renderIssues()}catch(e){}};
