addView("admin","adminH","adminP");addView("secure","secureH","secureP");SCREEN_LBL.secure="tSecure";SCREEN_LBL.admin="tAdmin";
Object.keys(MORE).forEach(r=>{if(!MORE[r].includes("secure"))MORE[r].push("secure")});
const DEF_SET={exportRoles:["mgr","cur","ch","exec","sadmin","siteadmin"],officeOnly:["sadmin"],lockMin:5,signOutH:12};
const SETTINGS=()=>({...DEF_SET,...store.get("kc-settings",{})});
const UADM=()=>store.get("kc-useradm",{});
const uadm=uid=>UADM()[uid]||{status:"active",extra:[]};
function setUadm(uid,patch){const A=UADM();A[uid]={...(A[uid]||{status:"active",extra:[]}),...patch,by:ME?ME.uid:"",at:Date.now()};store.set("kc-useradm",A)}
function userExtra(){return ME?(uadm(ME.uid).extra||[]):[]}
const canAdmin=uid=>{if(!ME)return false;if(ME.role==="sadmin")return true;const p=ORG.user(uid);if(ME.role==="siteadmin")return !!p&&p.cluster===ME.cluster&&!["sadmin","exec"].includes(p.role);return false};
const EXTRA_VIEWS=[["maint","tMaint"],["verify","tVerify"],["afm","tIssues"],["inbox","tInbox"],["att","tAtt"],["timeline","timelineH"],["safety","safetyH"],["inv","tInv"],["xdash","tDash"],["roster","rosterH"],["etho","tEtho"],["events","evH"]];

/* ---------- guards on load ---------- */
const LOCAL={get:k=>{try{return JSON.parse(localStorage.getItem(k))}catch(e){return null}},set:(k,v)=>localStorage.setItem(k,JSON.stringify(v))};
function blockScreen(msg){document.body.insertAdjacentHTML("beforeend",`<div class="lockscr" id="blockScr"><div><b>DRS</b><p>${esc(msg)}</p><button class="btn" id="blkOut">${t("signOut")}</button></div></div>`)}
document.addEventListener("click",e=>{if(e.target.id==="blkOut"){DRS_RAW.set("drs-user","null");DRS_RAW.set("kc-role","null");location.reload()}});
(function guards(){if(!ME)return;const A=uadm(ME.uid),S0=SETTINGS();const sessKey="drs-sess-"+ME.uid;
 if(!LOCAL.get(sessKey))LOCAL.set(sessKey,Date.now());
 if(A.signoutAt&&A.signoutAt>LOCAL.get(sessKey)){localStorage.removeItem(sessKey);DRS_RAW.set("drs-user","null");DRS_RAW.set("kc-role","null");alert(t("signedOutRemote"));location.reload();return}
 const last=LOCAL.get("drs-last-active");if(last&&NOW()-last>S0.signOutH*3600000){DRS_RAW.set("drs-user","null");DRS_RAW.set("kc-role","null");localStorage.removeItem("drs-last-active");location.reload();return}
 if(A.status==="suspended")return blockScreen(t("blockedSusp"));
 if((S0.officeOnly||[]).includes(ME.role)&&!LOCAL.get("drs-office-net"))return blockScreen(t("blockedNet"));
 if(A.status==="readonly")document.body.classList.add("readonly");
 if(!(S0.exportRoles||[]).includes(ME.role))document.body.classList.add("noexport")})();

/* ---------- app lock ---------- */
const pinHash=(pin,salt)=>{let h=2166136261;const s=salt+":"+pin;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}for(let r=0;r<2000;r++){h^=h>>>13;h=Math.imul(h,1540483477)}return (h>>>0).toString(16)};
/* production: the DRS app keeps the PIN in the phone's secure keystore and offers fingerprint/face (window.DRS_BIOMETRIC) */
const PIN=()=>store.get("kc-pin",null);
let LOCKED=false;
function showLock(){if(LOCKED||!PIN()||$("blockScr"))return;LOCKED=true;document.body.insertAdjacentHTML("beforeend",`<div class="lockscr" id="lockScr"><div><b>DRS</b><p>🔒 ${t("lockedH")}</p><input type="password" inputmode="numeric" maxlength="4" id="lkPin" placeholder="${t("enterPin")}" aria-label="${t("enterPin")}" autocomplete="off"><button class="btn" id="lkGo">${t("unlock")}</button>${window.DRS_BIOMETRIC?`<button class="btn ghost" id="lkBio">${t("useBio")}</button>`:""}<p class="counter" id="lkMsg"></p></div></div>`);setTimeout(()=>$("lkPin")&&$("lkPin").focus(),50)}
function tryUnlock(){const p=PIN();if(p&&pinHash($("lkPin").value,p.salt)===p.hash){$("lockScr").remove();LOCKED=false;LOCAL.set("drs-last-active",NOW())}else{$("lkMsg").textContent=t("wrongPin");$("lkPin").value=""}}
document.addEventListener("click",e=>{if(e.target.id==="lkGo")tryUnlock();if(e.target.id==="lkBio")Promise.resolve(window.DRS_BIOMETRIC()).then(ok=>{if(ok){$("lockScr").remove();LOCKED=false;LOCAL.set("drs-last-active",NOW())}})});
document.addEventListener("keydown",e=>{if(e.target.id==="lkPin"&&e.key==="Enter")tryUnlock()});
["click","keydown","touchstart"].forEach(ev=>document.addEventListener(ev,()=>{if(!LOCKED)LOCAL.set("drs-last-active",NOW())},{passive:true}));
function lockCheck(){if(!ME||LOCKED)return;const last=LOCAL.get("drs-last-active")||NOW();if(PIN()&&NOW()-last>SETTINGS().lockMin*60000)showLock()}
setInterval(lockCheck,15000);setTimeout(lockCheck,300);

RENDER.secure=()=>{const p=PIN();$("secureBody").innerHTML=`<div class="ecard"><p>${p?t("pinOn",{m:SETTINGS().lockMin}):t("pinOff")}</p>
 <div class="row"><div class="field"><span>${t("pinNew")}</span><input type="password" inputmode="numeric" maxlength="4" id="pn1" autocomplete="off"></div><div class="field"><span>${t("pinAgain")}</span><input type="password" inputmode="numeric" maxlength="4" id="pn2" autocomplete="off"></div></div>
 <div class="btns"><button class="btn" id="pnSave">${p?t("pinChange"):t("pinSet")}</button>${p?`<button class="btn ghost" id="pnLock">${t("lockNow")}</button>`:""}</div>${p?`<button class="x" id="pnDel" style="margin-top:8px">${t("pinRemove")}</button>`:""}</div>
 <div id="quietBox"></div><button class="btn ghost" id="secOut" style="margin-top:14px">${t("signOut")}</button>`;if(typeof rQuiet==="function")rQuiet()};
document.addEventListener("click",e=>{const id=e.target.id;
 if(id==="pnSave"){const a=$("pn1").value,b=$("pn2").value;if(!/^\d{4}$/.test(a)){$("pn1").focus();return}if(a!==b){toast(t("pinMismatch"));return}const salt=Math.random().toString(36).slice(2);store.set("kc-pin",{salt,hash:pinHash(a,salt)});toast(t("pinSaved"));RENDER.secure()}
 if(id==="pnDel"){store.set("kc-pin",null);RENDER.secure()}if(id==="pnLock")showLock();
 if(id==="secOut"){DRS_RAW.set("drs-user","null");DRS_RAW.set("kc-role","null");location.reload()}});

/* ---------- controlled, watermarked, logged exports ---------- */
const canExport=()=>!!ME&&(SETTINGS().exportRoles||[]).includes(ME.role);
const wm=()=>t("exportedBy",{n:ME?ME.name:"-",r:ME?L2(ROLE_LABEL[ME.role]||["",""]):"-",d:new Date(NOW()).toLocaleString()})+" · DRS · "+SITE;
const _makeDocx12=makeDocx;makeDocx=t2=>_makeDocx12(t2+"\n\n"+wm());
const _makePdf12=makePdf;makePdf=t2=>_makePdf12(t2+"\n\n"+wm());
const _exSheets12=exSheets;exSheets=function(){const s=_exSheets12();s["Export info"]=[["Exported by",ME?ME.name:""],["Role",ME?ROLE_LABEL[ME.role][0]:""],["EP",ME?ME.ep:""],["Site",SITE],["Time",new Date(NOW()).toLocaleString()]];return s};
const _saveFile12=saveFile;saveFile=async function(name,data){if(!canExport()){toast(t("noExport"));return}
 if(typeof data==="string")data=(name.endsWith(".csv")?`"${wm()}"\n`:wm()+"\n\n")+data;
 const log=store.get("kc-exportlog",[]);log.unshift({name,by:ME?ME.uid:"",byName:ME?ME.name:"",role:ROLE,at:Date.now()});store.set("kc-exportlog",log.slice(0,300));return _saveFile12(name,data)};

/* ---------- Admin screen ---------- */
let admQ="",admRole="",admSite="",admOpen=null,admTransfer=null;
function admPeople(){const sc=new Set(ORG.scopeSites(ME)),seen=new Set();return ORG.staff().filter(p=>p.uid!==ME.uid&&canAdmin(p.uid)&&(!p.site||sc.has(p.site)||ME.role==="sadmin")).filter(p=>!seen.has(p.uid)&&seen.add(p.uid))}
RENDER.admin=()=>{if(!["sadmin","siteadmin"].includes(ROLE)){$("adminBody").innerHTML=`<p class="empty">${t("nothing")}</p>`;return}
 const all=admPeople();const q=admQ.toLowerCase();const list=all.filter(p=>(!admRole||p.role===admRole)&&(!admSite||p.site===admSite||p.cluster===admSite)&&(!q||(p.name+" "+p.ep+" "+p.site+" "+p.antsRole).toLowerCase().includes(q)));
 const S0=SETTINGS();const sites=ORG.scopeSites(ME);const roleOpts=[...new Set(all.map(p=>p.role))];
 const badge=st=>`<span class="tag ${st==="active"?"ok":st==="readonly"?"age":""}">${t(st==="active"?"stActive":st==="readonly"?"stRO":"stSusp")}</span>`;
 $("adminBody").innerHTML=`<h2 class="dh">👥 ${t("usersH")}</h2>
 <input type="text" class="search" id="admQ" placeholder="${t("search")}" value="${esc(admQ)}">
 <div class="row" style="margin-top:8px"><div class="field" style="margin:0"><select class="full" id="admRole"><option value="">${t("allRoles")}</option>${roleOpts.map(r=>`<option value="${r}" ${r===admRole?"selected":""}>${esc(L2(ROLE_LABEL[r]||[r,r]))}</option>`).join("")}</select></div>
 <div class="field" style="margin:0"><select class="full" id="admSite"><option value="">${t("allClusters")}</option>${[...new Set(sites.map(s=>ORG.clusterOf(s)))].map(c=>`<option value="${c}" ${c===admSite?"selected":""}>${c}</option>`).join("")}${sites.map(s=>`<option ${s===admSite?"selected":""}>${s}</option>`).join("")}</select></div></div>
 <p class="counter">${t("showing",{n:Math.min(40,list.length),t:list.length})}</p>
 ${list.slice(0,40).map(p=>{const A=uadm(p.uid);const open=admOpen===p.uid;return `<div class="act usr"><span><b>${esc(p.name)}</b> <small>${p.ep}</small> ${badge(A.status||"active")}<br><small>${esc(L2(ROLE_LABEL[p.role]||[p.role,p.role]))} · ${esc(p.antsRole)}${p.site?" · "+p.site:p.cluster?" · "+p.cluster:""}${p.zone?" · "+p.zone:""}</small>${(A.extra||[]).length?`<br><small>+ ${(A.extra||[]).map(v=>t((EXTRA_VIEWS.find(x=>x[0]===v)||[v,v])[1])).join(", ")}</small>`:""}</span><button class="x" data-admopen="${p.uid}">${open?t("close"):"⋯"}</button></div>
 ${open?`<div class="ecard admpanel"><div class="acts">${A.status==="suspended"?`<button class="btn" data-adm="active" data-uid="${p.uid}">${t("activate")}</button>`:`<button class="btn ghost" data-adm="suspended" data-uid="${p.uid}">${t("suspend")}</button>`}${A.status==="readonly"?`<button class="btn ghost" data-adm="active" data-uid="${p.uid}">${t("fullAccess")}</button>`:`<button class="btn ghost" data-adm="readonly" data-uid="${p.uid}">${t("readOnly")}</button>`}</div>
  <span class="lbl" style="margin-top:10px">${t("extraAcc")}</span><div class="seg">${EXTRA_VIEWS.filter(([v])=>!(ROLES[p.role]||{tabs:[]}).tabs.some(x=>x[0]===v)).map(([v,k])=>`<label><input type="checkbox" data-admx="${p.uid}" value="${v}" ${(A.extra||[]).includes(v)?"checked":""}><span>${t(k)}</span></label>`).join("")}</div>
  <div class="acts" style="margin-top:10px"><button class="x" data-admout="${p.uid}">${t("signOutDev")}</button><button class="x" data-admtr="${p.uid}">${t("transfer")}</button>${window.DRS_RESET_PIN?`<button class="x" data-admpin="${p.uid}">${t("resetPin")}</button>`:""}</div><p class="counter" id="admPinMsg-${p.uid}"></p>
  ${admTransfer===p.uid?`<div class="field" style="margin-top:8px"><span>${t("transferTo",{a:esc(p.name)})}</span><select class="full" id="trTo">${ORG.staff().filter(x=>x.uid!==p.uid&&x.site===p.site&&x.role===p.role||x.uid!==p.uid&&x.site===p.site&&p.site).slice(0,30).map(x=>`<option value="${x.uid}">${esc(x.name)} · ${esc(L2(ROLE_LABEL[x.role]||["",""]))}</option>`).join("")}</select></div><button class="btn" data-trgo="${p.uid}">${t("transfer")}</button>`:""}</div>`:""}`}).join("")}
 ${ROLE==="sadmin"?`<h2 class="dh">🛡 ${t("settingsH")}</h2><div class="ecard"><span class="lbl">${t("exportWho")}</span><div class="seg">${Object.keys(ROLES).map(r=>`<label><input type="checkbox" data-set="exportRoles" value="${r}" ${(S0.exportRoles||[]).includes(r)?"checked":""}><span>${esc(L2(ROLE_LABEL[r]||[r,r]))}</span></label>`).join("")}</div>
  <span class="lbl" style="margin-top:12px">${t("officeOnly")}</span><div class="seg">${Object.keys(ROLES).map(r=>`<label><input type="checkbox" data-set="officeOnly" value="${r}" ${(S0.officeOnly||[]).includes(r)?"checked":""}><span>${esc(L2(ROLE_LABEL[r]||[r,r]))}</span></label>`).join("")}</div>
  <div class="row" style="margin-top:12px"><div class="field"><span>${t("lockMin")}</span><input type="number" min="1" data-setn="lockMin" value="${S0.lockMin}"></div><div class="field"><span>${t("signOutH")}</span><input type="number" min="1" data-setn="signOutH" value="${S0.signOutH}"></div></div></div>`:""}
 <h2 class="dh">🔗 ${t("mapH")}</h2><p class="counter">${t("mapP")}</p><div class="tblwrap"><table class="rtbl"><thead><tr><th>ANTS</th><th>DRS</th><th>${t("people")}</th></tr></thead><tbody>${Object.entries(ORG.roleMap()).map(([a,r])=>`<tr><td>${esc(a)}</td><td>${esc(L2(ROLE_LABEL[r]||[r,r]))}</td><td>${ORG.staff().filter(p=>p.antsRole===a).length}</td></tr>`).join("")}</tbody></table></div>
 <h2 class="dh">📥 ${t("exportLogH")}</h2>${store.get("kc-exportlog",[]).slice(0,10).map(l=>`<div class="act"><span>${esc(l.name)}<br><small>${esc(l.byName)} · ${hm(l.at)}</small></span></div>`).join("")||`<p class="empty">${t("nothing")}</p>`}
 <h2 class="dh">🧪 ${t("demoTools")}</h2><div class="ecard"><p class="counter">${LOCAL.get("drs-office-net")?"✓ This phone is on the office network.":"This phone is not on the office network."} The office network is set on the server (OFFICE_IPS).</p>
 <p class="counter">${t("clockFwd")} · ${t("clockNow",{h:Math.round((+(localStorage.getItem("drs-now-offset")||0))/3600000)})}</p><div class="acts"><button class="btn ghost" data-fwd="1">+1 h</button><button class="btn ghost" data-fwd="3">+3 h</button><button class="btn ghost" data-fwd="7">+7 h</button><button class="btn ghost" data-fwd="24">+1 day</button><button class="x" data-fwd="0">${t("clockReset")}</button></div></div>`};
document.addEventListener("input",e=>{if(e.target.id==="admQ"){admQ=e.target.value;const pos=e.target.selectionStart;RENDER.admin();const s=$("admQ");s.focus();s.setSelectionRange(pos,pos)}});
document.addEventListener("change",e=>{const id=e.target.id,d=e.target.dataset||{};
 if(id==="admRole"){admRole=e.target.value;RENDER.admin()}if(id==="admSite"){admSite=e.target.value;RENDER.admin()}
 if(d.admx){const A=uadm(d.admx);const ex=new Set(A.extra||[]);e.target.checked?ex.add(e.target.value):ex.delete(e.target.value);setUadm(d.admx,{extra:[...ex]});RENDER.admin()}
 if(d.set){const s=store.get("kc-settings",{});const cur0=new Set((s[d.set]||DEF_SET[d.set]||[]));e.target.checked?cur0.add(e.target.value):cur0.delete(e.target.value);s[d.set]=[...cur0];store.set("kc-settings",s)}
 if(d.setn){const s=store.get("kc-settings",{});s[d.setn]=Math.max(1,+e.target.value||DEF_SET[d.setn]);store.set("kc-settings",s)}
 if(id==="offSim")LOCAL.set("drs-office-net",e.target.checked)});
document.addEventListener("click",async e=>{const pb=e.target.closest("[data-admpin]");if(pb&&window.DRS_RESET_PIN){const uid=pb.dataset.admpin,m=$("admPinMsg-"+uid);m.textContent="…";try{const r=await window.DRS_RESET_PIN(uid);m.textContent=r.message}catch(err){m.textContent=String(err.message||err)}}});
document.addEventListener("click",e=>{const b=e.target.closest("[data-admopen],[data-adm],[data-admout],[data-admtr],[data-trgo],[data-fwd]");if(!b)return;const d=b.dataset;
 if(d.admopen){admOpen=admOpen===d.admopen?null:d.admopen;admTransfer=null;RENDER.admin()}
 if(d.adm){setUadm(d.uid,{status:d.adm});toast(t(d.adm==="active"?"stActive":d.adm==="readonly"?"stRO":"stSusp"));RENDER.admin()}
 if(d.admout){setUadm(d.admout,{signoutAt:Date.now()});toast(t("signOutDev")+" ✓")}
 if(d.admtr){admTransfer=admTransfer===d.admtr?null:d.admtr;RENDER.admin()}
 if(d.trgo){const to=$("trTo").value;const n=transferWork(d.trgo,to);toast(t("transferDone",{n}));admTransfer=null;RENDER.admin()}
 if(d.fwd!==undefined){localStorage.setItem("drs-now-offset",d.fwd==="0"?0:(+(localStorage.getItem("drs-now-offset")||0))+(+d.fwd)*3600000);RENDER.admin();if(typeof tickAll==="function")tickAll()}});
/* move open work owned by one person to another (all lists that record an owner) */
function transferWork(from,to){const p=ORG.user(from);const sites=p&&p.site?[p.site]:ORG.scopeSites(ME);let n=0;const toP=ORG.user(to);
 const fix=o=>{let c=0;["byUid","uid","ownerUid","assigneeUid"].forEach(f=>{if(o&&o[f]===from){o[f]=to;if(f==="byUid"&&o.byName)o.byName=toP.name;c=1}});return c};
 sites.forEach(sc=>{["kc-issues","kc-events","kc-incidents","kc-shifts","kc-plans","kc-inv","kc-leave","kc-pmjobs"].forEach(k=>{const L=storeAt.get(sc,k,null);if(!Array.isArray(L))return;let ch=0;L.forEach(o=>{if(o.st==="closed"||o.status==="closed")return;const c=fix(o);if(o.actions)o.actions.forEach(a=>{const c2=fix(a);ch+=c2;n+=c2});ch+=c;n+=c});if(ch)storeAt.set(sc,k,L)})});
 const N=store.get("kc-notices",[]);let nc=0;N.forEach(x=>{if(x.byUid===from&&!x.closed){x.byUid=to;x.byName=toP.name;nc++}});if(nc){store.set("kc-notices",N);n+=nc}
 return n}

/* =====================================================================
   ENGINE 13 — Compulsory notices, shifting notices, priority & quiet hours,
               escalation ladder, daily digest
   Rules (agreed):
     • A compulsory notice shows a RED BANNER that cannot be dismissed until the person replies.
     • No reply after 2 h  → reminder.   No reply after 6 h → escalated to the next level.
     • Shifting: when a move is planned, Supervisors of both sites, Curator, Biologist, Vet
       and Manager get a compulsory notice; any change to date/time/destination asks everyone again.
     • Quiet hours: only Critical items pop up; everything else waits in the list.
   ===================================================================== */
Object.assign(I,{
 noticesH:["Notices","सूचनाएँ"],noticesP:["Important messages that need your reply, and replies you are waiting for.","ज़रूरी संदेश जिनका जवाब देना है, और जिनके जवाब का इंतज़ार है।"],
 ntBar:["{n} notice needs your reply","{n} सूचना का जवाब देना है"],ntBars:["{n} notices need your reply","{n} सूचनाओं का जवाब देना है"],ntOpen:["Reply now","अभी जवाब दें"],
 ntNew:["New compulsory notice","नई अनिवार्य सूचना"],ntTitle:["Title","शीर्षक"],ntBody:["Message","संदेश"],ntPri:["Priority","प्राथमिकता"],ntWho:["Who must reply","किसे जवाब देना है"],ntWhere:["Sites","साइट"],ntThisSite:["This site","यह साइट"],ntMyCluster:["My cluster","मेरा क्लस्टर"],ntAll:["All sites","सभी साइट"],
 ntSend:["Send notice","सूचना भेजें"],ntSent:["Notice sent to {n} people","{n} लोगों को सूचना भेजी"],ntNeed:["Add a title and choose who must reply","शीर्षक लिखें और चुनें किसे जवाब देना है"],
 ntPending:["Waiting for your reply","आपके जवाब का इंतज़ार"],ntMine:["Notices I sent","मेरी भेजी सूचनाएँ"],ntDone:["Replied","जवाब दिया"],ntEsc:["Escalated to you","आपको एस्केलेट"],ntNone:["Nothing waiting for you.","आपके लिए कुछ बाकी नहीं।"],
 ntComment:["Comment (needed for 'Need changes' / 'Can't')","टिप्पणी"],ntReplied:["Reply sent","जवाब भेजा"],ntReply:["Send reply","जवाब भेजें"],ntBoard:["Replies: {a} of {b}","जवाब: {b} में से {a}"],ntReminded:["reminded","याद दिलाया"],ntEscalated:["escalated to {r}","{r} को एस्केलेट"],
 ntCloseN:["Close notice","सूचना बंद करें"],ntClosed:["Closed","बंद"],ntUpdated:["Updated – please reply again","बदला गया – कृपया फिर जवाब दें"],ntFrom:["From {n}","{n} से"],ntShowAll:["Show all","सब दिखाएँ"],
 shNotice:["Animal shifting: {a}","जानवर शिफ्टिंग: {a}"],shToSite:["Destination site code (e.g. V2S4)","गंतव्य साइट कोड (जैसे V2S4)"],shLinked:["ANTS transfer","ANTS ट्रांसफ़र"],shAuto:["Shifting notice sent – everyone involved must reply.","शिफ्टिंग सूचना भेजी – सभी को जवाब देना है।"],
 quietH:["Quiet hours","शांत समय"],quietP:["During quiet hours only Critical items pop up. Others wait in the list.","शांत समय में सिर्फ गंभीर सूचनाएँ दिखती हैं।"],quietOn:["Use quiet hours","शांत समय चालू"],qFrom:["From","से"],qTo:["To","तक"],
 digestH:["Daily digest","दैनिक सार"],digestP:["Automatic summary of the site's day.","साइट के दिन का अपने-आप बना सार।"],tDigest:["Digest","सार"],dgTitle:["DRS · DAILY DIGEST","DRS · दैनिक सार"],
 dgAnimals:["Animals","जानवर"],dgMaint:["Maintenance","मेंटेनेंस"],dgPeople:["Staff","स्टाफ"],dgSafety:["Safety","सुरक्षा"],dgNotices:["Notices","सूचनाएँ"],dgOpened:["opened","खुले"],dgClosedN:["closed","बंद"],dgOverdue:["past time target","समय-सीमा पार"],dgPresent:["present","उपस्थित"],dgNoInc:["No incidents","कोई घटना नहीं"],dgPendingR:["replies pending","जवाब बाकी"]});
addView("notices","noticesH","noticesP");addView("digest","digestH","digestP");SCREEN_LBL.digest="tDigest";SCREEN_LBL.notices="tNotices";
["mgr","ch","exec","cur"].forEach(r=>{if(MORE[r]&&!MORE[r].includes("digest"))MORE[r].unshift("digest")});
V["Critical"]="गंभीर";V["Important"]="ज़रूरी";V["Information"]="जानकारी";V["Acknowledged / ready"]="समझ लिया / तैयार";V["Need changes"]="बदलाव चाहिए";V["Can't attend"]="नहीं आ सकते";
V["Health check done"]="स्वास्थ्य जाँच हो गई";V["Sedation needed"]="बेहोशी की दवा चाहिए";V["Not fit to move"]="ले जाने लायक नहीं";V["Keepers and route ready"]="कीपर और रास्ता तैयार";V["Approve"]="स्वीकृत";V["Hold"]="रोकें";V["Ready"]="तैयार";
const PRI=["Critical","Important","Information"];
const NT_OPTS=["Acknowledged / ready","Need changes","Can't attend"];
const SH_OPTS={vet:["Health check done","Sedation needed","Not fit to move"],sup:["Keepers and route ready","Need changes","Can't attend"],cur:["Approve","Hold","Need changes"],mgr:["Approve","Hold"],bio:["Ready","Need changes"],acur:["Ready","Need changes"]};
const CAN_NOTICE=["cur","mgr","ch","exec","sadmin","siteadmin"];
/* escalation ladder: who is "the next level" for each role */
const NEXT_UP={keeper:"sup",sup:"mgr",pvet:"vet",vet:"mgr",bio:"cur",acur:"cur",cur:"mgr",afm:"mgr",mgr:"ch",siteadmin:"sadmin",ch:"exec",agency:"afm"};
function nextUp(p){const r=NEXT_UP[p.role];if(!r)return null;if(r==="ch")return ORG.staff().find(x=>x.role==="ch"&&x.cluster===p.cluster);if(r==="exec")return ORG.staff().find(x=>x.role==="exec");if(r==="sadmin")return ORG.staff().find(x=>x.role==="sadmin");
 return ORG.staff().find(x=>x.role===r&&x.site===p.site&&(r!=="sup"||!p.zone||x.zone===p.zone))||ORG.staff().find(x=>x.role===r&&x.site===p.site)}
const REMIND_MS=2*3600000,ESC_MS=6*3600000;

/* ---------- data ---------- */
const NTS=()=>store.get("kc-notices",[]);const ntSave=L=>store.set("kc-notices",L);
const myPending=()=>ME?NTS().filter(n=>!n.closed&&(n.targets||[]).includes(ME.uid)&&!((n.resp||{})[ME.uid]&&(n.resp[ME.uid].rev||1)>=(n.rev||1))):[];
function createNotice(o){const L=NTS();const n={id:"NT"+Date.now()+Math.floor(Math.random()*999),rev:1,at:NOW(),byUid:ME?ME.uid:"",byName:ME?ME.name:"",byRole:ROLE,site:SITE,resp:{},remind:{},esc:{},closed:false,...o};
 n.targets=[...new Set(n.targets||[])].filter(u=>u!==n.byUid);L.unshift(n);ntSave(L);
 notify({type:"compulsory_notice",title:n.title,body:(n.body||"").slice(0,140),toUids:n.targets,priority:n.pri,ref:n.id});return n}
function targetsFor(roles,sites){return ORG.staff().filter(p=>roles.includes(p.role)&&(sites.includes(p.site)||(!p.site&&["ch","siteadmin"].includes(p.role)&&sites.some(s=>ORG.clusterOf(s)===p.cluster))||(p.role==="exec"&&roles.includes("exec")))).map(p=>p.uid)}
/* reminders & escalation — runs every minute on every phone (server does it in production) */
function tickAll(){const L=NTS();let ch=false;const now=NOW();
 L.forEach(n=>{if(n.closed)return;const since=n.revAt||n.at;(n.targets||[]).forEach(uid=>{const r=(n.resp||{})[uid];if(r&&(r.rev||1)>=(n.rev||1))return;
  if(now-since>REMIND_MS&&!(n.remind||{})[uid]){n.remind=n.remind||{};n.remind[uid]=now;ch=true;notify({type:"notice_reminder",title:"Reminder: "+n.title,toUids:[uid],priority:n.pri,ref:n.id})}
  if(now-since>ESC_MS&&!(n.esc||{})[uid]){const p=ORG.user(uid);const up=p&&nextUp(p);if(up){n.esc=n.esc||{};n.esc[uid]={to:up.uid,toName:up.name,toRole:up.role,at:now};ch=true;notify({type:"notice_escalation",title:"No reply: "+n.title,body:p.name+" has not replied in 6 hours",toUids:[up.uid],priority:"Important",ref:n.id})}}})});
 if(ch){ntSave(L);if(VIEW==="notices")RENDER.notices()}rNoticeBar()}
setInterval(()=>{if(!typingNow())tickAll()},60000);setTimeout(tickAll,800);

/* ---------- red banner on every screen ---------- */
(function(){const c=$("ctxBar");if(c&&!$("noticeBar"))c.insertAdjacentHTML("afterend",`<div id="noticeBar"></div>`)})();
function rNoticeBar(){const el=$("noticeBar");if(!el)return;const p=myPending();
 const tb=document.querySelector('.tab[data-v="notices"]');if(tb){const old=tb.querySelector(".badge.b13");if(old)old.remove();if(p.length)tb.insertAdjacentHTML("beforeend",`<span class="badge b13 hot">${p.length}</span>`)}
 if(!p.length||VIEW==="notices"){el.innerHTML="";return}const top=p.find(n=>n.pri==="Critical")||p[0];
 el.innerHTML=`<button class="ntbar" id="ntGo">⚠ <b>${t(p.length===1?"ntBar":"ntBars",{n:p.length})}</b><span>${esc(top.title)}</span><em>${t("ntOpen")} ›</em></button>`}
document.addEventListener("click",e=>{if(e.target.closest("#ntGo"))go("notices")});

/* ---------- Notices screen ---------- */
let ntForm=null,ntBoard=null;
function ntCard(n,mode){const r=(n.resp||{})[ME&&ME.uid];const opts=(n.roleOpts&&n.roleOpts[ROLE])||n.opts||NT_OPTS;const pend=mode==="pending";
 const tg=n.targets||[];const done=tg.filter(u=>n.resp&&n.resp[u]&&(n.resp[u].rev||1)>=(n.rev||1));
 return `<div class="issue nt pri-${(n.pri||"Information").toLowerCase()} ${n.closed?"fixed":""}"><div class="top"><strong>${n.kind==="shifting"?"🦓 ":""}${esc(n.title)}</strong><small>${hm(n.revAt||n.at)}</small></div>
 <small><span class="tag ${n.pri==="Critical"?"":"age"}">${tv(n.pri||"Information")}</span> ${t("ntFrom",{n:esc(n.byName||"")})} · ${esc(L2(ROLE_LABEL[n.byRole]||["",""]))} · ${esc(n.site||"")}</small>
 ${n.rev>1&&pend?`<p class="warn" style="margin:6px 0">${t("ntUpdated")}</p>`:""}${n.body?`<p style="margin:8px 0;white-space:pre-wrap">${esc(n.body)}</p>`:""}
 ${n.link&&n.link.ants?`<p class="counter">🔗 ${t("shLinked")}: <b>${esc(n.link.ants)}</b></p>`:""}
 ${typeof mediaStrip==="function"?mediaStrip("nt:"+n.id):""}
 ${pend?`<div class="seg ntopts">${opts.map((o,i)=>`<label><input type="radio" name="nto-${n.id}" value="${esc(o)}" ${i===0?"checked":""}><span>${esc(tv(o))}</span></label>`).join("")}</div><div class="field" style="margin-top:8px"><input type="text" id="ntc-${n.id}" placeholder="${t("ntComment")}"></div><button class="btn" data-ntreply="${n.id}">✓ ${t("ntReply")}</button>`
  :r?`<p class="okmsg">✓ ${esc(tv(r.choice))}${r.comment?" – "+esc(r.comment):""} · ${hm(r.at)}</p>`:""}
 ${mode==="mine"||mode==="board"?`<p class="counter">${t("ntBoard",{a:done.length,b:tg.length})}</p><div class="bar"><i style="width:${tg.length?Math.round(done.length/tg.length*100):0}%"></i></div>
  ${ntBoard===n.id?ntBoardHTML(n):`<button class="x" data-ntboard="${n.id}">${t("ntShowAll")}</button>`}${!n.closed&&n.byUid===(ME&&ME.uid)?` <button class="x" data-ntclose="${n.id}">${t("ntCloseN")}</button>`:""}`:""}</div>`}
function ntBoardHTML(n){const tg=n.targets||[];const rows=tg.map(u=>{const p=ORG.user(u)||{name:u,role:""};const r=(n.resp||{})[u];const ok=r&&(r.rev||1)>=(n.rev||1);const es=(n.esc||{})[u];
  return {p,r,ok,es,rm:(n.remind||{})[u]}}).sort((a,b)=>(a.ok-b.ok));
 return `<div class="ntboard">${rows.slice(0,60).map(x=>`<div class="act"><span><b>${esc(x.p.name)}</b> <small>${esc(L2(ROLE_LABEL[x.p.role]||["",""]))} · ${esc(x.p.site||x.p.cluster||"")}</small>${x.ok?`<br><small>✓ ${esc(tv(x.r.choice))}${x.r.comment?" – "+esc(x.r.comment):""}</small>`:`<br><small class="over">${x.es?t("ntEscalated",{r:esc(x.es.toName)}):x.rm?t("ntReminded"):t("pending")}</small>`}</span></div>`).join("")}${rows.length>60?`<p class="counter">+${rows.length-60}</p>`:""}</div>`}
RENDER.notices=()=>{if(!ME){$("noticesBody").innerHTML="";return}const L=NTS();const pend=myPending();const mine=L.filter(n=>n.byUid===ME.uid).slice(0,15);
 const escd=L.filter(n=>!n.closed&&Object.values(n.esc||{}).some(e=>e.to===ME.uid));const pendIds=new Set(pend.map(n=>n.id));const done=L.filter(n=>(n.targets||[]).includes(ME.uid)&&!pendIds.has(n.id)).slice(0,10);
 $("noticesBody").innerHTML=`${CAN_NOTICE.includes(ROLE)?`<button class="btn" id="ntNewBtn">${t("ntNew")}</button><div id="ntFormBox">${ntForm?ntFormHTML():""}</div>`:""}
 <h2 class="dh">⚠ ${t("ntPending")} (${pend.length})</h2>${pend.map(n=>ntCard(n,"pending")).join("")||`<p class="empty">${t("ntNone")}</p>`}
 ${escd.length?`<h2 class="dh">⬆ ${t("ntEsc")} (${escd.length})</h2>${escd.map(n=>ntCard(n,"board")).join("")}`:""}
 ${mine.length?`<h2 class="dh">📤 ${t("ntMine")}</h2>${mine.map(n=>ntCard(n,"mine")).join("")}`:""}
 ${done.length?`<h2 class="dh">✓ ${t("ntDone")}</h2>${done.map(n=>ntCard(n,"done")).join("")}`:""}`;rNoticeBar()};
function ntFormHTML(){const f=ntForm;const roles=Object.keys(ROLES).filter(r=>!["sadmin","siteadmin","agency"].includes(r));const scopeOpts=ME.role==="exec"||ME.role==="sadmin"?["this","cluster","all"]:ME.role==="ch"||ME.role==="siteadmin"?["this","cluster"]:["this"];
 return `<div class="form" style="margin-top:12px"><div class="field"><span>${t("ntTitle")}</span><input type="text" data-nt="title" value="${esc(f.title)}"></div><div class="field"><span>${t("ntBody")}</span><textarea data-nt="body">${esc(f.body)}</textarea></div>
 <div class="field"><span class="lbl">${t("ntPri")}</span><div class="seg">${PRI.map(p=>`<label><input type="radio" name="ntp" data-nt="pri" value="${p}" ${f.pri===p?"checked":""}><span>${tv(p)}</span></label>`).join("")}</div></div>
 <div class="field"><span class="lbl">${t("ntWho")}</span><div class="seg">${roles.map(r=>`<label><input type="checkbox" data-nt="roles" value="${r}" ${f.roles.includes(r)?"checked":""}><span>${esc(L2(ROLE_LABEL[r]||[r,r]))}</span></label>`).join("")}</div></div>
 <div class="field"><span class="lbl">${t("ntWhere")}</span><div class="seg">${scopeOpts.map(s=>`<label><input type="radio" name="nts" data-nt="scope" value="${s}" ${f.scope===s?"checked":""}><span>${t({this:"ntThisSite",cluster:"ntMyCluster",all:"ntAll"}[s])}</span></label>`).join("")}</div></div>
 <div id="ntMedia">${typeof mediaBox==="function"?mediaBox("ntdraft:"+f.key):""}</div>
 <div class="btns"><button class="btn gold" id="ntSendBtn">${t("ntSend")}</button><button class="btn ghost" id="ntCancel">${t("cancel")}</button></div></div>`}
document.addEventListener("input",e=>{const k=e.target.dataset&&e.target.dataset.nt;if(!k||!ntForm)return;if(k==="roles")ntForm.roles=[...document.querySelectorAll('[data-nt="roles"]:checked')].map(x=>x.value);else if(e.target.type==="radio"){if(e.target.checked)ntForm[k]=e.target.value}else ntForm[k]=e.target.value});
document.addEventListener("click",e=>{const id=e.target.id,b=e.target.closest("[data-ntreply],[data-ntboard],[data-ntclose]"),d=b?b.dataset:{};
 if(id==="ntNewBtn"){ntForm={title:"",body:"",pri:"Important",roles:["sup","keeper"],scope:"this",key:"K"+Date.now()};RENDER.notices()}
 if(id==="ntCancel"){ntForm=null;RENDER.notices()}
 if(id==="ntSendBtn"){const f=ntForm;if(!f.title.trim()||!f.roles.length){toast(t("ntNeed"));return}
  const sites=f.scope==="all"?ORG.sites().map(s=>s.code):f.scope==="cluster"?ORG.sites().filter(s=>s.cluster===(ME.cluster||ORG.clusterOf(SITE))).map(s=>s.code):[SITE];
  const n=createNotice({kind:"notice",title:f.title.trim(),body:f.body.trim(),pri:f.pri,roles:f.roles,sites,targets:targetsFor(f.roles,sites)});
  if(typeof moveMedia==="function")moveMedia("ntdraft:"+f.key,"nt:"+n.id);toast(t("ntSent",{n:n.targets.length}));ntForm=null;RENDER.notices()}
 if(d.ntreply){const L=NTS();const n=L.find(x=>x.id===d.ntreply);const ch=(document.querySelector(`input[name="nto-${n.id}"]:checked`)||{}).value;const cm=($("ntc-"+n.id)||{}).value||"";
  if(/Need changes|Can't|Hold|Not fit|Sedation/.test(ch)&&!cm.trim()){$("ntc-"+n.id).focus();toast(t("ntComment"));return}
  n.resp=n.resp||{};n.resp[ME.uid]={choice:ch,comment:cm.trim(),at:NOW(),rev:n.rev||1,role:ROLE};ntSave(L);toast(t("ntReplied"));
  if(/Need changes|Can't|Hold|Not fit/.test(ch))notify({type:"notice_reply",title:ME.name+": "+ch,body:n.title+" – "+cm,toUids:[n.byUid],priority:"Important",ref:n.id});RENDER.notices()}
 if(d.ntboard){ntBoard=ntBoard===d.ntboard?null:d.ntboard;RENDER.notices()}
 if(d.ntclose){const L=NTS();const n=L.find(x=>x.id===d.ntclose);n.closed=true;ntSave(L);RENDER.notices()}});

/* ---------- Shifting → compulsory notice ---------- */
(function(){const F=FORMS.shift;if(F&&!F.sections[0].fields.some(f=>f.k==="toSite"))F.sections[0].fields.push({k:"toSite",t:"text",l:["Destination site code (e.g. V2S4)","गंतव्य साइट कोड (जैसे V2S4)"]})})();
function shiftSig(s){return [s.animal,s.kind,s.date,s.time,s.to,s.toSite,s.from].join("|")}
function shiftNotice(s){if(!s||!s.animal||!s.date||["Completed","Cancelled"].includes(s.status))return;const L=NTS();let n=L.find(x=>x.link&&x.link.shift===s.id);const sig=shiftSig(s);if(n&&n.sig===sig)return;
 const dest=(s.toSite||"").trim().toUpperCase();const sites=[SITE,...(ORG.site(dest)&&dest!==SITE?[dest]:[])];
 const tg=[...ORG.staff().filter(p=>p.site===SITE&&["sup","cur","bio","vet","mgr"].includes(p.role)),...ORG.staff().filter(p=>sites[1]&&p.site===sites[1]&&["sup","cur","mgr"].includes(p.role))].map(p=>p.uid);
 const body=`${s.animal}${s.species?" ("+s.species+")":""}\n${tv(s.kind||"")}: ${s.from||SITE} → ${s.to||""}${dest?" ["+dest+"]":""}\n${fmtDate(s.date)}${s.time?" · "+s.time:""}${s.how?"\n"+tv(s.how):""}${s.why?"\n"+s.why:""}`;
 if(n){n.title=t("shNotice",{a:s.animal});n.body=body;n.sig=sig;n.rev=(n.rev||1)+1;n.revAt=NOW();n.targets=[...new Set([...n.targets,...tg])].filter(u=>u!==n.byUid);n.remind={};n.esc={};ntSave(L);notify({type:"shifting_update",title:n.title,toUids:n.targets,priority:"Important",ref:n.id})}
 else{createNotice({kind:"shifting",title:t("shNotice",{a:s.animal}),body,pri:"Important",roleOpts:SH_OPTS,link:{shift:s.id,ants:"ANTS transfer to be raised in ANTS"},sig,targets:tg});toast(t("shAuto"))}}
let _shT=null;document.addEventListener("input",e=>{if(e.target.dataset&&e.target.dataset.fk==="shift"){clearTimeout(_shT);_shT=setTimeout(()=>{SHIFTS=store.get("kc-shifts",[]);SHIFTS.forEach(shiftNotice)},2500)}});
document.addEventListener("change",e=>{if(e.target.dataset&&e.target.dataset.fk==="shift"){clearTimeout(_shT);_shT=setTimeout(()=>{SHIFTS=store.get("kc-shifts",[]);SHIFTS.forEach(shiftNotice)},800)}});

/* ---------- quiet hours & priority ---------- */
const QUIET=()=>store.get("kc-quiet",{on:false,from:"22:00",to:"06:00"});
function inQuiet(){const q=QUIET();if(!q.on)return false;const d=new Date(NOW());const m=d.getHours()*60+d.getMinutes();const f=q.from.split(":"),tt=q.to.split(":");const a=+f[0]*60+ +f[1],b=+tt[0]*60+ +tt[1];return a<b?(m>=a&&m<b):(m>=a||m<b)}
function rQuiet(){const el=$("quietBox");if(!el)return;const q=QUIET();el.innerHTML=`<div class="ecard" style="margin-top:14px"><h3 class="subh" style="margin-top:0">🌙 ${t("quietH")}</h3><p class="counter">${t("quietP")}</p><label class="chk"><input type="checkbox" id="qOn" ${q.on?"checked":""}><span>${t("quietOn")}</span></label><div class="row"><div class="field"><span>${t("qFrom")}</span><input type="time" id="qFrom" value="${q.from}"></div><div class="field"><span>${t("qTo")}</span><input type="time" id="qTo" value="${q.to}"></div></div></div>`}
