[["alertPopup",()=>false],["afmPopup",()=>store.get("kc-issues",[]).some(x=>x.st==="new"&&x.p==="P1")],["evPopup",()=>false],["agencyPopup",()=>false],["afmDonePopup",()=>false],["pvPopups",()=>false]].forEach(([fn,crit])=>{try{const orig=window[fn]||eval(fn);const w=function(...a){if(inQuiet()&&!crit())return;return orig.apply(this,a)};eval(fn+"=w")}catch(e){}});
