function digestData(site,date){const A=Object.values(storeAt.get(site,"kc-alerts",{})).filter(a=>a.date===date);const sum=ty=>A.filter(a=>a.type===ty).reduce((s,a)=>s+(+a.count||1),0);
 const IS=storeAt.get(site,"kc-issues",[]);const opened=IS.filter(x=>x.date===date).length;const closed=IS.filter(x=>x.st==="closed"&&new Date((x.hist||[]).filter(h=>h.st==="closed").map(h=>h.at).pop()||0).toISOString().slice(0,10)===date).length;
 const overdue=IS.filter(x=>x.st!=="closed"&&typeof slaState==="function"&&slaState(x).breach).length;const openN=IS.filter(x=>x.st!=="closed").length;
 const INC=storeAt.get(site,"kc-incidents",[]).filter(s=>(s.date||"")===date);const att=storeAt.get(site,"kc-att",{})[date]||{};const staffN=ORG.staff().filter(p=>p.site===site&&["keeper","sup"].includes(p.role)).length;
 const present=Object.values(att).filter(r=>["Present","Late","Half day","On duty elsewhere"].includes(r.st)).length;
 const N=NTS().filter(n=>!n.closed&&(n.sites||[n.site]).includes(site));const pendR=N.reduce((s,n)=>s+(n.targets||[]).filter(u=>{const p=ORG.user(u);return p&&p.site===site&&!(n.resp&&n.resp[u])}).length,0);
 const ver=storeAt.get(site,"kc-verify",[]).filter(v=>v.date===date);
 return {births:sum("Birth"),deaths:sum("Mortality"),alerts:A.length,opened,closed,overdue,openN,incidents:INC,present,staffN,marked:Object.keys(att).length,pendR,verified:ver.filter(v=>v.status==="recorded").length,awaiting:ver.filter(v=>v.status==="pending").length}}
function digestText(site,date){const d=digestData(site,date);return [`*${t("dgTitle")}*`,`${site} · ${fmtDate(date)}`,"",`*${t("dgAnimals")}*`,`${t("births")}: ${d.births} · ${t("deaths")}: ${d.deaths} · ${t("mxAl")}: ${d.alerts}`,
 `*${t("dgMaint")}*`,`${d.opened} ${t("dgOpened")} · ${d.closed} ${t("dgClosedN")} · ${d.openN} ${t("fOpen").toLowerCase()} · ${d.overdue} ${t("dgOverdue")}`,
 `*${t("dgPeople")}*`,`${d.present}/${d.staffN} ${t("dgPresent")}`,`*${t("dgSafety")}*`,d.incidents.length?d.incidents.map(s=>`- ${tv(s.type||"")}: ${s.animal||""} (${tv(s.out||"")})`).join("\n"):t("dgNoInc"),
 `*${t("dgNotices")}*`,`${d.pendR} ${t("dgPendingR")}`].join("\n")}
