function vfSync(){const A=Object.values(store.get("kc-alerts",{})).filter(a=>["Birth","Mortality"].includes(a.type));const L=VFL();let ch=false;const ids=new Set(A.map(a=>a.id));
 A.forEach(a=>{if(!L.some(v=>v.id===a.id)){const rep=a.own&&ORG.user(a.own)||null;L.unshift({id:a.id,type:a.type,species:a.animal||"",cage:a.cage||"",count:+a.count||1,details:a.details||"",from:a.from,repUid:rep?rep.uid:(a.from==="sup"&&ME&&ME.role==="sup"?ME.uid:""),repName:rep?rep.name:(ME&&ME.role===a.from?ME.name:""),date:a.date,at:a.at||NOW(),status:"pending"});ch=true;
   notify({type:"verify_needed",title:(a.type==="Birth"?"Birth to verify: ":"Death to verify: ")+(a.animal||""),toRoles:a.type==="Birth"?["acur","cur","vet"]:["vet"],priority:a.type==="Mortality"?"Critical":"Important",ref:a.id})}
  else{const v=L.find(v=>v.id===a.id);if(v.status==="pending"&&(v.species!==(a.animal||"")||v.count!==(+a.count||1)||v.cage!==(a.cage||""))){v.species=a.animal||"";v.count=+a.count||1;v.cage=a.cage||"";ch=true}}});
 for(let i=L.length-1;i>=0;i--)if(L[i].status==="pending"&&L[i].date===TODAY&&!ids.has(L[i].id)){L.splice(i,1);ch=true}
 if(ch){vfSave(L);if(VIEW==="verify")RENDER.verify()}return L}
