/* ===================== MAINTENANCE P1–P4 ===================== */
const PLEV=["P1","P2","P3","P4"];
const SLA={P1:{resp:30*60e3,fix:4*3600e3},P2:{resp:4*3600e3,fix:24*3600e3},P3:{resp:24*3600e3,fix:5*864e5},P4:{resp:3*864e5,fix:null}};
const prOf=x=>x.p||(x.pri==="Urgent"?"P2":"P3");
const fmtDur=ms=>{const a=Math.abs(ms),m=Math.round(a/60000);return m<60?m+" min":m<1440?Math.round(m/60)+" h":Math.round(m/1440)+" d"};
const firstAt=(x,sts)=>{const h=(x.hist||[]).find(e=>sts.includes(e.st));return h?h.at:null};
function slaState(x){const p=prOf(x),S0=SLA[p],c=x.times[0],now=NOW();const respAt=firstAt(x,["seen","assigned","accepted"]);const fixAt=firstAt(x,["done","closed"]);
 const respDue=c+S0.resp;const fixDue=S0.fix?c+S0.fix:(x.due?new Date(x.due+"T17:00:00").getTime():c+30*864e5);
 const respOk=respAt?respAt<=respDue:(now<=respDue?null:false);const fixOk=fixAt?fixAt<=fixDue:(now<=fixDue?null:false);
 const open=x.st!=="closed";const breach=open&&(respOk===false&&!respAt||fixOk===false&&!fixAt);
 return {p,respDue,fixDue,respAt,fixAt,respOk,fixOk,breach,open,soon:open&&!fixAt&&fixDue-now<(fixDue-c)*0.25&&fixDue>now}}
/* complaint form: P1–P4 instead of Normal/Urgent */
