const _newIssue14=newIssue;newIssue=function(o){const t0=Date.now();const r=_newIssue14(o);const is=store.get("kc-issues",[]);const x=is[0];if(x&&x.times[0]>=t0-50){x.p=o.p||(o.pri==="Urgent"?"P2":"P3");if(o.due)x.due=o.due;if(o.tag)x.tag=o.tag;store.set("kc-issues",is);issues=is}return r};
/* show priority + time targets on every ticket card */
const _tkInfo14=tkInfo;tkInfo=function(x){const s=slaState(x);const tm=ts=>new Date(ts).toLocaleString(loc(),{day:"numeric",month:"short",hour:"2-digit",minute:"2-digit"});
 const part=(ok,at,due,lab)=>ok===true?`<span class="sla ok">✓ ${t(lab,{t:tm(due)})}</span>`:ok===false?`<span class="sla bad">⚠ ${t(lab,{t:tm(due)})} · ${at?t("slaLate"):t("slaOver",{d:fmtDur(NOW()-due)})}</span>`:`<span class="sla">${t(lab,{t:tm(due)})} · ${t("slaLeft",{d:fmtDur(due-NOW())})}</span>`;
 const esc0=(x.esc||[]).slice(-1)[0];
 const wc=x.wc||workCode(x.cat);return `<div class="slarow"><span class="pchip ${s.p}">${s.p}</span><span class="wchip" title="${esc(L2(WORK_NAME[wc]||WORK_NAME.O))}">${wc} · ${esc(L2(WORK_NAME[wc]||WORK_NAME.O))}</span>${x.tag?`<span class="tag age">${t("pmTag")}</span>`:""}${part(s.respOk,s.respAt,s.respDue,"slaResp")}${part(s.fixOk,s.fixAt,s.fixDue,"slaFix")}</div>${esc0?`<p class="warn" style="margin:4px 0">⬆ ${t("escTo",{r:esc(esc0.toName||L2(ROLE_LABEL[esc0.level]||["",""])),why:t(esc0.why)})}</p>`:""}`+_tkInfo14(x)};
/* escalation: AFM → Manager → Cluster Head */
function slaTick(){const is=store.get("kc-issues",[]);let ch=false;is.forEach(x=>{if(x.st==="closed"||!x.times)return;const s=slaState(x);x.esc=x.esc||[];const has=l=>x.esc.some(e=>e.level===l);
 const mgr=ORG.staff().find(p=>p.role==="mgr"&&p.site===SITE),chh=ORG.staff().find(p=>p.role==="ch"&&p.cluster===ORG.clusterOf(SITE));
 if((s.respOk===false&&!s.respAt||s.fixOk===false&&!s.fixAt)&&!has("mgr")&&mgr){x.esc.push({level:"mgr",toName:mgr.name,toUid:mgr.uid,at:NOW(),why:s.respOk===false&&!s.respAt?"escResp":"escFix"});ch=true;notify({type:"ticket_escalation",title:`Escalated ${x.id} (${s.p})`,body:x.prob,toUids:[mgr.uid],priority:s.p==="P1"?"Critical":"Important",ref:x.id})}
 const sev=s.fixOk===false&&!s.fixAt&&(NOW()-s.fixDue>(SLA[s.p].fix||864e5));
 if((sev||(s.p==="P1"&&s.fixOk===false&&!s.fixAt))&&!has("ch")&&chh){x.esc.push({level:"ch",toName:chh.name,toUid:chh.uid,at:NOW(),why:"escFix"});ch=true;notify({type:"ticket_escalation",title:`Escalated to Cluster Head ${x.id}`,body:x.prob,toUids:[chh.uid],priority:"Critical",ref:x.id})}});
 if(ch){store.set("kc-issues",is);issues=is;if(VIEW==="afm")rAfm();if(VIEW==="maint")RENDER.maint()}}
/* preventive jobs */
const PMJ=()=>store.get("kc-pmjobs",[]);const addPer=(d,n,u)=>{const x=new Date(d+"T12:00:00");if(u==="week")x.setDate(x.getDate()+7*n);else if(u==="month")x.setMonth(x.getMonth()+n);else x.setDate(x.getDate()+n);return x.toISOString().slice(0,10)};
function pmTick(){const L=PMJ();let n=0;const today=new Date(NOW()).toISOString().slice(0,10);L.forEach(j=>{let guard=0;while(j.active!==false&&j.next<=today&&guard++<6){const x=newIssue({cat:j.cat,prob:t("pmTag")+": "+j.title,loc:j.loc,pri:"Normal",from:ROLE||"afm",p:"P4",due:addDays(j.next,3),tag:"pm"});j.last=x?x.id:"";j.next=addPer(j.next,+j.n||1,j.unit);n++}});if(n){store.set("kc-pmjobs",L);toast(t("pmCreated",{n}))}}
setInterval(()=>{if(!typingNow()&&ME&&!["exec","sadmin","ch","siteadmin","agency"].includes(ROLE)){slaTick();if(["afm","mgr"].includes(ROLE))pmTick()}},60000);
setTimeout(()=>{if(ME&&!["exec","sadmin","ch","siteadmin","agency"].includes(ROLE)){slaTick();if(["afm","mgr"].includes(ROLE))pmTick()}},1200);
/* AFM list: most urgent first */
const _rAfm14=rAfm;rAfm=function(){const is=store.get("kc-issues",[]);const key=x=>(x.st==="closed"?9:0)+PLEV.indexOf(prOf(x))+(slaState(x).breach?-5:0);is.sort((a,b)=>key(a)-key(b)||b.times[0]-a.times[0]);store.set("kc-issues",is);issues=is;_rAfm14()};

