function agencyPerf(list){const A=store.get("kc-agencies",[]);return A.map(a=>{const J=list.filter(x=>x.agency===a.id);const acc=J.map(x=>{const as=firstAt(x,["assigned"]),ac=firstAt(x,["accepted"]);return as&&ac?ac-as:null}).filter(v=>v!=null);
 const fix=J.map(x=>{const ac=firstAt(x,["accepted"]),dn=firstAt(x,["done"]);return ac&&dn?dn-ac:null}).filter(v=>v!=null);const cl=J.filter(x=>x.st==="closed");const ont=cl.filter(x=>slaState(x).fixOk===true).length;
 const reo=J.filter(x=>(x.hist||[]).some((h,i,arr)=>h.st!=="done"&&i>0&&arr[i-1].st==="done")).length;
 return {a,jobs:J.length,open:J.filter(x=>x.st!=="closed").length,resp:acc.length?acc.reduce((s,v)=>s+v,0)/acc.length:null,fix:fix.length?fix.reduce((s,v)=>s+v,0)/fix.length:null,ontime:cl.length?Math.round(ont/cl.length*100):null,reopen:J.length?Math.round(reo/J.length*100):0}}).filter(r=>r.jobs)}
