const ageY=dob=>Math.max(0,Math.floor((NOW()-new Date(dob+"T12:00:00").getTime())/31557600000));

/* ---------- small SVG line chart ---------- */
function lineChart(pts,{w=340,h=120,yl=""}={}){if(pts.length<2)return "";const xs=pts.map(p=>new Date(p.x+"T12:00:00").getTime()),ys=pts.map(p=>p.y);const x0=Math.min(...xs),x1=Math.max(...xs);let y0=Math.min(...ys),y1=Math.max(...ys);if(y0===y1){y0-=1;y1+=1}const pad=(y1-y0)*.15;y0-=pad;y1+=pad;
 const X=v=>30+(v-x0)/(x1-x0||1)*(w-40),Y=v=>h-20-(v-y0)/(y1-y0)*(h-30);const d=pts.map((p,i)=>(i?"L":"M")+X(xs[i]).toFixed(1)+" "+Y(p.y).toFixed(1)).join(" ");
 return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(yl)}"><line x1="30" y1="${h-20}" x2="${w-10}" y2="${h-20}" stroke="var(--line)"/><text x="2" y="${Y(y1-pad)+4}">${(y1-pad).toFixed(y1>100?0:1)}</text><text x="2" y="${Y(y0+pad)+4}">${(y0+pad).toFixed(y1>100?0:1)}</text>
 <path d="${d}" fill="none" stroke="var(--leaf)" stroke-width="2.5" stroke-linejoin="round"/>${pts.map((p,i)=>`<circle cx="${X(xs[i]).toFixed(1)}" cy="${Y(p.y).toFixed(1)}" r="3" fill="var(--leaf)"><title>${p.x}: ${p.y}</title></circle>`).join("")}
 <text x="30" y="${h-4}">${shortD(pts[0].x)}</text><text x="${w-10}" y="${h-4}" text-anchor="end">${shortD(pts[pts.length-1].x)}</text></svg>`}

/* ---------- Animal timeline ---------- */
let tlQ="",tlSel=null;
function drsMentions(a){const out=[];const has=s=>s&&(String(s).includes(a.name)||String(s).includes(a.id));
 Object.values(store.get("kc-alerts",{})).forEach(x=>{if(has(x.animal)||(x.animal===a.species&&x.cage===a.enclosure))out.push({date:x.date,text:`${tv(x.type)}${x.details?": "+x.details:""}`,src:"drs"})});
 store.get("kc-rx",[]).forEach(r=>{if(has(r.animal))out.push({date:r.start,text:`💊 ${r.med} ${r.dose} (${r.dx||""})`,src:"drs"})});
 store.get("kc-pobs",[]).forEach(o=>{if(has(o.animal))out.push({date:o.date,text:`👁 ${tv(o.kind||"Health observation")}: ${(o.tags||[]).map(tv).join(", ")}${o.note?" – "+o.note:""}`,src:"drs"})});
 store.get("kc-incidents",[]).forEach(s=>{if(has(s.animal))out.push({date:s.date,text:`⚠ ${tv(s.type||"")} – ${tv(s.out||"")}`,src:"drs"})});
 VFL().forEach(v=>{if(v.payload&&v.payload.animalId===a.id)out.push({date:v.date,text:`🕯 ${tv(v.type)} · ${v.antsRef}`,src:"drs"})});
 return out}
RENDER.timeline=()=>{const L=myAnimals();const q=tlQ.toLowerCase();const a=tlSel&&L.find(x=>x.id===tlSel);
 if(!a){const list=L.filter(x=>!q||(x.name+" "+x.id+" "+x.species+" "+x.enclosure).toLowerCase().includes(q));
  $("timelineBody").innerHTML=`${ME&&["keeper","sup"].includes(ME.role)&&ME.zone?`<p class="counter">🔒 ${t("tlZoneOnly",{z:ME.zone})}</p>`:""}<input type="text" class="search" id="tlQ" placeholder="${t("tlPick")}" value="${esc(tlQ)}">
  <div style="margin-top:10px">${list.slice(0,40).map(x=>`<button class="ccard" data-tl="${x.id}"><span><b>${esc(x.name)}</b> <small>${x.id}</small><br><small>${esc(x.species)} · ${x.enclosure} · ${tv(x.sex)}</small></span><span class="go">›</span></button>`).join("")||`<p class="empty">${t("tlNone")}</p>`}${list.length>40?`<p class="counter">+${list.length-40}</p>`:""}</div>`;return}
 const H=ANTS.history(a.id);const ev=[...H.events.map(e=>({...e,src:"ants"})),...H.vacc.map(v=>({date:v.date,text:`💉 ${tv(v.type)} (${v.by})`,src:"ants"})),...H.weights.slice(-3).map(w=>({date:w.date,text:`⚖ ${w.kg} kg`,src:"ants"})),...drsMentions(a)].sort((x,y)=>y.date.localeCompare(x.date));
 $("timelineBody").innerHTML=`<button class="crumb" id="tlBack">${t("timelineH")}</button><div class="ecard"><h2 style="margin:0">${esc(a.name)}</h2><p class="counter" style="margin:4px 0 0">${a.id} · ${esc(a.species)} · ${tv(a.sex)} · ${t("tlAge",{y:ageY(a.dob)})} · ${a.enclosure} · ${a.zone} <span class="pill2 ants">${t("viaAnts")}</span></p></div>
 <h3 class="subh">${t("tlWeight")}</h3><div class="ecard">${lineChart(H.weights.map(w=>({x:w.date,y:w.kg})),{yl:t("tlWeight")})}</div>
 <h3 class="subh">${t("tlBcs")}</h3><div class="ecard">${lineChart(H.bcs.map(b=>({x:b.date,y:b.score})),{yl:t("tlBcs"),h:100})}</div>
 <h3 class="subh">📎 ${t("tlMedia")}</h3>${typeof mediaBox==="function"?mediaBox("animal:"+a.id):""}
 <h3 class="subh">${t("tlEvents")}</h3><div class="atl">${ev.map(e=>`<div class="ti ${e.src}"><small>${shortD(e.date)} · <span class="pill2 ${e.src==="ants"?"ants":""}">${e.src==="ants"?t("tlFromAnts"):t("tlFromDrs")}</span></small><br>${esc(e.text)}</div>`).join("")}</div>`};
document.addEventListener("input",e=>{if(e.target.id==="tlQ"){tlQ=e.target.value;const pos=e.target.selectionStart;RENDER.timeline();const s=$("tlQ");s.focus();s.setSelectionRange(pos,pos)}});
document.addEventListener("click",e=>{const b=e.target.closest("[data-tl]");if(b){tlSel=b.dataset.tl;RENDER.timeline();window.scrollTo(0,0)}if(e.target.id==="tlBack"){tlSel=null;RENDER.timeline()}});

/* ---------- vaccination / deworming reminders (schedules from ANTS) ---------- */
const VXD=()=>store.get("kc-vaccdone",{});
function vxDue(){const done=VXD();const lim=addDays(TODAY,7);return ANTS.schedules(SITE).filter(s=>!done[s.id]&&s.due<=lim).sort((a,b)=>a.due.localeCompare(b.due))}
function vxBox(){const L=vxDue();const canDo=["vet","pvet"].includes(ROLE);return `<div class="ecard vxbox"><h3 class="subh" style="margin-top:0">💉 ${t("vxH")} (${L.length})</h3><p class="counter">${t("vxP")}</p>${L.slice(0,12).map(s=>`<div class="act"><span><b>${esc(s.animal)}</b> · ${esc(tv(s.type))}<br><small>${esc(s.species)} · ${s.enclosure} · <span class="${s.due<TODAY?"over":""}">${s.due<TODAY?t("vxOver")+" ("+shortD(s.due)+")":t("vxDue",{d:shortD(s.due)})}</span></small></span>${canDo?`<button class="x" data-vxdone="${s.id}">${t("vxDone")}</button>`:""}</div>`).join("")||`<p class="empty">${t("nothing")}</p>`}${L.length>12?`<p class="counter">+${L.length-12}</p>`:""}</div>`}
document.addEventListener("click",e=>{const id=e.target.dataset&&e.target.dataset.vxdone;if(!id)return;const s=ANTS.schedules(SITE).find(x=>x.id===id);const r=ANTS.record("vaccination-done",{site:SITE,scheduleId:id,animalId:s.animalId,type:s.type,date:TODAY,by:ME.uid});const d=VXD();d[id]={ref:r.ref,by:ME.uid,at:NOW()};store.set("kc-vaccdone",d);toast(t("vxRecorded",{r:r.ref}));if(VIEW==="cdash")rCDash();if(VIEW==="pvtoday")rPvToday()});
const _rCDash15=rCDash;rCDash=function(){_rCDash15();if(ROLE==="vet")$("cdashBody").insertAdjacentHTML("afterbegin",vxBox())};
const _rPvToday15=rPvToday;rPvToday=function(){_rPvToday15();const el=$("pvBody");if(el)el.insertAdjacentHTML("afterbegin",vxBox())};
(function vxNotify(){if(!ME||!["vet","pvet"].includes(ME.role))return;const k="kc-vxnote-"+TODAY;if(store.get(k,false))return;const n=vxDue().filter(s=>s.due<=TODAY).length;if(n){notify({type:"vaccination_due",title:`${n} vaccinations / dewormings due or overdue`,toRoles:["vet","pvet"],priority:"Important"});store.set(k,true)}})();

/* ---------- Investigations ---------- */
const INV=()=>store.get("kc-inv",[]);const invSave=L=>store.set("kc-inv",L);
const CAUSES=["Human error","Equipment / structure","Procedure gap","Animal behaviour","Weather","Other"];
let invEdit=null;
const canInv=()=>["cur","mgr","acur"].includes(ROLE),isCH=()=>ROLE==="ch";
function invStatus(i){return !i?"iNone":i.status==="closed"?"iClosed":i.status==="submitted"?"iSub":i.status==="more"?"iMore":"iDraft"}
RENDER.inv=()=>{const sites=isCH()||ROLE==="exec"?ORG.scopeSites(ME):[SITE];const rows=sites.flatMap(sc=>storeAt.get(sc,"kc-incidents",[]).map(s=>({s,sc,i:storeAt.get(sc,"kc-inv",[]).find(v=>v.incId===s.id)})));
 if(invEdit){const v=invEdit;$("invBody").innerHTML=`<button class="crumb" id="invBack">${t("invH")}</button><div class="ecard"><b>${esc(tv(v.incType||""))}: ${esc(v.incAnimal||"")}</b><p class="counter">${v.site} · ${shortD(v.incDate||TODAY)}</p></div>
  <div class="form"><div class="field"><span class="lbl">${t("invCauseCat")}</span><div class="seg">${CAUSES.map(c=>`<label><input type="radio" name="invc" value="${c}" data-iv="cat" ${v.cat===c?"checked":""}><span>${tv(c)}</span></label>`).join("")}</div></div>
  <div class="field"><span>${t("invCause")}</span><textarea data-iv="cause">${esc(v.cause||"")}</textarea></div>
  <span class="lbl">${t("invActions")}</span>${(v.actions||[]).map((a,k)=>`<div class="box"><div class="field"><span>${t("invAct")} ${k+1}</span><input type="text" data-iva="${k}" data-f="text" value="${esc(a.text)}"></div><div class="row"><div class="field"><span>${t("invOwner")}</span><select class="full" data-iva="${k}" data-f="ownerUid">${ORG.staff().filter(p=>p.site===v.site).map(p=>`<option value="${p.uid}" ${p.uid===a.ownerUid?"selected":""}>${esc(p.name)} · ${esc(L2(ROLE_LABEL[p.role]||["",""]))}</option>`).join("")}</select></div><div class="field"><span>${t("invDue")}</span><input type="date" data-iva="${k}" data-f="due" value="${a.due||""}"></div></div><label class="chk"><input type="checkbox" data-iva="${k}" data-f="done" ${a.done?"checked":""}><span>${t("actDone")}</span></label></div>`).join("")}
  <button class="add" id="invAddAct">${t("invAddAct")}</button><div class="field" style="margin-top:10px"><span>${t("invPrev")}</span><textarea data-iv="prev">${esc(v.prev||"")}</textarea></div>
  ${v.chNote?`<p class="warn">${esc(v.chNote)}</p>`:""}
  ${isCH()&&v.status==="submitted"?`<div class="field"><span>${t("notes")}</span><input type="text" id="chNote"></div><div class="btns"><button class="btn" id="invAccept">${t("invAccept")}</button><button class="btn ghost" id="invMoreB">${t("invMore")}</button></div>`
   :canInv()&&v.status!=="closed"?`<div class="btns"><button class="btn gold" id="invSubmit">${t("invSubmit")}</button><button class="btn ghost" id="invSaveB">${t("invSave")}</button></div>`:""}</div>`;return}
 $("invBody").innerHTML=rows.length?rows.sort((a,b)=>(b.s.date||"").localeCompare(a.s.date||"")).map(({s,sc,i})=>{const od=i&&(i.actions||[]).filter(a=>!a.done&&a.due&&a.due<TODAY).length;return `<div class="issue ${i&&i.status==="closed"?"fixed":"urgent"}"><div class="top"><strong>${esc(tv(s.type||""))}: ${esc(s.animal||"?")}</strong><small>${sc} · ${s.date?shortD(s.date):""}</small></div><small>${esc(tv(s.out||""))} · <b>${t(invStatus(i))}</b>${i?` · ${(i.actions||[]).filter(a=>a.done).length}/${(i.actions||[]).length} ${t("invActions").toLowerCase()}`:""}${od?` · <span class="over">${od} ${t("actOverdue").toLowerCase()}</span>`:""}</small>
  <div class="acts" style="margin-top:6px">${(canInv()&&sc===SITE)||isCH()?`<button class="btn ${i?"ghost":""}" data-invopen="${sc}|${s.id}">${i?t("edit"):t("invStart")}</button>`:""}</div></div>`}).join(""):`<p class="empty">${t("invNoInc")}</p>`};
document.addEventListener("input",e=>{if(!invEdit)return;const d=e.target.dataset||{};if(d.iv){if(e.target.type==="radio"&&!e.target.checked)return;invEdit[d.iv]=e.target.value}if(d.iva!==undefined){const a=invEdit.actions[+d.iva];a[d.f]=e.target.type==="checkbox"?e.target.checked:e.target.value}});
document.addEventListener("change",e=>{if(invEdit&&e.target.dataset&&e.target.dataset.iva!==undefined&&e.target.type==="checkbox"){invEdit.actions[+e.target.dataset.iva].done=e.target.checked}});
function invPut(v){const L=storeAt.get(v.site,"kc-inv",[]);const k=L.findIndex(x=>x.id===v.id);if(k>=0)L[k]=v;else L.unshift(v);storeAt.set(v.site,"kc-inv",L)}
document.addEventListener("click",e=>{const id=e.target.id,b=e.target.closest("[data-invopen]");
 if(b){const [sc,iid]=b.dataset.invopen.split("|");const s=storeAt.get(sc,"kc-incidents",[]).find(x=>x.id===iid);invEdit=storeAt.get(sc,"kc-inv",[]).find(v=>v.incId===iid)||{id:"INV"+Date.now(),incId:iid,site:sc,incType:s.type,incAnimal:s.animal,incDate:s.date,cat:"",cause:"",actions:[],prev:"",status:"draft",byUid:ME.uid,byName:ME.name};invEdit=JSON.parse(JSON.stringify(invEdit));RENDER.inv();window.scrollTo(0,0)}
 if(id==="invBack"){invEdit=null;RENDER.inv()}
 if(id==="invAddAct"){invEdit.actions.push({text:"",ownerUid:ME.uid,due:addDays(TODAY,7),done:false});RENDER.inv()}
 if(id==="invSaveB"){invPut(invEdit);toast(t("invSave")+" ✓")}
 if(id==="invSubmit"){if(!invEdit.cause.trim()||!invEdit.actions.length){toast(t("invCause"));return}invEdit.status="submitted";invEdit.subAt=NOW();invPut(invEdit);const chh=ORG.staff().find(p=>p.role==="ch"&&p.cluster===ORG.clusterOf(invEdit.site));
  notify({type:"investigation_submitted",title:`Investigation: ${tv(invEdit.incType)} at ${invEdit.site}`,body:invEdit.cause.slice(0,120),toUids:chh?[chh.uid]:[],toRoles:["ch"],priority:"Important",ref:invEdit.id});
  invEdit.actions.forEach(a=>notify({type:"action_assigned",title:"Corrective action: "+a.text,body:"Due "+a.due,toUids:[a.ownerUid],ref:invEdit.id}));toast(t("invSubmit")+" ✓");invEdit=null;RENDER.inv()}
 if(id==="invAccept"){invEdit.status="closed";invEdit.closedBy=ME.name;invEdit.chNote=$("chNote").value;invPut(invEdit);invEdit=null;RENDER.inv()}
 if(id==="invMoreB"){const n=$("chNote").value.trim();if(!n){$("chNote").focus();return}invEdit.status="more";invEdit.chNote=ME.name+": "+n;invPut(invEdit);notify({type:"investigation_more",title:"Cluster Head asks for more: "+n,toUids:[invEdit.byUid],ref:invEdit.id});invEdit=null;RENDER.inv()}});

/* ---------- Night SOS and check-ins ---------- */
const SOSL=()=>store.get("kc-sos",[]);const sosSave=L=>store.set("kc-sos",L);
const CHK=()=>store.get("kc-checkin",{});const CHK_MIN=60;
function nightPanel(){if(!ME||ME.role!=="keeper")return "";const c=CHK()[ME.uid];const on=c&&c.active;
 return `<div class="ecard nightpanel"><button class="sosbtn" id="sosBtn">🆘 ${t("sos")}</button>${on?`<div class="chkin"><span>${t("nwLast",{t:hm(c.last),n:new Date(c.last+CHK_MIN*60000).toLocaleTimeString(loc(),{hour:"2-digit",minute:"2-digit"})})}</span><button class="btn" id="nwOk" style="width:auto">${t("nwOk")}</button></div><button class="x" id="nwStop">${t("nwStop")}</button>`:`<button class="btn ghost" id="nwStart">${t("nwStart",{m:CHK_MIN})}</button>`}</div>`}
const _rDuty15=rDuty;rDuty=function(){_rDuty15();const old=$("nightPanelBox");if(old)old.remove();if(DUTY==="night"&&$("duty-night"))$("duty-night").insertAdjacentHTML("afterbegin",`<div id="nightPanelBox">${nightPanel()}</div>`)};
function sosRaise(kind,who,note){const L=SOSL();const x={id:"SOS"+Date.now(),kind,uid:who.uid,name:who.name,zone:who.zone||"",at:NOW(),status:"open",note:note||""};L.unshift(x);sosSave(L);
 const tg=ORG.staff().filter(p=>p.site===SITE&&(p.role==="mgr"||p.role==="vet"||(p.role==="sup"&&(!who.zone||p.zone===who.zone)))).map(p=>p.uid);
 notify({type:"sos",title:(kind==="sos"?"🚨 SOS: ":"⚠ Missed check-in: ")+who.name+" ("+SITE+" "+(who.zone||"")+")",toUids:tg,priority:"Critical",ref:x.id});return x}
document.addEventListener("click",e=>{const id=e.target.id;
 if(id==="sosBtn"){if(!confirm(t("sosConfirm")))return;sosRaise("sos",ME);toast(t("sosSent"))}
 if(id==="nwStart"||id==="nwOk"){const C=CHK();C[ME.uid]={active:true,last:NOW(),name:ME.name,zone:ME.zone,missed:0};store.set("kc-checkin",C);rDuty()}
 if(id==="nwStop"){const C=CHK();if(C[ME.uid])C[ME.uid].active=false;store.set("kc-checkin",C);rDuty()}
 const b=e.target.closest("[data-sosact]");if(b){const L=SOSL();const x=L.find(s=>s.id===b.dataset.sosid);x.status=b.dataset.sosact;x.by=ME.name;x.byAt=NOW();sosSave(L);if($("repSheet").querySelector(".sospop"))$("repSheet").hidden=true;if(VIEW==="safety")RENDER.safety()}});
function sosTick(){if(!ME||!["sup","mgr","vet"].includes(ME.role))return;const C=CHK();let ch=false;Object.entries(C).forEach(([uid,c])=>{if(c.active&&NOW()-c.last>(CHK_MIN+15)*60000&&(!c.missedAt||c.missedAt<c.last)){c.missedAt=NOW();ch=true;sosRaise("missed",{uid,name:c.name,zone:c.zone})}});if(ch)store.set("kc-checkin",C);
 const open=SOSL().filter(s=>s.status==="open");const seen=store.get("kc-sos-seen",[]);const fresh=open.filter(s=>!seen.includes(s.id));
 if(fresh.length&&$("repSheet").hidden){store.set("kc-sos-seen",[...seen,...fresh.map(s=>s.id)]);try{navigator.vibrate&&navigator.vibrate([400,150,400,150,400])}catch(e){}
  $("repSheet").innerHTML=`<div class="sheet big sospop"><div class="top"><h2>🚨 SOS</h2><button class="x" id="rsClose">${t("close")}</button></div>${fresh.map(s=>`<div class="issue urgent" style="margin-top:10px"><div class="top"><strong>${s.kind==="sos"?t("sosPop",{n:esc(s.name)}):t("sosMissed",{n:esc(s.name)})}</strong><small>${hm(s.at)}</small></div><small>${SITE} · ${esc(s.zone)}</small><div class="acts" style="margin-top:8px"><button class="btn" data-sosact="responding" data-sosid="${s.id}">${t("sosResp")}</button></div></div>`).join("")}</div>`;$("repSheet").hidden=false}}
setInterval(()=>{if(!typingNow())sosTick()},20000);setTimeout(sosTick,1500);

/* ---------- Safety screen: SOS log + drills ---------- */
const DRL=()=>store.get("kc-drills",[]);let drForm=null;
RENDER.safety=()=>{const S0=SOSL().slice(0,15);$("safetyBody").innerHTML=`${ME&&ME.role==="keeper"?nightPanel():""}<h2 class="dh">🚨 ${t("sosH")}</h2>${S0.map(s=>`<div class="issue ${s.status==="resolved"?"fixed":"urgent"}"><div class="top"><strong>${s.kind==="sos"?"SOS":t("sosMissed",{n:""})}: ${esc(s.name)}</strong><small>${hm(s.at)}</small></div><small>${esc(s.zone)} · ${esc(s.status)}${s.by?" · "+esc(s.by):""}</small>${s.status!=="resolved"&&["sup","mgr","vet"].includes(ROLE)?`<div class="acts" style="margin-top:6px">${s.status==="open"?`<button class="btn" data-sosact="responding" data-sosid="${s.id}">${t("sosResp")}</button>`:""}<button class="btn ghost" data-sosact="resolved" data-sosid="${s.id}">${t("sosClose")}</button></div>`:""}</div>`).join("")||`<p class="empty">${t("nothing")}</p>`}
 <h2 class="dh">🧯 ${t("drillH")}</h2>${["sup","mgr","cur","afm"].includes(ROLE)?(drForm?drFormHTML():`<button class="btn" id="drNew">${t("drillNew")}</button>`):""}
 ${DRL().map(d=>`<div class="issue ${d.rate==="Good"?"fixed":""}"><div class="top"><strong>${esc(tv(d.type))}</strong><small>${shortD(d.date)} ${d.time||""}</small></div><small>${d.dur||"-"} min · ${(d.who||[]).length} · ${esc(tv(d.rate||""))} · ${esc(d.byName||"")}</small>${d.obs?`<p style="margin:6px 0 0">${esc(d.obs)}</p>`:""}${d.act?`<p class="warn" style="margin:6px 0 0">${esc(d.act)}</p>`:""}</div>`).join("")}`};
function drFormHTML(){const f=drForm;const ppl=ORG.staff().filter(p=>p.site===SITE&&!["exec","ch","sadmin","siteadmin","agency"].includes(p.role));return `<div class="form"><div class="field"><span class="lbl">${t("drType")}</span><div class="seg">${["Fire","Animal escape","First aid","Evacuation","Power failure","Other"].map(x=>`<label><input type="radio" name="drt" data-dr="type" value="${x}" ${f.type===x?"checked":""}><span>${tv(x)}</span></label>`).join("")}</div></div>
 <div class="row3"><div class="field"><span>${t("rDate")}</span><input type="date" data-dr="date" value="${f.date}"></div><div class="field"><span>${t("time")}</span><input type="time" data-dr="time" value="${f.time}"></div><div class="field"><span>${t("drDur")}</span><input type="number" data-dr="dur" value="${f.dur}"></div></div>
 <div class="field"><span class="lbl">${t("drWho")}</span><div class="seg">${ppl.map(p=>`<label><input type="checkbox" data-dr="who" value="${p.uid}" ${f.who.includes(p.uid)?"checked":""}><span>${esc(p.name.split(" ")[0])}</span></label>`).join("")}</div></div>
 <div class="field"><span>${t("drObs")}</span><textarea data-dr="obs">${esc(f.obs)}</textarea></div><div class="field"><span>${t("drAct")}</span><textarea data-dr="act">${esc(f.act)}</textarea></div>
 <div class="field"><span class="lbl">${t("drRate")}</span><div class="seg">${["Good","Needs improvement"].map(x=>`<label><input type="radio" name="drr" data-dr="rate" value="${x}" ${f.rate===x?"checked":""}><span>${tv(x)}</span></label>`).join("")}</div></div>
 ${typeof mediaBox==="function"?mediaBox("drdraft:"+f.key):""}<div class="btns"><button class="btn" id="drSave">${t("drSave")}</button><button class="btn ghost" id="drCancel">${t("cancel")}</button></div></div>`}
document.addEventListener("input",e=>{const k=e.target.dataset&&e.target.dataset.dr;if(!k||!drForm)return;if(k==="who")drForm.who=[...document.querySelectorAll('[data-dr="who"]:checked')].map(x=>x.value);else if(e.target.type==="radio"){if(e.target.checked)drForm[k]=e.target.value}else drForm[k]=e.target.value});
document.addEventListener("click",e=>{const id=e.target.id;if(id==="drNew"){drForm={type:"Fire",date:TODAY,time:nowHM(),dur:20,who:[],obs:"",act:"",rate:"Good",key:"D"+Date.now()};RENDER.safety()}if(id==="drCancel"){drForm=null;RENDER.safety()}
 if(id==="drSave"){const L=DRL();const d={...drForm,id:"DR"+Date.now(),byUid:ME.uid,byName:ME.name};L.unshift(d);store.set("kc-drills",L);if(typeof moveMedia==="function")moveMedia("drdraft:"+drForm.key,"drill:"+d.id);drForm=null;RENDER.safety()}});

/* ---------- Roster and leave ---------- */
const SHIFT_CODES=["M","E","N","OFF",""];
let rosW=(()=>{const d=new Date(TODAY+"T12:00:00");d.setDate(d.getDate()-((d.getDay()+6)%7));return d.toISOString().slice(0,10)})();
const LVL=()=>store.get("kc-leave",[]);const lvSave=L=>store.set("kc-leave",L);
const rosterPeople=()=>ORG.staff().filter(p=>p.site===SITE&&["keeper","sup"].includes(p.role)&&(ROLE!=="sup"||!ME.zone||p.zone===ME.zone||p.uid===ME.uid));
const onLeave=(uid,d)=>LVL().find(l=>l.uid===uid&&l.status==="approved"&&l.from<=d&&l.to>=d);
const approverFor=p=>p.role==="keeper"?"sup":"mgr";
RENDER.roster=()=>{const R=store.get("kc-roster",{});const W=R[rosW]||{};const days=[...Array(7)].map((_,i)=>addDays(rosW,i));const ppl=rosterPeople();const canEdit=["sup","mgr"].includes(ROLE);
 const pend=LVL().filter(l=>l.status==="pending"&&(ROLE==="mgr"||(ROLE==="sup"&&l.role==="keeper"&&(!ME.zone||l.zone===ME.zone))));
 $("rosterBody").innerHTML=`<h2 class="dh">🗓 ${t("lvH")} (${pend.length})</h2>${pend.map(l=>`<div class="issue"><div class="top"><strong>${esc(l.name)}</strong><small>${shortD(l.from)} – ${shortD(l.to)}</small></div><small>${esc(tv(l.type))} · ${esc(L2(ROLE_LABEL[l.role]||["",""]))} · ${esc(l.zone||"")}</small>${l.reason?`<p style="margin:6px 0 0">${esc(l.reason)}</p>`:""}<div class="acts" style="margin-top:6px"><button class="btn" data-lv="approved" data-lvid="${l.id}">${t("lvApprove")}</button><button class="x" data-lv="rejected" data-lvid="${l.id}">${t("lvReject")}</button></div></div>`).join("")||`<p class="empty">${t("nothing")}</p>`}
 <h2 class="dh">${t("wk",{d:shortD(rosW)})}</h2><div class="acts"><button class="x" data-rw="-7">${t("prevW")}</button><button class="x" data-rw="7">${t("nextW")}</button></div>
 <div class="tblwrap"><table class="roster"><thead><tr><th></th>${days.map(d=>`<th>${new Date(d+"T12:00:00").toLocaleDateString(loc(),{weekday:"short"})}<br>${d.slice(8)}</th>`).join("")}</tr></thead><tbody>${ppl.map(p=>`<tr><td style="text-align:left"><b>${esc(p.name.split(" ")[0])}</b><br><small>${p.zone}</small></td>${days.map(d=>{const lv=onLeave(p.uid,d);const c=lv?"L":((W[p.uid]||{})[d]||"");return `<td class="sh-${c||"x"}">${canEdit&&!lv?`<button data-rc="${p.uid}|${d}" aria-label="${esc(p.name)} ${d}">${c||"·"}</button>`:(c||"·")}</td>`}).join("")}</tr>`).join("")}</tbody></table></div><p class="counter">M = Morning · E = Evening · N = Night · OFF · L = Leave</p>`};
RENDER.leave=()=>{const mine=LVL().filter(l=>l.uid===ME.uid);const R=store.get("kc-roster",{});const W=R[rosW]||{};const days=[...Array(7)].map((_,i)=>addDays(rosW,i));
 $("leaveBody").innerHTML=`<h2 class="dh">${t("myShifts")}</h2><div class="tblwrap"><table class="roster"><tr>${days.map(d=>{const c=onLeave(ME.uid,d)?"L":((W[ME.uid]||{})[d]||"·");return `<td class="sh-${c}"><small>${new Date(d+"T12:00:00").toLocaleDateString(loc(),{weekday:"short"})}</small><br><b>${c}</b></td>`}).join("")}</tr></table></div>
 <h2 class="dh">${t("lvNew")}</h2><div class="form"><div class="field"><span class="lbl">${t("lvType")}</span><div class="seg">${["Casual","Sick","Earned","Other"].map((x,i)=>`<label><input type="radio" name="lvt" value="${x}" ${i===0?"checked":""}><span>${tv(x)}</span></label>`).join("")}</div></div>
 <div class="row"><div class="field"><span>${t("lvFrom")}</span><input type="date" id="lvF" value="${addDays(TODAY,1)}"></div><div class="field"><span>${t("lvTo")}</span><input type="date" id="lvT" value="${addDays(TODAY,1)}"></div></div><div class="field"><span>${t("lvWhy")}</span><input type="text" id="lvR"></div><button class="btn" id="lvSend">${t("lvSend")}</button></div>
 <h2 class="dh">${t("lvH")}</h2>${mine.map(l=>`<div class="act"><span>${esc(tv(l.type))} · ${shortD(l.from)} – ${shortD(l.to)}</span><b class="${l.status==="approved"?"okw":""}">${t(l.status==="approved"?"lvOk":l.status==="rejected"?"lvNo":"lvPend")}</b></div>`).join("")||`<p class="empty">${t("nothing")}</p>`}`};
document.addEventListener("click",e=>{const id=e.target.id,b=e.target.closest("[data-rc],[data-rw],[data-lv]");
 if(id==="lvSend"){const f=$("lvF").value,tt=$("lvT").value;if(!f||!tt||tt<f){toast(t("lvTo"));return}const L=LVL();L.unshift({id:"LV"+Date.now(),uid:ME.uid,name:ME.name,role:ME.role,zone:ME.zone,from:f,to:tt,type:(document.querySelector("input[name=lvt]:checked")||{}).value,reason:$("lvR").value,status:"pending",at:NOW()});lvSave(L);
  notify({type:"leave_request",title:"Leave request: "+ME.name,body:f+" – "+tt,toRoles:[approverFor(ME)],priority:"Information"});toast(t("lvSend")+" ✓");RENDER.leave()}
 if(!b)return;const d=b.dataset;
 if(d.rc){const [uid,day]=d.rc.split("|");const R=store.get("kc-roster",{});R[rosW]=R[rosW]||{};R[rosW][uid]=R[rosW][uid]||{};const c=R[rosW][uid][day]||"";R[rosW][uid][day]=SHIFT_CODES[(SHIFT_CODES.indexOf(c)+1)%SHIFT_CODES.length];store.set("kc-roster",R);RENDER.roster()}
 if(d.rw){rosW=addDays(rosW,+d.rw);VIEW==="leave"?RENDER.leave():RENDER.roster()}
 if(d.lv){const L=LVL();const l=L.find(x=>x.id===d.lvid);l.status=d.lv;l.by=ME.name;l.byAt=NOW();lvSave(L);
  if(d.lv==="approved"){const A=store.get("kc-att",{});let dd=l.from;while(dd<=l.to){A[dd]=A[dd]||{};const st=l.type==="Sick"?"Sick leave":"Leave";A[dd][l.uid]={st,by:ROLE,tm:"",at:NOW()};dd=addDays(dd,1)}store.set("kc-att",A)}
  notify({type:"leave_result",title:"Leave "+d.lv+": "+shortD(l.from)+" – "+shortD(l.to),toUids:[l.uid]});RENDER.roster()}});

/* staff list for attendance comes from ANTS (Data Operator no longer keeps one) */
STAFF=ORG.staff().filter(p=>p.site===SITE&&!["exec","ch","sadmin","siteadmin","agency"].includes(p.role)).map(p=>({id:p.uid,name:p.name,ep:p.ep,post:p.antsRole,site:p.site,zone:p.zone,shift:""}));

/* =====================================================================
   ENGINE 16 — Photos, short videos and documents (always optional)
   • Photo: compressed to max 1600 px JPEG; can be marked up (pen, circle, arrow)
   • Video: up to 60 seconds   • Document: PDF or image
   • Linked to the record (ticket, event, incident, animal…) — visible only
     where that record is visible.
   • Files: this phone keeps them in IndexedDB. With a server, window.DRS_MEDIA_UPLOAD(blob,meta)
     -> Promise<url> stores them centrally (ANTS / company storage). If upload fails
     (no network) the item waits and retries automatically.
   ===================================================================== */
Object.assign(I,{mPhoto:["📷 Photo","📷 फ़ोटो"],mVideo:["🎥 Video","🎥 वीडियो"],mDoc:["📄 Document","📄 दस्तावेज़"],mOptional:["Optional – add photos, a short video or documents","वैकल्पिक – फ़ोटो, छोटा वीडियो या दस्तावेज़"],
 mTooLong:["Video must be 60 seconds or less","वीडियो 60 सेकंड या कम हो"],mTooBig:["File is too large","फ़ाइल बहुत बड़ी है"],mPen:["✏️ Draw","✏️ बनाएँ"],mCircle:["⭕ Circle","⭕ गोला"],mArrow:["➜ Arrow","➜ तीर"],mUndo:["↶ Undo","↶ वापस"],mDone:["✓ Use photo","✓ फ़ोटो लगाएँ"],mSkip:["Skip marking","बिना निशान"],
 mDel:["Delete","हटाएँ"],mWaiting:["Waiting for network – will upload","नेटवर्क का इंतज़ार – अपलोड होगा"],mAdded:["Attached","जोड़ा गया"],mOpenPdf:["Open document","दस्तावेज़ खोलें"]});
const MEDIA_MAX_MB=40,VIDEO_MAX_S=60,IMG_MAX=1600;
/* ---------- local blob store ---------- */
const MDB=(()=>{let dbp=null;const open=()=>dbp||(dbp=new Promise((res,rej)=>{const r=indexedDB.open("drs-media",1);r.onupgradeneeded=()=>r.result.createObjectStore("blobs");r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)}));
 const tx=(mode,fn)=>open().then(db=>new Promise((res,rej)=>{const t0=db.transaction("blobs",mode);const st=t0.objectStore("blobs");const q=fn(st);t0.oncomplete=()=>res(q&&q.result);t0.onerror=()=>rej(t0.error)}));
 return {put:(id,b)=>tx("readwrite",s=>s.put(b,id)),get:id=>tx("readonly",s=>s.get(id)),del:id=>tx("readwrite",s=>s.delete(id))}})();
const MMETA=()=>store.get("kc-media",{});const mmSave=M=>store.set("kc-media",M);
const mItems=ref=>(MMETA()[ref]||[]);
const mIcon=it=>it.type==="video"?"🎥":it.type==="pdf"?"📄":"🖼";
function thumbs(ref,edit){return mItems(ref).map(it=>`<button class="mth" data-mview="${esc(ref)}|${it.id}" aria-label="${esc(it.name)}">${it.type==="image"?`<img data-mid="${it.id}" alt="">`:it.type==="video"?`<video data-mid="${it.id}" muted playsinline preload="metadata"></video>`:mIcon(it)}${it.pending?`<span class="del" title="${t("mWaiting")}">⏳</span>`:""}</button>`).join("")}
function mediaBox(ref){return `<div class="mbox" data-mref="${esc(ref)}"><div class="media">${thumbs(ref,true)}</div><div class="mbtns"><button type="button" class="mbtn" data-madd="photo">${t("mPhoto")}</button><button type="button" class="mbtn" data-madd="video">${t("mVideo")}</button><button type="button" class="mbtn" data-madd="doc">${t("mDoc")}</button></div><p class="counter" style="margin:4px 0 0">${t("mOptional")}</p></div>`}
function mediaStrip(ref){return mItems(ref).length?`<div class="mbox ro" data-mref="${esc(ref)}"><div class="media">${thumbs(ref)}</div></div>`:""}
function refreshBoxes(ref){document.querySelectorAll(`.mbox[data-mref="${CSS.escape(ref)}"] .media`).forEach(m=>m.innerHTML=thumbs(ref))}
function moveMedia(from,to){const M=MMETA();if(!M[from])return;M[to]=[...(M[to]||[]),...M[from]];delete M[from];mmSave(M)}
/* load thumbnails lazily */
const _urlCache={};
async function urlFor(it){if(it.url)return it.url;if(_urlCache[it.id])return _urlCache[it.id];const b=await MDB.get(it.id);if(!b)return null;return _urlCache[it.id]=URL.createObjectURL(b)}
function findItem(id){const M=MMETA();for(const r in M){const it=M[r].find(x=>x.id===id);if(it)return it}return null}
new MutationObserver(()=>{document.querySelectorAll("[data-mid]:not([data-loaded])").forEach(el=>{el.setAttribute("data-loaded","1");const it=findItem(el.dataset.mid);if(it)urlFor(it).then(u=>{if(u)el.src=u})})}).observe(document.body,{childList:true,subtree:true});
/* ---------- picking files ---------- */
let mPickRef=null;const picker=document.createElement("input");picker.type="file";picker.hidden=true;document.body.appendChild(picker);
document.addEventListener("click",e=>{const b=e.target.closest("[data-madd]");if(!b)return;mPickRef=b.closest(".mbox").dataset.mref;const k=b.dataset.madd;
 picker.accept=k==="photo"?"image/*":k==="video"?"video/*":"application/pdf,image/*";if(k==="doc")picker.removeAttribute("capture");else picker.setAttribute("capture","environment");picker.dataset.kind=k;picker.value="";picker.click()});
picker.addEventListener("change",async()=>{const f=picker.files[0];if(!f||!mPickRef)return;const kind=picker.dataset.kind;
 if(f.size>MEDIA_MAX_MB*1048576){toast(t("mTooBig"));return}
 if(kind==="video"||f.type.startsWith("video/")){const ok=await new Promise(res=>{const v=document.createElement("video");v.preload="metadata";v.onloadedmetadata=()=>{URL.revokeObjectURL(v.src);res(!(v.duration>VIDEO_MAX_S+0.5))};v.onerror=()=>res(true);v.src=URL.createObjectURL(f)});if(!ok){toast(t("mTooLong"));return}return addMedia(mPickRef,f,"video",f.name)}
 if(f.type==="application/pdf")return addMedia(mPickRef,f,"pdf",f.name);
 const img=await compressImg(f);openMarkup(img,mPickRef,f.name)});
function compressImg(f){return new Promise(res=>{const im=new Image();im.onload=()=>{const sc=Math.min(1,IMG_MAX/Math.max(im.width,im.height));const c=document.createElement("canvas");c.width=Math.round(im.width*sc);c.height=Math.round(im.height*sc);c.getContext("2d").drawImage(im,0,0,c.width,c.height);URL.revokeObjectURL(im.src);res(c)};im.onerror=()=>res(null);im.src=URL.createObjectURL(f)})}
async function addMedia(ref,blob,type,name){const id="MD"+Date.now()+Math.floor(Math.random()*999);const meta={id,type,name:name||type,size:blob.size,mime:blob.type,by:ME?ME.uid:"",byName:ME?ME.name:"",at:NOW()};
 await MDB.put(id,blob);if(window.DRS_MEDIA_UPLOAD){meta.pending=true}const M=MMETA();(M[ref]=M[ref]||[]).push(meta);mmSave(M);refreshBoxes(ref);toast(t("mAdded"));uploadPending()}
let _upBusy=false;async function uploadPending(){if(!window.DRS_MEDIA_UPLOAD||_upBusy)return;_upBusy=true;try{const M=MMETA();let ch=false;for(const ref in M)for(const it of M[ref]){if(!it.pending)continue;try{const b=await MDB.get(it.id);if(!b){it.pending=false;continue}it.url=await window.DRS_MEDIA_UPLOAD(b,{...it,ref,site:SITE});it.pending=false;ch=true}catch(e){/* offline: retry later */}}
 if(ch){const cur0=MMETA();for(const ref in M)for(const it of M[ref]){const c=(cur0[ref]||[]).find(x=>x.id===it.id);if(c){c.url=it.url;c.pending=it.pending}}mmSave(cur0);document.querySelectorAll(".mbox").forEach(b=>refreshBoxes(b.dataset.mref))}}finally{_upBusy=false}}
setInterval(uploadPending,30000);window.addEventListener("online",uploadPending);
/* ---------- mark-up editor ---------- */
function openMarkup(cv,ref,name){if(!cv){toast(t("mTooBig"));return}const ov=document.createElement("div");ov.className="mview";ov.innerHTML=`<canvas></canvas><div class="mtools"><button data-tool="pen" aria-pressed="true">${t("mPen")}</button><button data-tool="circle">${t("mCircle")}</button><button data-tool="arrow">${t("mArrow")}</button><button data-mk="undo">${t("mUndo")}</button></div><div class="mtools"><button data-mk="done" style="background:#006D35;color:#fff">${t("mDone")}</button><button data-mk="cancel">${t("cancel")}</button></div>`;document.body.appendChild(ov);
 const c=ov.querySelector("canvas");c.width=cv.width;c.height=cv.height;const g=c.getContext("2d");const base=cv;let tool="pen",shapes=[],cur0=null;
 const draw=()=>{g.drawImage(base,0,0);g.lineWidth=Math.max(4,c.width/180);g.strokeStyle="#D42A4A";g.lineCap="round";g.lineJoin="round";shapes.concat(cur0?[cur0]:[]).forEach(s=>{g.beginPath();if(s.t==="pen"){s.p.forEach((p,i)=>i?g.lineTo(p[0],p[1]):g.moveTo(p[0],p[1]))}else if(s.t==="circle"){const rx=Math.abs(s.b[0]-s.a[0])/2,ry=Math.abs(s.b[1]-s.a[1])/2;g.ellipse((s.a[0]+s.b[0])/2,(s.a[1]+s.b[1])/2,rx||1,ry||1,0,0,7)}else{g.moveTo(s.a[0],s.a[1]);g.lineTo(s.b[0],s.b[1]);const an=Math.atan2(s.b[1]-s.a[1],s.b[0]-s.a[0]),L=g.lineWidth*4;g.moveTo(s.b[0],s.b[1]);g.lineTo(s.b[0]-L*Math.cos(an-.5),s.b[1]-L*Math.sin(an-.5));g.moveTo(s.b[0],s.b[1]);g.lineTo(s.b[0]-L*Math.cos(an+.5),s.b[1]-L*Math.sin(an+.5))}g.stroke()})};draw();
 const pos=e=>{const r=c.getBoundingClientRect();const p=e.touches?e.touches[0]:e;return [(p.clientX-r.left)*c.width/r.width,(p.clientY-r.top)*c.height/r.height]};
 const down=e=>{e.preventDefault();const p=pos(e);cur0=tool==="pen"?{t:"pen",p:[p]}:{t:tool,a:p,b:p};draw()},move=e=>{if(!cur0)return;e.preventDefault();const p=pos(e);if(cur0.t==="pen")cur0.p.push(p);else cur0.b=p;draw()},up=()=>{if(cur0){shapes.push(cur0);cur0=null;draw()}};
 c.addEventListener("pointerdown",down);c.addEventListener("pointermove",move);window.addEventListener("pointerup",up);
 ov.addEventListener("click",e=>{const b=e.target.closest("button");if(!b)return;if(b.dataset.tool){tool=b.dataset.tool;ov.querySelectorAll("[data-tool]").forEach(x=>x.setAttribute("aria-pressed",x===b))}
  if(b.dataset.mk==="undo"){shapes.pop();draw()}if(b.dataset.mk==="cancel"){ov.remove();window.removeEventListener("pointerup",up)}
  if(b.dataset.mk==="done"){draw();c.toBlob(bl=>{addMedia(ref,bl,"image",(name||"photo").replace(/\.\w+$/,"")+".jpg");ov.remove();window.removeEventListener("pointerup",up)},"image/jpeg",0.82)}})}
/* ---------- viewer ---------- */
document.addEventListener("click",async e=>{const b=e.target.closest("[data-mview]");if(!b)return;const [ref,id]=b.dataset.mview.split("|");const it=mItems(ref).find(x=>x.id===id);if(!it)return;const u=await urlFor(it);
 const ov=document.createElement("div");ov.className="mview";const mine=ME&&it.by===ME.uid&&!b.closest(".ro");
 ov.innerHTML=`${it.type==="image"?`<img src="${u}" alt="">`:it.type==="video"?`<video src="${u}" controls playsinline autoplay></video>`:`<a class="btn" href="${u}" target="_blank" rel="noopener">${t("mOpenPdf")}</a>`}<p style="color:#fff;font-size:.85rem">${esc(it.name)} · ${esc(it.byName||"")} · ${hm(it.at)}</p><div class="mtools">${mine?`<button data-mdel="1">${t("mDel")}</button>`:""}<button data-mclose="1">${t("close")}</button></div>`;document.body.appendChild(ov);
 ov.addEventListener("click",async ev=>{if(ev.target.dataset.mclose||ev.target===ov)ov.remove();if(ev.target.dataset.mdel){const M=MMETA();M[ref]=(M[ref]||[]).filter(x=>x.id!==id);mmSave(M);await MDB.del(id).catch(()=>{});ov.remove();refreshBoxes(ref)}})});

/* ---------- where media can be attached ---------- */
