function hseed(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return ()=>{h=Math.imul(h^h>>>15,2246822507);h=Math.imul(h^h>>>13,3266489909);return ((h^=h>>>16)>>>0)/4294967296}}
function histDay(site,d){if(!window.ANTS.demo||d>=TODAY)return {opened:0,closed:0,ontime:0,births:0,deaths:0,inc:0,att:null,esc:0};const r=hseed(site+d);const opened=Math.floor(r()*4),closed=Math.min(opened+1,Math.floor(r()*4));
 return {opened,closed,ontime:Math.round(closed*(.6+r()*.4)),births:r()<.08?1+Math.floor(r()*2):0,deaths:r()<.025?1:0,inc:r()<.04?1:0,att:Math.round(86+r()*12),esc:r()<.07?1:0}}
function liveDay(site,d){const IS=storeAt.get(site,"kc-issues",[]);const day=ts=>ts?new Date(ts).toISOString().slice(0,10):"";const closedT=x=>(x.hist||[]).filter(h=>h.st==="closed").map(h=>h.at).pop();
 const V=storeAt.get(site,"kc-verify",[]).filter(v=>v.status==="recorded"&&v.date===d);const att=storeAt.get(site,"kc-att",{})[d]||{};const n=ORG.staff().filter(p=>p.site===site&&["keeper","sup"].includes(p.role)).length;
 const pres=Object.values(att).filter(r=>["Present","Late","Half day","On duty elsewhere"].includes(r.st)).length;
 return {opened:IS.filter(x=>day(x.times[0])===d).length,closed:IS.filter(x=>x.st==="closed"&&day(closedT(x))===d).length,ontime:IS.filter(x=>x.st==="closed"&&day(closedT(x))===d&&slaState(x).fixOk===true).length,
  births:V.filter(v=>v.type==="Birth").reduce((s,v)=>s+(v.payload&&v.payload.count||v.count||1),0),deaths:V.filter(v=>v.type==="Mortality").length,inc:storeAt.get(site,"kc-incidents",[]).filter(s=>s.date===d).length,att:Object.keys(att).length?Math.round(pres/Math.max(1,n)*100):null,esc:IS.filter(x=>(x.esc||[]).some(e=>day(e.at)===d)).length}}
function siteKpis(site,days){const tot={opened:0,closed:0,ontime:0,births:0,deaths:0,inc:0,esc:0,attS:0,attN:0};days.forEach(d=>{const a=histDay(site,d),b=liveDay(site,d);["opened","closed","ontime","births","deaths","inc","esc"].forEach(k=>tot[k]+=a[k]+b[k]);const at=b.att!=null?b.att:a.att;if(at!=null){tot.attS+=at;tot.attN++}});
 const IS=storeAt.get(site,"kc-issues",[]);const hist=window.ANTS.demo?Math.floor(hseed(site+"open")()*6):0;
 tot.open=IS.filter(x=>x.st!=="closed").length+hist;tot.breach=IS.filter(x=>x.st!=="closed"&&slaState(x).breach).length;tot.att=tot.attN?Math.round(tot.attS/tot.attN):null;tot.ontimePct=tot.closed?Math.round(tot.ontime/tot.closed*100):null;
 tot.sos=storeAt.get(site,"kc-sos",[]).filter(s=>s.status!=="resolved").length;tot.pendR=NTS().filter(n=>!n.closed).reduce((s,n)=>s+(n.targets||[]).filter(u=>{const p=ORG.user(u);return p&&p.site===site&&!(n.resp&&n.resp[u])}).length,0);return tot}
const perDays=()=>{const n=xPer==="1"?1:+xPer;return [...Array(n)].map((_,i)=>addDays(TODAY,i-n+1))};
function sumK(list){const s={opened:0,closed:0,ontime:0,births:0,deaths:0,inc:0,esc:0,open:0,breach:0,sos:0,pendR:0,attS:0,attN:0};list.forEach(k=>{Object.keys(s).forEach(x=>{if(x==="attS"){if(k.att!=null){s.attS+=k.att;s.attN++}}else if(x!=="attN")s[x]+=k[x]||0})});s.att=s.attN?Math.round(s.attS/s.attN):null;s.ontimePct=s.closed?Math.round(s.ontime/s.closed*100):null;return s}
const kpiTiles=k=>[["kOpenT",k.open,k.breach?"hot":""],["kOnTime",k.ontimePct!=null?k.ontimePct+"%":"–",k.ontimePct!=null&&k.ontimePct<70?"hot":"ok"],["kEsc",k.esc,k.esc?"hot":""],["kBirths",k.births,"ok"],["kDeaths",k.deaths,k.deaths?"hot":""],["kAtt",k.att!=null?k.att+"%":"–",k.att!=null&&k.att<85?"hot":""],["kInc",k.inc,k.inc?"hot":""],["kPendR",k.pendR,k.pendR?"hot":""],["kSos",k.sos,k.sos?"hot":""]];
