/* ---------- AI summary ---------- */
function summaryFacts(site){const sites=site?[site]:ORG.scopeSites(ME);const days=perDays();const k=sumK(sites.map(s=>siteKpis(s,days)));const worst=sites.map(s=>({s,k:siteKpis(s,days)})).sort((a,b)=>(b.k.breach+b.k.esc*2+b.k.deaths*3)-(a.k.breach+a.k.esc*2+a.k.deaths*3)).slice(0,3);
 return {scope:site||(["ch","siteadmin"].includes(ROLE)?"Cluster "+ME.cluster:"All clusters"),period:xPer==="1"?"today":xPer+" days",sites:sites.length,...k,worst:worst.map(w=>({site:w.s,open:w.k.open,breach:w.k.breach,esc:w.k.esc,deaths:w.k.deaths}))}}
function offlineSummary(f){const L=[];L.push(`${f.scope}, ${f.period}: ${f.opened} complaints opened and ${f.closed} closed${f.ontimePct!=null?` (${f.ontimePct}% fixed on time)`:""}; ${f.open} still open${f.breach?`, ${f.breach} past their time target`:""}.`);
 if(f.births||f.deaths)L.push(`Animals: ${f.births} birth${f.births===1?"":"s"} and ${f.deaths} death${f.deaths===1?"":"s"} recorded in ANTS.`);
 if(f.att!=null)L.push(`Average attendance ${f.att}%.`);if(f.inc)L.push(`${f.inc} incident${f.inc>1?"s":""} reported.`);if(f.sos)L.push(`⚠ ${f.sos} SOS alert${f.sos>1?"s":""} still open.`);if(f.pendR)L.push(`${f.pendR} compulsory notice replies are pending.`);
 const w=f.worst.filter(x=>x.breach||x.esc||x.deaths);if(w.length)L.push(`Needs attention first: ${w.map(x=>`${x.site} (${[x.breach&&x.breach+" late tickets",x.esc&&x.esc+" escalations",x.deaths&&x.deaths+" deaths"].filter(Boolean).join(", ")})`).join("; ")}.`);return L.join(" ")}
let aiText=null;
function rAiBox(site){const el=$("aiBox");if(!el)return;el.innerHTML=`<div class="aibox"><b>✨ ${t("aiH")}</b><p id="aiOut" style="margin:6px 0">${aiText?esc(aiText):`<span class="counter">${t("aiOffline")}: </span>${esc(offlineSummary(summaryFacts(site)))}`}</p><button class="x" id="aiGo" data-aisite="${site||""}">${t("aiGo")}</button></div>`}
document.addEventListener("click",async e=>{if(e.target.id!=="aiGo")return;const site=e.target.dataset.aisite||null;const f=summaryFacts(site);const out=$("aiOut");out.textContent=t("aiBusy");
 try{let txt=null;if(window.DRS_AI_SUMMARY)txt=await window.DRS_AI_SUMMARY(f);else{const s=window.claude&&claude.use?await claude.use("sample"):null;if(s){const r=await s(`You are writing a short daily operations summary for the leadership of a large zoo and animal rescue organisation. Use plain, calm English, 3–5 sentences, no headings, no invented facts. Mention what needs attention first. Data (JSON): ${JSON.stringify(f)}`,{modelTier:"quick"});txt=r.text}}
  aiText=txt||offlineSummary(f);out.textContent=aiText}catch(err){out.textContent=offlineSummary(f)}});

/* =====================================================================
   ENGINE 18 — Platform: archive, installable app, ANTS login mode
   • Archive: closed tickets older than 60 days move to monthly keys
     (kc-issues-arch-YYMM) so everyday lists stay small at 5,000+ users.
   • Installable DRS app: manifest + service worker (web/app/), own icon,
     works offline, Android + iPhone "Add to Home screen" or a store wrapper.
   • ANTS login mode: when the DRS app is opened outside ANTS (keepers, agencies)
     window.DRS_LOGIN (set by the connector) shows an EP-number + password screen
     checked by ANTS. Opened from inside ANTS, the ANTS token signs in automatically.
   ===================================================================== */
Object.assign(I,{loginH:["Sign in to DRS","DRS में साइन इन"],loginP:["Use your employee number and PIN.","अपना कर्मचारी नंबर और PIN डालें।"],loginEp:["Employee number (EP)","कर्मचारी नंबर (EP)"],loginPw:["PIN","PIN"],loginBio:["Sign in with face or fingerprint","चेहरे या फ़िंगरप्रिंट से साइन इन"],resetPin:["Reset PIN","PIN रीसेट"],loginGo:["Sign in","साइन इन"],loginBad:["Wrong employee number or PIN","गलत नंबर या PIN"],loginBusy:["Signing in…","साइन इन हो रहा है…"],
 archived:["Older closed tickets are kept in monthly archives.","पुराने बंद टिकट मासिक संग्रह में रखे जाते हैं।"]});
/* ---------- monthly archive ---------- */
const ARCH_DAYS=60;
function archiveTickets(){const is=store.get("kc-issues",[]);const cut=NOW()-ARCH_DAYS*864e5;const keep=[],move={};
 is.forEach(x=>{const cl=x.st==="closed"?((x.hist||[]).filter(h=>h.st==="closed").map(h=>h.at).pop()||0):0;if(cl&&cl<cut){const k="kc-issues-arch-"+new Date(x.times[0]).toISOString().slice(2,7).replace("-","");(move[k]=move[k]||[]).push(x)}else keep.push(x)});
 if(!Object.keys(move).length)return 0;Object.entries(move).forEach(([k,L])=>store.set(k,[...store.get(k,[]),...L]));store.set("kc-issues",keep);issues=keep;return Object.values(move).flat().length}
if(ME&&["afm","mgr"].includes(ROLE))setTimeout(archiveTickets,3000);
/* ticket sheets read the archive for the chosen month/year as well */
const _sheetRows18=sheetRows;sheetRows=function(all){const y=$("shY")&&$("shY").checked;const sites=[...new Set(all.map(x=>x._site||SITE))];const yy=shM.slice(2,4),mm=shM.slice(5,7);
 const months=y?[...Array(12)].map((_,i)=>yy+String(i+1).padStart(2,"0")):[yy+mm];const extra=sites.flatMap(s=>months.flatMap(m=>storeAt.get(s,"kc-issues-arch-"+m,[]).map(x=>({...x,_site:s}))));return _sheetRows18([...all,...extra])};
/* ---------- installable app (only when served over http/https with the app files) ---------- */
