/* =====================================================================
   ENGINE 19 — "Send now" for urgent animal events + instant delivery
   • Supervisor events (birth, mortality, sick, escape…) are no longer half-sent while
     typing. Each event has a big "Send now" button: one tap sends it at once to the Vet,
     Curators, Biologist, Paravet and Manager (pop-up + push) — no waiting for the evening report.
     After sending, the card shows "✓ Sent at 12:41" and who has seen it. If the event is changed
     later, "Send update" sends the new details and pops up again for everyone.
   • window.DRS_URGENT(keys): the connector calls it the moment alerts / tickets / notices
     arrive from another phone, so pop-ups and red banners appear even while the person is busy.
   • window.DRS_FLUSH(): connectors send queued saves immediately (used by Send now).
   ===================================================================== */
Object.assign(I,{evSendNow:["🚨 Send now to Vet, Curators, Biologist and Manager","🚨 अभी वेट, क्यूरेटर, बायोलॉजिस्ट और मैनेजर को भेजें"],
 evSendUpd:["🔁 Send update","🔁 अपडेट भेजें"],evSentAt:["✓ Sent at {t}","✓ {t} पर भेजा गया"],evSentWho:["Vet, Curators, Biologist, Paravet and Manager were notified.","वेट, क्यूरेटर, बायोलॉजिस्ट, पैरावेट और मैनेजर को सूचना गई।"],
 evChanged:["Changed after sending — tap Send update so everyone sees the new details.","भेजने के बाद बदला गया — सबको नई जानकारी दिखे, इसलिए अपडेट भेजें।"],evPickType:["Choose the type of event first","पहले घटना का प्रकार चुनें"],
 evSentToast:["Sent — everyone concerned has been notified","भेजा गया — सभी संबंधित लोगों को सूचना गई"],evSeenBy:["Seen by","देखा"],evNobody:["not seen yet","अभी किसी ने नहीं देखा"],
 evHint:["Urgent events go out the moment you tap Send now — you don't wait for the evening report.","ज़रूरी घटनाएँ 'अभी भेजें' दबाते ही चली जाती हैं — शाम की रिपोर्ट का इंतज़ार नहीं।"],evNotSent:["Not sent yet","अभी नहीं भेजा"],
 alUpdated:["Updated","अपडेट"],
 alP:["Births, deaths, injuries and other animal events reach the Biologist, Curators, Vet and Manager the moment the supervisor taps Send now.","जन्म, मृत्यु, चोट और दूसरी घटनाएँ सुपरवाइज़र के 'अभी भेजें' दबाते ही बायोलॉजिस्ट, क्यूरेटर, वेट और मैनेजर तक पहुँचती हैं।"]});
const EV_KEYS=["type","species","cage","count","details","time"];
const evSnap=ev=>Object.fromEntries(EV_KEYS.map(k=>[k,ev[k]==null?"":String(ev[k])]));
const evChanged=ev=>!!ev.sent&&EV_KEYS.some(k=>String(ev[k]==null?"":ev[k])!==String(ev.sent[k]==null?"":ev.sent[k]));
const EV_BAD=["Mortality","Sick / injured","Staff injury / bite","Escape / near-miss","Under treatment","Behaviour concern"];
/* only events that were sent create alerts, and they carry what was sent (not what is being typed) */
const _cur19=currentAlerts;
currentAlerts=function(){return _cur19().filter(a=>{const m=/^sup:[\d-]+:(\d+)$/.exec(a.id);if(!m)return true;const ev=(S.events||[])[+m[1]];if(!ev||!ev.sentAt||!ev.sent)return false;
 const s=ev.sent;Object.assign(a,{type:s.type,animal:s.species||"",cage:s.cage||"",count:s.count||"",details:s.details||"",time:s.time||""});return true})};
/* an updated alert pops up again for everyone */
const _sync19=syncAlerts;
syncAlerts=function(){const before=JSON.parse(JSON.stringify(store.get("kc-alerts",{})));_sync19();const A=store.get("kc-alerts",{});let ch=false;
 Object.values(A).forEach(a=>{const o=before[a.id];if(!o)return;const k=["type","animal","cage","count","details","time"];if(k.some(f=>o[f]!==a[f])){a.upd=(o.upd||0)+1;a.updAt=NOW();a.seen={[a.from==="sup"?"sup":a.from]:1};ch=true;
  notify({type:"animal_alert",title:`${t("alUpdated")}: ${a.type}${a.animal?": "+a.animal:""}`,body:[a.cage,a.details].filter(Boolean).join(" – "),toRoles:AL_TO,ref:a.id+"#"+a.upd,priority:["Mortality","Escape / near-miss"].includes(a.type)?"critical":"high"})}});
 if(ch){store.set("kc-alerts",A);ALERTS=A;try{rAlertBox()}catch(e){}}};
/* pop-ups: never lost while another sheet is open; updates pop up again */
alertPopup=function(){if(!AL_TO.includes(ROLE))return;if(!$("repSheet").hidden)return;const k="kc-alpop-"+ROLE,popped=store.get(k,[]);const tag=a=>a.id+(a.upd?"#"+a.upd:"");
 const fresh=unseen().filter(a=>!popped.includes(tag(a)));if(!fresh.length)return;store.set(k,[...popped,...fresh.map(tag)].slice(-400));try{navigator.vibrate&&navigator.vibrate([150,80,150])}catch(e){}openAlerts()};
/* the Send now / Sent footer on each event card */
function evFootHTML(i){const ev=(S.events||[])[i];if(!ev)return "";const bad=EV_BAD.includes(ev.type);
 if(!ev.sentAt)return `<div class="evfoot" data-evf="${i}"><p class="counter" style="margin:0 0 6px">${t("evNotSent")}</p><button class="sendnow${bad?" bad":""}" data-evsend="${i}">${t("evSendNow")}</button></div>`;
 const id=(meId()==="local"?"":meId()+"/")+`sup:${TODAY}:${i}`;const a=store.get("kc-alerts",{})[id];const seen=a?AL_TO.filter(r=>(a.seen||{})[r]).map(r=>L2(ROLE_LABEL[r])):[];
 return `<div class="evfoot" data-evf="${i}"><p class="sentok">${t("evSentAt",{t:new Date(ev.sentAt).toLocaleTimeString([],{hour:"2-digit",minute:"2-digit"})})} · ${t("evSentWho")}</p>
 <p class="counter" style="margin:2px 0 0">${t("evSeenBy")}: ${seen.length?esc(seen.join(", ")):t("evNobody")}</p>
 ${evChanged(ev)?`<p class="counter over" style="margin:6px 0">${t("evChanged")}</p><button class="sendnow${bad?" bad":""}" data-evsend="${i}">${t("evSendUpd")}</button>`:""}</div>`}
function evFoot(i){const box=document.querySelectorAll("#events > .box")[i];if(!box)return;const old=box.querySelector(".evfoot");const h=evFootHTML(i);if(old)old.outerHTML=h;else box.insertAdjacentHTML("beforeend",h)}
const _renderEvents19=renderEvents;renderEvents=function(){_renderEvents19();const m=document.querySelector("#events > .okmsg");if(m)m.textContent="🚨 "+t("evHint");(S.events||[]).forEach((_,i)=>evFoot(i))};
$("events").addEventListener("input",e=>{const i=e.target.dataset&&e.target.dataset.ev;if(i!=null)setTimeout(()=>evFoot(+i),0)});
document.addEventListener("click",e=>{const b=e.target.closest("[data-evsend]");if(!b)return;const i=+b.dataset.evsend;const ev=(S.events||[])[i];if(!ev)return;
 if(!ev.type){toast(t("evPickType"));return}
 ev.sent=evSnap(ev);ev.sentAt=NOW();ev.sentBy=ME?ME.uid:"";save();try{status()}catch(x){}syncAlerts();evFoot(i);
 try{window.DRS_FLUSH&&window.DRS_FLUSH()}catch(x){}toast(t("evSentToast"))});
/* events sent earlier keep their "sent" state; old reports from before this version count as sent */
(function(){try{if(!S||!S.events)return;let ch=false;const A=store.get("kc-alerts",{});S.events.forEach((ev,i)=>{const id=(meId()==="local"?"":meId()+"/")+`sup:${TODAY}:${i}`;if(!ev.sentAt&&A[id]){ev.sent=evSnap(ev);ev.sentAt=A[id].at||NOW();ch=true}});if(ch)save()}catch(e){}})();
/* instant delivery from other phones */
window.DRS_URGENT=function(keys){keys=keys||[];
 try{ALERTS=store.get("kc-alerts",{});rAlertBox();if(!typingNow())alertPopup()}catch(e){}
 try{if(keys.some(k=>/kc-issues$/.test(k))){issues=store.get("kc-issues",[]);if(!typingNow()){afmPopup();if(typeof agencyPopup==="function")agencyPopup()}}}catch(e){}
 try{rNoticeBar()}catch(e){}try{addBadges()}catch(e){}
 try{if(VIEW==="sup")(S.events||[]).forEach((_,i)=>evFoot(i))}catch(e){}};
/* fallback: keep checking every few seconds (covers updates and anything a connector missed) */
setInterval(()=>{try{const A=store.get("kc-alerts",{});if(JSON.stringify(A)!==JSON.stringify(ALERTS)){ALERTS=A;rAlertBox();if(VIEW==="sup")(S.events||[]).forEach((_,i)=>evFoot(i))}if(!typingNow())alertPopup()}catch(e){}},4000);
/* SOS is an emergency: show it at once (within 5 s, or the moment it arrives), even over another open sheet */
function sosNow(){try{if(!ME||!["sup","mgr","vet"].includes(ME.role))return;const open=SOSL().filter(s=>s.status==="open");const seen=store.get("kc-sos-seen",[]);
 if(open.some(s=>!seen.includes(s.id))&&!$("repSheet").hidden&&!document.querySelector("#repSheet .sospop"))$("repSheet").hidden=true;sosTick()}catch(e){}}
setInterval(sosNow,5000);
const _urg19=window.DRS_URGENT;window.DRS_URGENT=function(keys){_urg19(keys);if((keys||[]).some(k=>/kc-(sos|checkin)$/.test(k)))sosNow()};

